local config = {
  ui_story_5022_50220101_1_dialog_content = "Nng… Vice…",
  ui_story_5022_50220101_2_dialog_content = "Vice… Aku membutuhkanmu…",
  ui_story_5022_50220101_3_dialog_content = "(Kalau saja dulu aku minta maaf padanya…)",
  ui_story_5022_50220101_4_dialog_content = "<color=#e8d9bb>Beberapa hari lalu…</color>",
  ui_story_5022_50220101_5_dialog_content = "<size=45>Rasakan ini!</size>",
  ui_story_5022_50220101_6_dialog_content = "Waow, kapan kau…?! Teknik menyudutkan macam apa itu?!",
  ui_story_5022_50220101_7_dialog_content = "Heh, aku masih punya banyak strategi, tahu? Garis finisnya tinggal setengah jalan… Aku pasti akan memenangkan balapan ini!",
  ui_story_5022_50220101_8_dialog_content = "Wah, mau tak mau aku harus memujimu. Permainan balapan itu benar-benar berguna… Akan tetapi, masih terlalu dini untuk merayakan keberhasilanmu, bocah tengil!",
  ui_story_5022_50220101_9_dialog_content = "Benar! Saatnya menunjukkan teknik balapan rahasia Rediesel Wrench—",
  ui_story_5022_50220101_10_dialog_content = "… Oh!",
  ui_story_5022_50220101_11_dialog_content = "V-Vice? Kenapa kaumatikan terminalnya, sih?! Aku kan sudah hampir menang…",
  ui_story_5022_50220101_12_dialog_content = "Apa benar-benar perlu kujelaskan?",
  ui_story_5022_50220101_13_dialog_content = "Mengesampingkan fakta bahwa Anda bermain dengan program pelatihan Colossus seperti video game ... Apakah Anda benar-benar lupa tentang daftar ini ?!",
  ui_story_5022_50220101_14_dialog_content = "Daftar apa? Biar kulihat… \"Program Olahraga Mandiri\"?",
  ui_story_5022_50220101_15_dialog_content = "\"Pagi: 100 push-up. Siang: 100 sit-up. Sore: 100 squat. Lari jarak jauh setiap hari…\"",
  ui_story_5022_50220101_16_dialog_content = "Astaga, itu rencana ambisius yang kau punya di sana, Nak...",
  ui_story_5022_50220101_17_dialog_content = "Nah, PlayerName, sudah berapa banyak dari daftar itu yang kaulakukan?",
  ui_story_5022_50220101_18_dialog_content = "Uh... Y-Yah, aku melakukan sit-up sore ini! Maksudku, secara teknis aku berbaring untuk waktu yang lama dan duduk sekali, tapi...",
  ui_story_5022_50220101_19_dialog_content = "Bangun tidur tidak masuk hitungan!",
  ui_story_5022_50220101_20_dialog_content = "Kau suka membuat rencana ambisius untuk diri sendiri, tapi setiap kali kuperiksa, kerjaanmu hanya bermain saja…",
  ui_story_5022_50220101_21_dialog_content = "Dari pagi sampai malam. Itu yang terus kaulakukan belakangan ini!",
  ui_story_5022_50220101_22_dialog_content = "I-iya juga sih, tapi… kalau dipikir-pikir, video game kan seperti latihan! Sekarang tanganku jadi kuat, waktu reaksiku juga sangat bagus!",
  ui_story_5022_50220101_23_dialog_content = "Iya, 'kan, Sinsa?",
  ui_story_5022_50220101_24_dialog_content = "I-iya, benar! Seharusnya kaulihat drift barusan! Sangat mantap!",
  ui_story_5022_50220101_25_dialog_content = "Ugh... Kau tahu?",
  ui_story_5022_50220101_26_dialog_content = "Jangan pernah minta bantuanku lagi! Mulai sekarang, lakukan saja sendiri!",
  ui_story_5022_50220101_27_dialog_content = "Mampus… Aku harus bagaimana kalau dia tak mau mengingatkanku tentang tugas-tugasku lagi? Kadang-kadang aku kan pelupa!",
  ui_story_5022_50220101_28_dialog_content = "Selain itu, orang dungu macam apa sih yang membuat rencana olahraga segila itu?!",
  ui_story_5022_50220101_29_dialog_content = "… Baiklah, benar, memang aku sendiri yang membuatnya.",
  ui_story_5022_50220101_30_dialog_content = "Sudah terlambat belum ya kalau aku minta maaf?",
  ui_story_5022_50220101_31_dialog_content = "Bagaimana kalau dia ingin menghukumku dengan menyuruhku untuk menyelesaikan olahragaku hari ini?",
  ui_story_5022_50220101_32_dialog_content = "Aku pasti mampus…",
  ui_story_5022_50220101_33_dialog_content = "Iya, sudah pasti.",
  ui_story_5022_50220101_34_dialog_content = "Begini, sekarang Vice sedang sangat marah. Bagaimana kalau kautunggu dia tenang dulu lalu minta maaf setelahnya? Siapa tahu? Mungkin dia mau memaafkanmu!",
  ui_story_5022_50220101_35_dialog_content = "Omonganmu ada benarnya… Sebentar, kenapa sepertinya hal semacam ini tidak asing bagimu?",
  ui_story_5022_50220101_36_dialog_content = "Heh, kalau punya adik, kau pasti tahu hal-hal seperti ini… Pokoknya, sekarang kau jangan dekat-dekat dia dulu.",
  ui_story_5022_50220101_37_dialog_content = "Namun, kita kan di Colossus… Memangnya aku harus ke mana?",
  ui_story_5022_50220101_38_dialog_content = "Tunggu, aku baru ingat! Ini sudah hampir saatnya!",
  ui_story_5022_50220101_39_dialog_content = "Hei, PlayerName… Mau lihat balapan sungguhan, tidak?",
  ui_story_5022_50220101_40_dialog_content = "Tak pernah kusangka ada yang seperti ini di gurun… Tempat apa ini?",
  ui_story_5022_50220101_41_dialog_content = "Selamat datang di <color=#FFB400>Oasis</color>, salah satu benteng utama Rediesel Wrench!",
  ui_story_5022_50220101_42_dialog_content = "Jarak pandang di sini cukup buruk, 'kan? Bahkan menggunakan Lepidoz pun jarak pandangnya kurang dari dua meter karena ada pasir dan angin… Nah, memang begitulah yang kami cari.",
  ui_story_5022_50220101_43_dialog_content = "Medan di sekitar sini cukup kompleks dan cuacanya juga tak bisa ditebak. Hanya kami yang tahu cara menemukan tempat ini.",
  ui_story_5022_50220101_44_dialog_content = "Yah, tapi kadang kami juga kesulitan menemukannya, sih…",
  ui_story_5022_50220101_45_dialog_content = "\"Oasis\"…",
  ui_story_5022_50220101_46_dialog_content = "Kaulihat bengkel di sebelah sana? Nah, di sanalah kami memperbaiki kendaraan dan senjata kalau perbaikan biasa tak berhasil.",
  ui_story_5022_50220101_47_dialog_content = "Lalu rumah pohon di sebelah sana sangat enak untuk dipakai tidur. Dindingnya mencegah pasir masuk ke baju dalammu, tapi tempat itu akan bergoyang-goyang kalau ada angin kencang.",
  ui_story_5022_50220101_48_dialog_content = "Kau juga bisa membeli keik kurma berpasir di sini. Pai kalajengking merahnya juga lumayan lezat, lo.",
  ui_story_5022_50220101_49_dialog_content = "Dan hanya ada dua puluh atau tiga puluh orang yang sakit setiap bulannya karena menyantapnya! Kalau mau, kau juga boleh mencoba peruntunganmu, kok. Oh, lalu yang di sebelah sana…",
  ui_story_5022_50220101_50_dialog_content = "Hei, Sinsa! Selamat datang kembali!",
  ui_story_5022_50220101_51_dialog_content = "Kami baru saja membongkar kiriman di Giant Lizard!",
  ui_story_5022_50220101_52_dialog_content = "Kudengar kali ini Azure yang memimpin jalannya. Hasilnya lumayan juga!",
  ui_story_5022_50220101_53_dialog_content = "Karena mereka sudah selesai menyusun stoknya, sekarang kami mau mengirimnya ke gudang. Mau lihat, Sinsa?",
  ui_story_5022_50220101_54_dialog_content = "Tidak, serahkan saja pada Roy. Omong-omong, apa kalian melihat dia di sekitar sini?",
  ui_story_5022_50220101_55_dialog_content = "—Wahai petualang gagah perkasa dari negeri nun jauh! Kulihat betapa beratnya beban takdir di pundakmu…",
  ui_story_5022_50220101_56_dialog_content = "Apa kau juga butuh tuntunan angin?",
  ui_story_5022_50220101_57_dialog_content = "Petualang…?",
  ui_story_5022_50220101_58_dialog_content = "Hei, Zeta! Sudah lama tak bertemu, ya? Masih suka berfantasi rupanya!",
  ui_story_5022_50220101_59_dialog_content = "B-berfantasi…?!",
  ui_story_5022_50220101_60_dialog_content = "Ah, aku paham sekarang…",
  ui_story_5022_50220101_61_dialog_content = "Rupanya setelah kita terpisahkan oleh takdir yang kejam, reaksi kekuatan Evil God membuatmu kehilangan ingatan dan lupa pada takdirmu…",
  ui_story_5022_50220101_62_dialog_content = "Namun, tenang saja. Ada aku di sini. Tak ada yang perlu ditakuti sekarang.",
  ui_story_5022_50220101_63_dialog_content = "Bangkitlah, wahai kesatria terkutuk! Bangkitlah, wahai prajurit kesepian yang pernah bercerai tiga kali, yang ditakdirkan untuk menjelajahi berbagai negeri tanpa memiliki kampung halaman!",
  ui_story_5022_50220101_64_dialog_content = "Hah…? Oh, kurasa itu masuk akal juga…",
  ui_story_5022_50220101_65_option_content = "\"Kesatria terkutuk\"?",
  ui_story_5022_50220101_66_dialog_content = "Ah, itu hanya bagian dari permainan fantasi Zeta. Dia menciptakan seorang tokoh untukku.",
  ui_story_5022_50220101_67_dialog_content = "Nah, dulu ceritanya bagaimana, ya…? Aku menjelajahi daratan untuk mencari kekuatan, lalu… pokoknya sesuatu soal rohku…",
  ui_story_5022_50220101_68_dialog_content = "Kau memasuki reruntuhan Ishradi dan menawarkan rohmu pada Evil God kuno, Y'noth-raz!",
  ui_story_5022_50220101_69_option_content = "Kau sudah bercerai tiga kali?",
  ui_story_5022_50220101_70_dialog_content = "\"Tidak!\"",
  ui_story_5022_50220101_71_dialog_content = "Itu hanya bagian dari, eh… Apa itu namanya? … Oh, iya! \"Permainan peran\"! Zeta menciptakan seorang tokoh untukku.",
  ui_story_5022_50220101_72_dialog_content = "Masalahnya, dia terus mengganti bagian-bagian ceritanya, jadi aku tidak yakin sekarang sudah sampai mana…",
  ui_story_5022_50220101_73_dialog_content = "Kau menjelajahi daratan untuk mencari kekuatan yang lebih besar. Sesampainya di reruntuhan Ishradi, kau menawarkan rohmu pada Evil God kuno, Y'noth-raz!",
  ui_story_5022_50220101_74_dialog_content = "Akan tetapi, tak lama kemudian, kau menyadari bahwa kekuatan itu terkutuk. Lalu, kau memulai perjalanan untuk mengalahkan si raja iblis…",
  ui_story_5022_50220101_75_dialog_content = "Oh, iya! Sekarang aku ingat!",
  ui_story_5022_50220101_76_dialog_content = "Syukurlah kau sudah sadar. Wahai prajurit gagah perkasa, bolehkah aku bertanya… Siapa orang yang berdiri di sebelahmu?",
  ui_story_5022_50220101_77_option_content = "S-salam kenal! Namaku PlayerName!",
  ui_story_5022_50220101_78_dialog_content = "Kaubilang PlayerName? Hmm… Aku bisa merasakan kekuatan kuno dan misterius yang tertidur dalam tubuhmu…",
  ui_story_5022_50220101_79_dialog_content = "Apa jangan-jangan karena aku Caelestite, ya? Kau pernah dengar tentang kami? Ras manusia yang bisa melihat Lumina dan memiloti Colossus besar!",
  ui_story_5022_50220101_80_option_content = "Aku Caelestite terakhir! Navigator Colossus dan penuntun cahaya!",
  ui_story_5022_50220101_81_dialog_content = "<size=45>C-Caelestite… Terakhir!!!</size>",
  ui_story_5022_50220101_82_dialog_content = "Gelar itu… Gelar itu kedengaran sangat keren!",
  ui_story_5022_50220101_83_dialog_content = "Jangan bilang begitu, ah! Aku jadi malu…",
  ui_story_5022_50220101_84_dialog_content = "Ehem… Maaf karena kehebohan yang tak perlu barusan.",
  ui_story_5022_50220101_85_dialog_content = "Sepertinya aku masih perlu banyak berlatih jika ingin menjadi penyelamat Astra.",
  ui_story_5022_50220101_86_dialog_content = "Izinkan aku memandumu ke tempat sang putri berada. Semoga angin menuntun kita…",
  ui_story_5022_50220101_87_dialog_content = "… Setelahnya kita tinggal menunggu saja. Aku akan segera mengirim kabar lewat Courier Union kalau ada perubahan.",
  ui_story_5022_50220101_88_dialog_content = "Tentu, tapi… yakin nih tidak butuh bantuan lebih banyak orang, Azure?",
  ui_story_5022_50220101_89_dialog_content = "Terakhir kali, orang-orang Umbraton itu benar-benar mengacau saat mereka terpengaruh obat…",
  ui_story_5022_50220101_90_dialog_content = "Jangan ungkit itu lagi… Sudah kubilang, aku lebih suka bekerja sendirian. Keberadaan orang lain hanya akan menggangguku.",
  ui_story_5022_50220101_91_dialog_content = "Berhentilah memperlakukanku seperti anak kecil.",
  ui_story_5022_50220101_92_dialog_content = "Iya, iya, aku tahu! Hanya saja…",
  ui_story_5022_50220101_93_dialog_content = "Tolong! Sepertinya ada yang salah dengan bom alarmku! Benda ini tak mau meledak seperti biasanya…",
  ui_story_5022_50220101_94_dialog_content = "Sini, biar kulihat… Tarik saja sumbunya seperti ini, lalu tepuk satu-dua kali, dan… Nah, sudah seperti baru lagi.",
  ui_story_5022_50220101_95_dialog_content = "Apa camilan untuk Lepidoz sudah sampai?",
  ui_story_5022_50220101_96_dialog_content = "Brock dan Fleur membantu pengantarannya. Kalau mereka belum sampai… Kemungkinan, Brock melahapnya saat tak ada orang yang melihat.",
  ui_story_5022_50220101_97_dialog_content = "Kalau memang begitu, umpankan saja Brock pada Lepidoz. Dia pasti tak akan keberatan dengan rasanya.",
  ui_story_5022_50220101_98_dialog_content = "Kita perlu memperluas gudang di Oasis! Aku hampir tak punya tempat lagi untuk menyimpan komponen mesin!",
  ui_story_5022_50220101_99_dialog_content = "Bagaimana kalau kaugantung saja beberapa komponenmu di langit-langit? Kita baru saja mendapat tali yang bagus dan kokoh. Itu, di sebelah sana.",
  ui_story_5022_50220101_100_dialog_content = "Kalau tidak, kau juga bisa menggunakan talinya untuk mengikat Jomu selama beberapa hari sampai dia mau menyisihkan ruang untukmu.",
  ui_story_5022_50220101_101_dialog_content = "Soal pengiriman dua hari lalu…",
  ui_story_5022_50220101_102_dialog_content = "Warehouse 6, dalam peti yang ditutupi kain terpal. Hati-hati, ya. Hewan-hewan kecil itu menggigit. Racunnya juga tidak main-main.",
  ui_story_5022_50220101_103_dialog_content = "Nah, soal suplai hari ini…",
  ui_story_5022_50220101_104_dialog_content = "Daftarnya ada di dinding sebelah sana. Nanti kulihat.",
  ui_story_5022_50220101_105_dialog_content = "Uh... Maaf Azure, Saya hampir tidak mendapat kesempatan untuk berbicara dengan Anda dan inilah saya ... Apa yang baru saja kita bicarakan?",
  ui_story_5022_50220101_106_dialog_content = "Putri! Kesatriamu yang terhormat sudah kembali!",
  ui_story_5022_50220101_107_dialog_content = "Sekarang aku jadi putri, ya…? Wah, makin rumit saja hari ini…",
  ui_story_5022_50220101_108_dialog_content = "Ehem… Terpujilah tuntunan angin karena telah membawamu kembali ke sisiku, kesatria yang mulia. Bagaimana dengan perselisihan di perbatasan kerajaan kita?",
  ui_story_5022_50220101_109_dialog_content = "Pasukan iblis telah berani menyerang di desa perbatasan, tapi jangan khawatir, Yang Mulia. Aku dan teman tepercayaku berhasil menyingkirkan para setan jahat itu.",
  ui_story_5022_50220101_110_dialog_content = "Sebagai ucapan terima kasih, gadis-gadis di desa itu menawarkan permen karena kami sudah melindungi mereka dari kejahatan.",
  ui_story_5022_50220101_111_dialog_content = "Aku mengerti… Kalau begitu, untuk saat ini Eclipsite sudah dikalahkan.",
  ui_story_5022_50220101_112_dialog_content = "Sejumlah desa bermunculan di daerah itu sejak kita sepakat untuk membantu melindungi sumber air setempat. Mungkinkah serangan Eclipsite ada hubungannya dengan ini…?",
  ui_story_5022_50220101_113_dialog_content = "Sepertinya ada yang sedang Yang Mulia risaukan. Ada yang bisa kubantu?",
  ui_story_5022_50220101_114_dialog_content = "Betapa hancurnya hatiku melihat wajah cantik dan rupawan ternoda oleh kesedihan…",
  ui_story_5022_50220101_115_dialog_content = "C-cantik…? Eh… Bantuanmu sudah lebih dari cukup, pahlawan pemberaniku.",
  ui_story_5022_50220101_116_dialog_content = "Hand of Fate memerintahkanmu untuk menghilangkan rasa penat akibat perjalanan dan menikmati istirahat yang memang pantas kaudapatkan. Kalau kau butuh bantuan untuk mengepang rambut, aku akan selalu siap melakukannya.",
  ui_story_5022_50220101_117_dialog_content = "Oho? Wah, hari ini kau jelas sudah merebut hati ibuku, Zeta! Lumayan juga!",
  ui_story_5022_50220101_X117_dialog_content = "Ibu… Maksudmu aku?",
  ui_story_5022_50220101_118_dialog_content = "—Pffffft!",
  ui_story_5022_50220101_119_dialog_content = "Huh… Pasti selalu begini setiap kali kalian bertemu…",
  ui_story_5022_50220101_120_dialog_content = "Baiklah, siapa yang butuh bantuan Ibu hari ini? Hmm? Siapa anak baru ini?",
  ui_story_5022_50220101_121_dialog_content = "Ya! Biar kuperkenalkan teman baru kita. Dia adalah PlayerName, sang Caelestite terakhir!",
  ui_story_5022_50220101_122_dialog_content = "Begitu rupanya… Salam kenal. Namaku Roy. Aku yang bertanggung jawab atas logistik dan perbaikan untuk Rediesel Wrench.",
  ui_story_5022_50220101_123_dialog_content = "Sinsa jarang mengajak temannya bermain di rumah… Caelestite terakhir, ya?",
  ui_story_5022_50220101_124_dialog_content = "Yah, teman pemimpin adalah teman kami juga, begitu pula dengan tamu terhormat di Rediesel Wrench. Selamat datang, PlayerName.",
  ui_story_5022_50220101_125_dialog_content = "Nah, kedatanganmu kemari pasti untuk menonton Blazing Rally, 'kan? Kalau begitu, sebaiknya kita mulai menyiapkan tempatnya.",
  ui_story_5022_50220101_126_dialog_content = "Berarti, kalian belum memutuskan mau mengadakan balapan di mana?!",
  ui_story_5022_50220101_127_dialog_content = "Benar. Meskipun ada banyak trek, lokasi balapannya baru diputuskan sehari sebelumnya.",
  ui_story_5022_50220101_128_dialog_content = "Selain itu, kadang lokasi balapannya malah jadi tempat Lumopolis menangkap kriminal buronan atau tempat Illumina menemukan kendaraan yang hilang…",
  ui_story_5022_50220101_129_dialog_content = "Meskipun selalu dibombardir, tentu saja ada saat-saat serunya.",
  ui_story_5022_50220101_130_dialog_content = "I-Kedengarannya menarik...",
  ui_story_5022_50220101_131_dialog_content = "(… Saking akrabnya dengan mereka, kadang aku lupa bahwa mereka adalah kawanan bandit yang suka keluyuran…)",
  ui_story_5022_50220101_132_dialog_content = "Ahaha! Ya, kami juga kedatangan tamu. Ayo jaga sikap. Ada ide, Pemimpin?",
  ui_story_5022_50220101_133_dialog_content = "Yah, kalau teman Caelestite kita ingin punya pengalaman baru, jawabannya tentu saja <color=#FFB400>Blazing Tooth</color>.",
  ui_story_5022_50220101_134_dialog_content = "Para penguasa lembek, tentara uzur, dan tentara bayaran itu mungkin tak mau repot-repot pergi ke gurun untuk menangkap kita.",
  ui_story_5022_50220101_135_dialog_content = "Tidak! Tempat itu sangat dekat dengan area patroliku. Tak pernah ada yang menang di sana. Membosankan!",
  ui_story_5022_50220101_136_dialog_content = "Cuacanya bagus. Bagaimana kalau kita pergi ke Nightmare Harbor di Gold River saja?",
  ui_story_5022_50220101_137_dialog_content = "Kalau tidak, kita pergi saja ke Green Hell di dekat Whispering Corridor. Kita buat orang-orang bodoh dari Umbraton itu jengkel!",
  ui_story_5022_50220101_138_dialog_content = "(Rupanya anak ini bisa bicara dengan normal!)",
  ui_story_5022_50220101_139_dialog_content = "Hm... The Blazing Tooth adalah rute klasik.",
  ui_story_5022_50220101_140_dialog_content = "Namun, karena kondisi jalannya rumit, staf logistik balapan sering mengeluhkan konsekuensinya. Meski sudah dibasmi secara rutin, Eclipsite masih bermunculan.",
  ui_story_5022_50220101_141_dialog_content = "Selain itu, menurut laporan Zeta, belakangan ini kawanan Eclipsite di wilayah sekitarnya justru aktif. Kita harus menyelidikinya lebih lanjut.",
  ui_story_5022_50220101_142_dialog_content = "Mungkin juga ada si besar itu. Namun, barangkali aku hanya terlalu banyak berpikir…",
  ui_story_5022_50220101_143_dialog_content = "…!",
  ui_story_5022_50220101_144_dialog_content = "Si besar? Jangan-jangan Legendary <color=#FFB400>Wicked Dragon Hakudoma</color>?",
  ui_story_5022_50220101_145_dialog_content = "Hah? Itu benar-benar nama aslinya?",
  ui_story_5022_50220101_146_dialog_content = "Tentu saja itu hanya nama karanganku! Keren, 'kan? Iya, 'kan?",
  ui_story_5022_50220101_147_dialog_content = "Setelah mendengar ceritamu, menurutku itu nama yang keren.",
  ui_story_5022_50220101_148_dialog_content = "Sebuah cerita, ya... Betapa riangnya...",
  ui_story_5022_50220101_149_dialog_content = "Hei, Roy. Akan kuselidiki masalah ini nanti.",
  ui_story_5022_50220101_150_dialog_content = "Tenanglah. Nikmati saja permainan balapannya dengan anak-anak ini.",
  ui_story_5022_50220101_151_dialog_content = "Anda... Anda mengatakan bahwa saya masih kecil?",
  ui_story_5022_50220101_152_dialog_content = "Kauanggap Blazing Rally permainan semata?!",
  ui_story_5022_50220101_153_dialog_content = "Kau mau coba-coba memonopoli sesuatu yang menyenangkan seperti menantang naga iblis?!",
  ui_story_5022_50220101_154_dialog_content = "Wah, wah, wah… Sepertinya Kota sudah tidak tahan lagi dan ingin berduel denganmu!",
  ui_story_5022_50220101_155_dialog_content = "Cih, dasar cecunguk merepotkan…",
  ui_story_5022_50220101_156_dialog_content = "Aku akan mengalahkanmu dalam balapan!",
  ui_story_5022_50220101_157_dialog_content = "Kalau naga itu muncul, aku yang akan mengalahkannya lebih dulu seperti kesatria dalam dongeng!",
  ui_story_5022_50220101_158_dialog_content = "… Mungkin.",
  ui_story_5022_50220101_159_dialog_content = "Aku tak punya waktu bermain-main denganmu.",
  ui_story_5022_50220101_160_dialog_content = "J-jangan pergi! Jangan pura-pura tidak mendengarku. Akan kuseret kau ke bagian pendaftaran!",
  ui_story_5022_50220101_161_dialog_content = "Berhenti! Aku juga ingin punya kaki panjang seperti itu! Tunggu aku!",
  ui_story_5022_50220101_162_dialog_content = "Ooh. Sekarang ini baru menarik.",
  ui_story_5022_50220101_163_dialog_content = "Duel?",
  ui_story_5022_50220101_164_dialog_content = "Di Rediesel Wrench, duel adalah persoalan serius. Orang yang ditantang harus menerima tantangan.",
  ui_story_5022_50220101_165_dialog_content = "Demi kehormatan? Tak pernah kusangka Rediesel Wrench sangat…",
  ui_story_5022_50220101_166_dialog_content = "Bukan begitu. Ini agar orang-orang bisa berkumpul dan menonton sesuatu yang mengasyikkan.",
  ui_story_5022_50220101_167_dialog_content = "Kurasa aku seharusnya sudah melihat itu datang...",
  ui_story_5022_50220101_168_dialog_content = "Hei, mengadakan suatu pertunjukan yang bisa ditonton itu penting.",
  ui_story_5022_50220101_169_dialog_content = "Aturan duelnya juga cukup banyak. Brock pernah menantangku lomba makan kadal panggang dan aku menang.",
  ui_story_5022_50220101_170_dialog_content = "Meskipun setelah itu kami berdua sama-sama dimarahi Roy…",
  ui_story_5022_50220101_171_dialog_content = "Sudah berapa kali kubilang? Jangan terlalu banyak makan camilan sebelum tidur. Terutama saat itu, saat semua makanan cadangan—",
  ui_story_5022_50220101_172_dialog_content = "Ehem! Sepertinya Blazing Tooth sudah ditetapkan sebagai trek kompetisinya. Tidak ada masalah, 'kan? Roy, aku masih mau mengajak para tamu berkeliling!",
  ui_story_5022_50220101_173_dialog_content = "Nah, jika pemimpin mengatakan demikian ...",
  ui_story_5022_50220101_174_dialog_content = "Sebaiknya aku juga bersiap-siap untuk balapan itu.",
  ui_story_5022_50220101_175_dialog_content = "PlayerName, nantikan balapan itu, ya!",
  ui_story_5022_50220201_1_dialog_content = "(Bagaimana saya bisa sampai di sini... Dan ini baru permulaan...)",
  ui_story_5022_50220201_2_dialog_content = "<size=45>—Rasakan ini! Lightning Shot!</size>",
  ui_story_5022_50220201_3_dialog_content = "Blazing Rally tak akan mengasyikkan kalau tidak ada ini! Hei, cecunguk yang di depan! Kalian kepanasan?!",
  ui_story_5022_50220201_4_dialog_content = "Bodoh! Justru kawat durilah barang tradisional yang paling autentik! Rasakan ini, tukang ikut-ikutan!",
  ui_story_5022_50220201_5_dialog_content = "Aduh! Pasti kena, pasti kena—!",
  ui_story_5022_50220201_6_dialog_content = "Semua tipuannya sama saja. Menggelikan. Aku jadi merasa bernostalgia.",
  ui_story_5022_50220201_7_dialog_content = "(Mengejutkan juga bisa keluar tanpa cedera…)",
  ui_story_5022_50220201_8_dialog_content = "Yah, sekarang jadi hening.",
  ui_story_5022_50220201_9_dialog_content = "Yah… Sepertinya sudah waktunya untuk menjelaskan.",
  ui_story_5022_50220201_S9_dialog_content = "Kenapa kau duduk di kursi kopilotku, Caelestite?",
  ui_story_5022_50220201_10_dialog_content = "B-bisa tidak kalau kau tidak dekat-dekat? Azure! Lihat jalannya! Lihat jalannya!",
  ui_story_5022_50220201_11_dialog_content = "Sinsa menyuruhku duduk di sini dan menunggunya, lalu terdengar suara pistol ditembakkan. Setelah itu aku tak bisa melihatnya lagi.",
  ui_story_5022_50220201_12_dialog_content = "Nah, lalu yang muncul adalah…",
  ui_story_5022_50220201_13_dialog_content = "Sudahlah. Lumayan juga kalau ada bocah manis yang duduk di sebelahku. Asal, jangan buat masalah, ya.",
  ui_story_5022_50220201_14_dialog_content = "D-dibandingkan dengan itu, tak kusangka bakal ada tabrakan beruntun di garis start dan para kontestan tak akan tanggung-tanggung kalau menyerang…",
  ui_story_5022_50220201_15_dialog_content = "Balapan macam apa ini?!",
  ui_story_5022_50220201_16_dialog_content = "Tadi kau bahkan tidak tanya dan sekarang kau berani duduk di mobil kontestan? Wah, kau punya nyali, Nak.",
  ui_story_5022_50220201_17_dialog_content = "Karena tadi Sinsa sangat fokus memaksaku makan pai kalajengking dan tak menjelaskan apa pun…",
  ui_story_5022_50220201_18_dialog_content = "Kemampuan mengemudimu boleh juga, bisa mengeluarkan kita dari kekacauan tadi.",
  ui_story_5022_50220201_19_dialog_content = "Hm, kau agak konyol, tapi pandai menyanjung, ya?",
  ui_story_5022_50220201_20_dialog_content = "Ah, bukan apa-apa. Ini hanya permainan dan aku harus serius kalau bermain.",
  ui_story_5022_50220201_21_dialog_content = "Bagaimana dengan duelnya?",
  ui_story_5022_50220201_22_dialog_content = "Pertanyaan yang konyol. Ya, aku memang menerima tantangannya, tapi siapa juga yang peduli kalau si bodoh itu menang?",
  ui_story_5022_50220201_23_dialog_content = "Menyelidiki pergerakan Eclipsite justru lebih penting.",
  ui_story_5022_50220201_24_dialog_content = "Mencegah hal semacam itu terjadi lagi…",
  ui_story_5022_50220201_25_dialog_content = "Omong-omong, naga legendaris itu—",
  ui_story_5022_50220201_26_dialog_content = "Ugh!",
  ui_story_5022_50220201_27_dialog_content = "Kita menabrak apa tadi?",
  ui_story_5022_50220201_28_dialog_content = "Kau ini cerewet juga, ya? Aku jadi menyesal karena mengizinkanmu ikut.",
  ui_story_5022_50220201_29_dialog_content = "Barusan aku melindas satu Eclipsite. Rasanya sih tidak fatal. Dia pasti akan menyusul nanti.",
  ui_story_5022_50220201_30_dialog_content = "… Menyusul?",
  ui_story_5022_50220201_31_dialog_content = "Iya, seharusnya juga ada lebih banyak Eclipsite di depan sana.",
  ui_story_5022_50220201_32_dialog_content = "Lebih banyak…?",
  ui_story_5022_50220201_33_dialog_content = "Siapa tahu. Mungkin saja ada sosok yang kucari… Eclipsite itu.",
  ui_story_5022_50220201_34_dialog_content = "Kalau kau takut, masih ada waktu untuk kabur, kok.",
  ui_story_5022_50220201_35_dialog_content = "Bahkan orang seperti kau pasti juga bisa berlari melintasi gurun ini dan kembali ke garis start.",
  ui_story_5022_50220201_36_dialog_content = "Anu…",
  ui_story_5022_50220201_37_dialog_content = "Hehe… Bercanda, kok! Ekspresi bingungmu lebih menarik dari dugaanku.",
  ui_story_5022_50220201_38_dialog_content = "Sayang sekali, kebersamaan kita yang indah hampir berakhir.",
  ui_story_5022_50220201_39_dialog_content = "A-apa…?",
  ui_story_5022_50220201_40_dialog_content = "—Hei! PlayerName!",
  ui_story_5022_50220201_41_dialog_content = "Hoamm… Sepertinya kita tertidur dan melewatkan permulaan kompetisi.",
  ui_story_5022_50220201_42_dialog_content = "Itu kan kau! Aku sih tidak melewatkannya!",
  ui_story_5022_50220201_43_dialog_content = "Mendarat dengan satu ban, lalu melesat dari sana! Melintasi celah dan melewati orang-orang yang menghalangi jalan! Wow! Begitulah gaya Azure!",
  ui_story_5022_50220201_44_dialog_content = "Sebentar, mobilnya kan bergerak. Bagaimana kalian bisa kemari?",
  ui_story_5022_50220201_45_dialog_content = "Dari atap, dong!",
  ui_story_5022_50220201_46_dialog_content = "Lumayan juga. Tadinya kukira kalian terpental dan mendarat di pasir.",
  ui_story_5022_50220201_47_dialog_content = "Kau tak boleh tidur nyenyak di mobil orang lain tanpa izin. Aku benar-benar ingin membangunkanmu dengan cara-cara yang tak lazim.",
  ui_story_5022_50220201_48_dialog_content = "Jangan kejam begitu, dong. Mantan juara balapannya kan ikut lomba lagi! Aku ingin duduk di kursi barisan depan!",
  ui_story_5022_50220201_49_dialog_content = "PlayerName, kursinya oke, 'kan? Terima kasihnya nanti saja.",
  ui_story_5022_50220201_50_dialog_content = "Azure adalah seniorku yang bergabung lebih dulu dengan Rediesel Wrench.",
  ui_story_5022_50220201_51_dialog_content = "Dia juga pembalap legendaris!",
  ui_story_5022_50220201_52_dialog_content = "Legendaris? Itu kan dulu.",
  ui_story_5022_50220201_53_dialog_content = "Kalian berada di sini kemungkinan besar karena… Huh. Dasar tukang ikut campur.",
  ui_story_5022_50220201_54_dialog_content = "Walaupun Sinsa benar-benar junior yang tidak manis, dia tetap pemimpinnya.",
  ui_story_5022_50220201_55_dialog_content = "Karena dia sudah bilang begitu, kalian boleh tetap di sini.",
  ui_story_5022_50220201_56_dialog_content = "Pertama, aku ingin pergi ke area Blazing Tooth untuk menyelidiki Eclipsite. Ruteku kebetulan melewati trek lomba.",
  ui_story_5022_50220201_57_dialog_content = "Selain kalian, sepertinya ada orang lain yang ingin menumpang…",
  ui_story_5022_50220201_58_dialog_content = "Hukuman apa yang paling tepat untuk anak nakal?",
  ui_story_5022_50220202_1_dialog_content = "Apa mobil balap Azure menembakkan meriam pada Eclipsite yang mengejarnya…?",
  ui_story_5022_50220202_2_dialog_content = "Tidak, sampai sejauh ini, tak ada yang bisa menggangguku lagi…",
  ui_story_5022_50220202_3_dialog_content = "<size=45>Halo, Semuanya—!</size>Aku penyelenggara acara kalian, Jomu! Rindu padaku?",
  ui_story_5022_50220202_4_dialog_content = "Wow! Suara apa itu?",
  ui_story_5022_50220202_5_dialog_content = "Blazing Rally memang seperti namanya. Dimulai dengan berapi-api…",
  ui_story_5022_50220202_6_dialog_content = "Benar, setengah dari kontestan sudah tersingkir secara tragis sejak di garis start!",
  ui_story_5022_50220202_7_dialog_content = "Beberapa dari yang tersingkir itu, sayangnya, menabrak. Meskipun begitu, ada unsur keberuntungan juga dalam permainan ini!",
  ui_story_5022_50220202_8_dialog_content = "Jangan cemaskan orang-orang lemah yang terjebak dalam kecelakaan mobil itu!",
  ui_story_5022_50220202_9_dialog_content = "Rabbie dan Chainsaw Rick dari Team 6 logistik balapan akan membuka cangkang logam mobil dan membawa mereka semua ke tempat yang aman!",
  ui_story_5022_50220202_10_dialog_content = "Mereka yang masih balapan sedang melaju menuju stage pertama, <color=#FFB400>Hot Air Desert</color>, dengan kecepatan penuh!",
  ui_story_5022_50220202_11_dialog_content = "Ayo duduk di kursi kita dan perhatikan percikan api yang beterbangan!",
  ui_story_5022_50220202_12_dialog_content = "Ini… radio?",
  ui_story_5022_50220202_13_dialog_content = "Blazing Rally diselenggarakan berkat sponsor eksklusif kita, Rediesel Wrench!",
  ui_story_5022_50220202_14_dialog_content = "Rediesel Wrench, sahabat terbaik kita di gurun.",
  ui_story_5022_50220202_15_dialog_content = "Kami menangani keamanan desa, pintu yang merepotkan, perbaikan mesin, daur ulang barang-barang lama, dan layanan lain yang bisa diandalkan!",
  ui_story_5022_50220202_16_dialog_content = "Harganya…. lebih murah dari Illumina. Pokoknya ini promo yang bagus!",
  ui_story_5022_50220202_17_dialog_content = "Pesan sekarang juga dan dapatkan figurine mini Lepidoz yang terkenal dari Rediesel Wrench!",
  ui_story_5022_50220202_X17_dialog_content = "Jumlahnya terbatas, jadi siapa cepat dia dapat. Jangan lewatkan!",
  ui_story_5022_50220202_18_dialog_content = "Berikutnya, hasil survei penonton kompetisi terakhir…",
  ui_story_5022_50220202_19_dialog_content = "Suara terbanyak adalah: Apa kita bisa mengganti penyelenggara acaranya yang berisik?",
  ui_story_5022_50220202_20_dialog_content = "Terima kasih! Kepuasan kalian adalah motivasi kami untuk terus meningkatkan diri!",
  ui_story_5022_50220202_21_dialog_content = "Dengan menyesal harus kukatakan bahwa semua orang merasa menyelenggarakan balapan ini terlalu merepotkan atau mereka terlalu malu, jadi aku masih jadi penyelenggara acara kompetisi tahun ini!",
  ui_story_5022_50220202_22_dialog_content = "Namun, sebagai kompensasinya, aku sudah mengundang seorang komentator tamu untuk kalian!",
  ui_story_5022_50220202_23_dialog_content = "Kami akan melakukan siaran dari stasiun radio resmi di Lepidoz, membagikan berita tentang balapan dan berbagai pesan lainnya!",
  ui_story_5022_50220202_24_dialog_content = "—Apa…? Duduk di sini? Ada hal penting yang harus ku…",
  ui_story_5022_50220202_25_dialog_content = "Kau mau orang tua seperti aku? Aku kan tidak ada menarik-menariknya…",
  ui_story_5022_50220202_26_dialog_content = "(Dia jelas-jelas baru saja secara acak terjebak untuk melakukan ini!)",
  ui_story_5022_50220202_27_dialog_content = "Dan sekarang, kita sambut…",
  ui_story_5022_50220202_28_dialog_content = "Maksudku, bisakah komentator spesial kita, Roy, menjelaskan peraturan kompetisinya kepada teman-teman baru kita yang masih awam dengan lomba ini?",
  ui_story_5022_50220202_29_dialog_content = "Eh… Peraturan? Peraturannya tidak membosankan, kok.",
  ui_story_5022_50220202_30_dialog_content = "Siapa pun yang sudah mendaftar bisa menggunakan kendaraan apa pun untuk melewati lintasan yang ditentukan. Tetaplah berada di dalam kendaraan selama mungkin dan selesaikan balapan secepat mungkin.",
  ui_story_5022_50220202_31_dialog_content = "Benar sekali! Taklukkan alam dan tantang diri sendiri!",
  ui_story_5022_50220202_32_dialog_content = "Majulah ke dalam pertempuran dengan api yang membara dalam mesin dan hatimu!",
  ui_story_5022_50220202_33_dialog_content = "Ada hal lain yang ingin komentator tamu kita tambahkan?",
  ui_story_5022_50220202_34_dialog_content = "Tambahan? Yah… Selamat bersenang-senang, pulanglah hidup-hidup.",
  ui_story_5022_50220202_35_dialog_content = "Tak ada salahnya bersenang-senang, tapi jangan sampai mati. Tim logistik akan selalu siap membantu.",
  ui_story_5022_50220202_36_dialog_content = "Bagus sekali! Begitulah Roy, selalu membicarakan hal-hal seperti itu dengan biasa-biasa saja!",
  ui_story_5022_50220202_37_dialog_content = "Namun, bukan itu saja kejutan di tahun ini!",
  ui_story_5022_50220202_38_dialog_content = "Pengemudi legendaris tak terkalahkan, yang dikenal sebagai Sexy Wildcat dari Rediesel Race, kembali ke lintasan untuk pertama kalinya dalam satu dasawarsa!",
  ui_story_5022_50220202_39_dialog_content = "Jomu…!",
  ui_story_5022_50220202_40_dialog_content = "(Fokus… Azure sangat fokus!)",
  ui_story_5022_50220202_41_dialog_content = "Wah, baru kali ini aku mendengar gelar itu… Sebentar lagi kau akan berada dalam jangkauannya, jadi minta maaf sekarang agar tidak celaka.",
  ui_story_5022_50220202_42_dialog_content = "Pengorbanan kecil seperti ini sepadan dengan programnya.",
  ui_story_5022_50220202_43_dialog_content = "Oh, bicara soal programnya!",
  ui_story_5022_50220202_44_dialog_content = "Konon, Eclipsite kuat yang muncul di Blazing Tooth lebih dari sepuluh tahun silam—",
  ui_story_5022_50220202_45_dialog_content = "—Wicked Dragon Hakudoma, bisa jadi muncul lagi!",
  ui_story_5022_50220202_46_dialog_content = "Sejak kapan nama itu jadi nama resmi…? Sudahlah, Zeta pasti akan senang.",
  ui_story_5022_50220202_47_dialog_content = "Nah, kita kesampingkan dulu rumornya. Aku datang kemari untuk membahas hadiahnya.",
  ui_story_5022_50220202_48_dialog_content = "Oh, iya. Hampir lupa! Hadiah tahun ini akan jadi yang termewah!",
  ui_story_5022_50220202_49_dialog_content = "Untuk hadiahnya… siapa cepat dia dapat dan itu termasuk tiket interaktif satu hari Lepidoz, Barbara dan Regina…",
  ui_story_5022_50220202_50_dialog_content = "Hadiahnya sudah tidak tersedia lagi.",
  ui_story_5022_50220202_51_dialog_content = "Hah? Apa maksudmu?",
  ui_story_5022_50220202_52_dialog_content = "Lepidoz memakan tiket interaktif satu hari.",
  ui_story_5022_50220202_53_dialog_content = "Barbara dan Regina tak mau menyatukan album mereka dan kelompok peminat bom mengadakan pemilihan anggota tahunan yang tak penting…",
  ui_story_5022_50220202_54_dialog_content = "Joanie Boom menang, tetapi dia tak bisa menahan godaan dan bomnya meledak bahkan sebelum balapan dimulai.",
  ui_story_5022_50220202_55_dialog_content = "Dia bilang dia tidak tahu seperti apa efeknya setelah membuatnya. Akibatnya, ada sebongkah batu pasir runcing yang terlempar ke angkasa akibat ledakan itu.",
  ui_story_5022_50220202_56_dialog_content = "Kukira itu akan jadi efek yang bagus, tapi dia bersikeras bahwa warna nyala apinya masih perlu ditingkatkan agar lebih artistik…",
  ui_story_5022_50220202_57_dialog_content = "Baiklah, biar kuganti—",
  ui_story_5022_50220202_58_dialog_content = "Sepertinya hadiah untuk balapan ini sama dengan tahun-tahun sebelumnya: campuran bubuk protein yang sangat rahasia dariku…",
  ui_story_5022_50220202_59_dialog_content = "Juga boneka hewan buatan tangan dari donatur anonim!",
  ui_story_5022_50220202_60_dialog_content = "Selain itu, tentu ada hadiah hiburan untuk semua orang!",
  ui_story_5022_50220202_61_dialog_content = "Dan juga—",
  ui_story_5022_50220202_62_dialog_content = "Rasakan kehidupan. Rasakan gairah yang mendidih. Kegembiraan dari tawa canda bersama semua orang dalam terpaan sinar matahari dan embusan angin!",
  ui_story_5022_50220202_63_dialog_content = "(Bisa tidak sih stasiun radio ini dimatikan…?)",
  ui_story_5022_50220202_64_dialog_content = "Eits, tunggu dulu! Bagi siapa pun yang ingin mematikan radionya, ada satu hadiah misterius lagi yang akan kami umumkan nanti!",
  ui_story_5022_50220202_65_dialog_content = "Bagian mengasyikkannya dimulai dari sini. Nah, sekarang, waktunya siaran penting—",
  ui_story_5022_50220202_66_dialog_content = "Kios es serut di depan Tir' Hotel… pria gurita itu baru saja meluncurkan produk baru!",
  ui_story_5022_50220202_67_dialog_content = "Menu baru bernama Lies Taste Like Sweet Honey! Wah, aku jadi penasaran! Aurorian dan Wolf, yang ikut uji rasanya, bilang…",
  ui_story_5022_50220202_68_dialog_content = "Fiuh, akhirnya selesai juga. Memangnya hadiah seperti ini menarik minat?",
  ui_story_5022_50220202_69_dialog_content = "Heh… Mungkin secara tak terduga memang populer.",
  ui_story_5022_50220202_70_dialog_content = "Hadiahnya selalu berasal dari Rediesel Wrench dan dilebih-lebihkan dari biasanya.",
  ui_story_5022_50220202_71_dialog_content = "Orang-orang tetap datang untuk ikut bersenang-senang walaupun tak ada hadiahnya.",
  ui_story_5022_50220202_72_dialog_content = "(Azure… tertawa?)",
  ui_story_5022_50220202_73_dialog_content = "… Azure, jangan-jangan kau memang menyukai Blazing Rally, ya…?",
  ui_story_5022_50220202_74_dialog_content = "Kau langsung menebak isi hati seorang wanita meskipun baru bertemu sebentar. Caramu menggoda tidak terlalu bagus, Caelestite.",
  ui_story_5022_50220202_75_dialog_content = "B-bagaimana aku harus mengatakannya, ya…? Ini kan kompetisi yang tak masuk akal. Sebenarnya, apa memang ini yang Rediesel Wrench lakukan…?",
  ui_story_5022_50220202_76_dialog_content = "Apa sih yang kaugumamkan?",
  ui_story_5022_50220202_77_dialog_content = "Zeta?",
  ui_story_5022_50220202_78_dialog_content = "Oh? Tak kusangka kau bisa langsung mengenali suaraku.",
  ui_story_5022_50220202_79_dialog_content = "Oh, kau memang bukan orang biasa. Master Colossus, Penuntun Cahaya, dan Caelestite.",
  ui_story_5022_50220202_80_option_content = "Panggil saja aku PlayerName.",
  ui_story_5022_50220202_81_dialog_content = "Bodoh! Itu kan nama yang bagus! Sayang sekali kau jarang menggunakannya!",
  ui_story_5022_50220202_82_dialog_content = "Biar kulihat… Hm, jadi itu Nona Sweet Evil God yang sedang bicara di saluran komunikasi?",
  ui_story_5022_50220202_83_dialog_content = "Kau… Kauanggap aku orang bodoh, ya?!",
  ui_story_5022_50220202_84_dialog_content = "Bukankah itu nama tim buatanmu? Nona Sweet Devil.",
  ui_story_5022_50220202_85_dialog_content = "Jangan! Tertawa! Dan! Membacanya!",
  ui_story_5022_50220202_86_option_content = "Heheh, aku jadi malu.",
  ui_story_5022_50220202_87_dialog_content = "Hah? Tak kusangka kau begitu tertarik bermain rumah-rumahan. Manisnya.",
  ui_story_5022_50220202_88_dialog_content = "Kalau begitu… Nona Sweet Devil, apa yang kauinginkan dari Caelestite milikku?",
  ui_story_5022_50220202_89_dialog_content = "\"Milikku\"…?",
  ui_story_5022_50220202_90_dialog_content = "Tidak… Jangan tertawa sambil membaca nama yang sudah kupikirkan masak-masak!",
  ui_story_5022_50220202_91_dialog_content = "Aku hanya kemari untuk mencari tahu kenapa kalian lama sekali!",
  ui_story_5022_50220202_92_dialog_content = "Bukankah nama timnya Evil God? Aku jadi agak bingung.",
  ui_story_5022_50220202_93_dialog_content = "Tahun lalu Child of the Wilderness atau apalah itu…",
  ui_story_5022_50220202_94_dialog_content = "Prajurit Sinsa! Kenapa kau ada di mobil wanita itu…? Apa kau sudah mengkhianati misi kesatria?",
  ui_story_5022_50220202_95_dialog_content = "Anu, itu… Anu…",
  ui_story_5022_50220202_96_dialog_content = "Hehehe. Aku tahu kau hanya pura-pura tergoda olehnya dan menunggu kesempatan untuk membantuku demi memperlambat progresnya…",
  ui_story_5022_50220202_97_dialog_content = "Kuhargai usahamu, tapi aku akan melawannya dengan adil dan jujur!",
  ui_story_5022_50220202_98_dialog_content = "Sepertinya kau tak akan kalah di garis start.",
  ui_story_5022_50220202_99_dialog_content = "Tak kusangka bahwa melemparkan beberapa bom kotoran burung bisa berdampak seperti itu…",
  ui_story_5022_50220202_100_dialog_content = "Tidak, tidak. Mereka jadi mengekor sebagian besar gara-gara ada orang botak yang mengeluarkan peluncur misil!",
  ui_story_5022_50220202_101_dialog_content = "Haaah! Takutlah, Caelestite!",
  ui_story_5022_50220202_102_dialog_content = "Dia sama sekali tidak mendengarkan.",
  ui_story_5022_50220202_103_dialog_content = "Aku punya kekuatan Evil God seperti ini. Kejam, ganas, dan jahat. Peduli setan kalau tak ada yang memahaminya…",
  ui_story_5022_50220202_104_dialog_content = "… Namun, sebenarnya aku adalah kesatria yang baik.",
  ui_story_5022_50220202_105_dialog_content = "Pura-pura tidak mendengarkan, tapi diam-diam tetap menutup lubang suaranya…",
  ui_story_5022_50220202_106_dialog_content = "Jadi… aku pasti akan mengalahkanmu, Azure.",
  ui_story_5022_50220202_107_dialog_content = "Juga dikenal sebagai Absolute Zero Witch, anak buah salah satu dari empat Heavenly King, Demon King!",
  ui_story_5022_50220202_108_dialog_content = "Siapakah Demon King dan ketiga lainnya itu? Entahlah, aku tak mau tahu.",
  ui_story_5022_50220202_109_dialog_content = "Harus kuakui, aku lebih memilih Absolute Zero Witch ketimbang Sexy Wildcat.",
  ui_story_5022_50220202_110_dialog_content = "Sejak tahun pertama aku memenangi Blazing Rally…",
  ui_story_5022_50220202_111_dialog_content = "Beberapa orang bodoh membandingkan rekorku dengan mereka. Mereka bilang, \"Kalau kau tidak keluar dari balapan, hasilnya tetap tidak diketahui…\"",
  ui_story_5022_50220202_112_dialog_content = "Kau selalu menjalankan misi-misi berbahaya dan berkata bahwa kau ingin melatih kekuatanmu. Kau membuat Roy cemas!",
  ui_story_5022_50220202_113_dialog_content = "Tak ada yang perlu kaujelaskan lagi. Takdir sudah terjalin dalam benang sutra kita.",
  ui_story_5022_50220202_114_dialog_content = "—Sebaiknya kau tidak mengecewakanku, pembalap legendaris.",
  ui_story_5022_50220202_115_dialog_content = "Akhirnya, selesai juga…",
  ui_story_5022_50220202_116_dialog_content = "Tariannya terlihat mengasyikkan, 'kan? Meskipun sudah berusaha keras, dia tetap tidak bisa jadi anak nakal.",
  ui_story_5022_50220202_117_dialog_content = "Akan tetapi, sebagai pembalap, dia adalah lawan yang tak bisa dianggap enteng.",
  ui_story_5022_50220202_118_dialog_content = "Kaudengar suara di saluran komunikasi tadi? Caelestite. Memang sempat ada gangguan, tapi aku tak mungkin salah dengar.",
  ui_story_5022_50220202_119_dialog_content = "Zeta sudah mendahului yang lain. Dia sudah sampai ke gurun.",
  ui_story_5022_50220202_120_dialog_content = "… Sebagai tokoh jahat yang sudah ditentukan untuk melawan sang kesatria, aku harus berusaha keras.",
  ui_story_5022_50220301_1_dialog_content = "Eh… Kita ada di mana?",
  ui_story_5022_50220301_2_dialog_content = "Ooh! Kita di gurun, 'kan?",
  ui_story_5022_50220301_3_dialog_content = "Saya punya dendeng cacing pasir di sini. Ingin beberapa? Saya akan memakannya jika Anda tidak menginginkannya.",
  ui_story_5022_50220301_4_dialog_content = "Kalian berdua kok terlalu santai, sih? Ini kan bukan piknik.",
  ui_story_5022_50220301_5_dialog_content = "Heheh, aku sampai tak bisa tidur semalam gara-gara sudah tidak sabar menantikan hari ini!",
  ui_story_5022_50220301_6_dialog_content = "Azure mengemudi dengan sangat cepat dan stabil. Begitu kudengar suara bodoh Jomu, aku langsung mengantuk…",
  ui_story_5022_50220301_7_dialog_content = "Omong-omong, Jomu memang penyelenggara acaranya, tapi yang dia bicarakan hanya iklan dan sama sekali bukan progres balapannya!",
  ui_story_5022_50220301_8_dialog_content = "Meski titik startnya berbeda, semua kontestan akan melewati titik pencatatan di gurun dan titik perbaikan di Dragon Breath Volcano—",
  ui_story_5022_50220301_9_dialog_content = "Melewati Blazing Tooth Canyon, lalu akhirnya mencapai tepi Eternal Night.",
  ui_story_5022_50220301_10_dialog_content = "Sesuai namanya, itu adalah trek ke ujung dunia.",
  ui_story_5022_50220301_11_dialog_content = "Ujung dunia…",
  ui_story_5022_50220301_12_dialog_content = "Karena cuaca hari ini tampak cerah, seharusnya kita tak akan menjumpai badai pasir. Terakhir kalinya balapan, pasir menerpa wajah kita…",
  ui_story_5022_50220301_13_dialog_content = "Memangnya mungkin menjumpai badai pasir? Tamat riwayat kita kalau tidak hati-hati…",
  ui_story_5022_50220301_14_dialog_content = "Tenang saja. Bahkan meskipun kau terbawa badai hingga ke langit, selalu ada jalan keluar!",
  ui_story_5022_50220301_15_dialog_content = "Hmm. Sudah hampir waktunya menemui para kontestan lain.",
  ui_story_5022_50220301_16_dialog_content = "Ooh! Lihat, PlayerName, lihat!",
  ui_story_5022_50220301_17_dialog_content = "Itu…?",
  ui_story_5022_50220301_18_dialog_content = "Awas!",
  ui_story_5022_50220301_19_dialog_content = "Ck, ck. Untung Honcho Sinsa cepat-cepat menarikmu.",
  ui_story_5022_50220301_20_dialog_content = "Kau kok terlalu santai, sih, PlayerName? Ini kan bukan piknik.",
  ui_story_5022_50220301_21_dialog_content = "Benda yang hampir memotong rambutku barusan… Apa itu Shadow Windmill milik Clover?",
  ui_story_5022_50220301_22_dialog_content = "—Hei! Itu berbahaya, tahu?! Kalau buluku sampai tergores, kau harus bayar!",
  ui_story_5022_50220301_23_dialog_content = "E-eh, Teman-teman… Jangan berkelahi… Berbahaya kalau bergerak-gerak…",
  ui_story_5022_50220301_24_dialog_content = "Huaaaa! Aku memang lebih cocok kalau naik sepeda motor…",
  ui_story_5022_50220301_25_dialog_content = "Beruang itu yang mulai duluan.",
  ui_story_5022_50220301_26_dialog_content = "Jangan menuduh orang yang tak bersalah!",
  ui_story_5022_50220301_27_dialog_content = "<size=45>Aku tidak menerima komisi untuk datang ke tempat yang sangat panas ini demi berpartisipasi dalam perlombaan ini dan menyuruh Kuma untuk menyergapmu agar peluang kemenanganku meningkat!</size>",
  ui_story_5022_50220301_28_dialog_content = "Pengy, tak ada gunanya berbohong.",
  ui_story_5022_50220301_29_dialog_content = "Kemarilah, Kawan! Memangnya kau tidak tahu seberapa sulit bagiku untuk mencari nafkah bagi kita berdua?",
  ui_story_5022_50220301_30_dialog_content = "Pengy, kedengarannya itu seperti kerja hukuman…",
  ui_story_5022_50220301_31_dialog_content = "Maggie, jangan lengah saat mengemudi. Waspadalah terhadap lereng pasir.",
  ui_story_5022_50220301_32_dialog_content = "—Aha! Ada celah!",
  ui_story_5022_50220301_33_dialog_content = "… Aku ingin berteriak hingga serak, tapi gadis ini sangat tenang…",
  ui_story_5022_50220301_34_dialog_content = "Diam!!! Jangan ganggu tidurku! Mau makan peluru, ya?!",
  ui_story_5022_50220301_35_dialog_content = "S-sergapan?! Nih, rasakan kekuatan peluru ini! Deep Cold—",
  ui_story_5022_50220301_36_dialog_content = "Mengalihkan perhatian, cangkang palsu, dan semuanya diledakkan. Sangat cepat.",
  ui_story_5022_50220301_37_dialog_content = "S-sebelum aku sempat menggunakan Luminatics, kau…",
  ui_story_5022_50220301_38_dialog_content = "Hah? Bukankah ini Kafka?!",
  ui_story_5022_50220301_39_dialog_content = "Apa-apaan ini…? Rupanya kalian berdua… Akhirnya mau bergabung dengan Rediesel Wrench, ya?",
  ui_story_5022_50220301_40_dialog_content = "Guk?",
  ui_story_5022_50220301_41_dialog_content = "Berhentilah meremehkan orang. Kami tidak seperti Crocodile yang ingin bergabung dengan mereka demi kolam renang jelek dan makanan tiga kali sehari.",
  ui_story_5022_50220301_42_dialog_content = "Hei, jangan kira aku tak bakal mengusirmu karena aku sedang mengemudi. Atau apa kau mau kujadikan bantal?",
  ui_story_5022_50220301_43_dialog_content = "Benar! Kalian sangat menyukai kolam itu, 'kan?",
  ui_story_5022_50220301_44_dialog_content = "Kami memang menghabiskan banyak waktu untuk bersantai di tepi kolam di oasis dan mengumpulkan segala berita di Rediesel Wrench.",
  ui_story_5022_50220301_45_dialog_content = "Kafka juga memberi kami camilan sesekali, tapi…",
  ui_story_5022_50220301_46_dialog_content = "Sayap kebebasan sejati tak bisa dibeli dengan kenyamanan-kenyamanan kecil seperti ini!",
  ui_story_5022_50220301_47_dialog_content = "Kepalaku masih pusing gara-gara harus bergadang untuk menyelesaikan pekerjaan. Aku tak punya waktu untuk omong kosongmu. Tangkap.",
  ui_story_5022_50220301_48_dialog_content = "Cangkangmu adalah taktik pengalih perhatian. Yang asli adalah ikan haring kalengan itu.",
  ui_story_5022_50220301_49_dialog_content = "!!!",
  ui_story_5022_50220301_50_dialog_content = "Kulempar, ya.",
  ui_story_5022_50220301_51_dialog_content = "T-tangkap—",
  ui_story_5022_50220301_X51_dialog_content = "Aku juga…",
  ui_story_5022_50220301_X52_dialog_content = "Aaaahhhh!!",
  ui_story_5022_50220301_X53_dialog_content = "Pengy! Pegangan padaku!",
  ui_story_5022_50220301_52_dialog_content = "Penguin bodoh itu tak perlu melompat keluar dari mobil yang mengebut hanya demi menangkap kaleng…",
  ui_story_5022_50220301_53_dialog_content = "Kuma berusaha menyelamatkannya dan malah ikut jatuh… Saking jauhnya mereka berguling, aku sampai tak bisa melihat mereka.",
  ui_story_5022_50220301_54_dialog_content = "Siapa yang tahu? Mungkin itulah sayap kebebasan yang mereka bicarakan tadi… Kalau soal mengacau, mereka memang tak ada tandingannya.",
  ui_story_5022_50220301_55_dialog_content = "Baiklah. Dua rekan timmu yang bermain di kotak pasir sudah berhenti, Sork.",
  ui_story_5022_50220301_56_dialog_content = "Kaleng ikan itu tidak sia-sia. Aku tahu tujuan kita sama.",
  ui_story_5022_50220301_57_dialog_content = "Pertempuran ini memang tak terhindarkan.",
  ui_story_5022_50220301_58_dialog_content = "Oowoooooo!",
  ui_story_5022_50220301_59_dialog_content = "Aku tidak mengerti… Benar-benar tidak mengerti.",
  ui_story_5022_50220301_60_dialog_content = "K-kenapa boneka yang Roy buat sangat populer?",
  ui_story_5022_50220301_61_dialog_content = "Demi mendapatkannya, beberapa kolektor bahkan sampai rela membuat penawaran yang tak bisa ditolak pemburu hadiah…",
  ui_story_5022_50220301_62_dialog_content = "Mungkin kali ini seekor kelinci. Tak ada yang mau melewatkan kelinci.",
  ui_story_5022_50220301_63_dialog_content = "Tekstur lembut Bunnybear Plush tak ada tandingannya. Kita pasti bisa tidur nyenyak kalau memeluknya.",
  ui_story_5022_50220301_64_dialog_content = "Guk, guk!",
  ui_story_5022_50220301_65_dialog_content = "Ini bukan masalah penampilan… atau teksturnya… Pokoknya kita akan merasa tenang, aman, dan nyaman…",
  ui_story_5022_50220301_66_dialog_content = "Meskipun bahannya sederhana, boneka itu dibuat dengan halus dan bagus. Aku menjadikannya sebagai kursi santai di sarang.",
  ui_story_5022_50220301_67_dialog_content = "Bekk… Bahkan kau juga menyukainya!?",
  ui_story_5022_50220301_68_dialog_content = "Kafka benar. Pertempuran itu tak terhindarkan.",
  ui_story_5022_50220301_69_dialog_content = "Ini kesempatan langka. Bagaimana kalau kita cari tahu siapa sniper yang lebih andal dari Rediesel Wrench?",
  ui_story_5022_50220301_70_dialog_content = "Tak ada tempat untuk sembunyi! Pergilah, Franz!",
  ui_story_5022_50220301_71_dialog_content = "Ha! Raging Bekk!",
  ui_story_5022_50220301_72_dialog_content = "Giliranku! M23 High Explosive!",
  ui_story_5022_50220301_73_dialog_content = "Mereka benar-benar bersenang-senang di sana… Apa kita tak perlu turun tangan?",
  ui_story_5022_50220301_74_dialog_content = "Tak apa-apa. Saling hajar juga bagian dari permainan ini.",
  ui_story_5022_50220301_75_dialog_content = "Lebih baik mengenal satu sama lain agar mereka bisa bekerja sama dengan lebih baik dalam pertempuran.",
  ui_story_5022_50220301_76_dialog_content = "Aku tak menyadari ada tujuan tersembunyi di balik semua ini…",
  ui_story_5022_50220301_77_dialog_content = "Oh, aku hanya mengarang, kok. Aku sendiri bahkan merasa terkesan!",
  ui_story_5022_50220301_78_dialog_content = "Bisakah kita menjauh dari mereka dan berjalan memutar?",
  ui_story_5022_50220301_79_dialog_content = "Bukannya tidak bisa sih, tapi wilayah ini dihuni oleh para Sandworm raksasa.",
  ui_story_5022_50220301_80_dialog_content = "Jika keluar dari jalur, kemungkinan kita akan menjadi kudapan sandworm, terlindas mobil, dan semacamnya. Atau lebih buruk lagi, pasir isap akan menelan kita.",
  ui_story_5022_50220301_81_dialog_content = "Bahkan jalur yang ditentukan melewati area perburuan mereka…",
  ui_story_5022_50220301_82_dialog_content = "Omong-omong, kudengar ada kontestan yang membawa Sandworm jinak, ya?",
  ui_story_5022_50220301_83_dialog_content = "Benar. Tak kusangka mereka hebat juga. Akan tetapi, akhirnya akulah yang menang.",
  ui_story_5022_50220301_84_dialog_content = "Wow! Ada bom berdaya ledak tinggi melesat ke arah sini! Seperti apa ya warna api dari ledakannya?",
  ui_story_5022_50220301_85_dialog_content = "Cih… Dasar anak-anak. Mainan mereka berserakan.",
  ui_story_5022_50220301_86_dialog_content = "Mainan? Bom berdaya ledak tinggi? Serius, nih!?",
  ui_story_5022_50220301_87_dialog_content = "Mainan yang menyakitkan kalau diinjak. Dua sniper itu terlihat lebih profesional, tapi cara mereka memegang senapan…",
  ui_story_5022_50220301_88_dialog_content = "Azure! Belok! Belok sekarang!",
  ui_story_5022_50220301_89_dialog_content = "<color=#e8d9bb>DUAR!</color>",
  ui_story_5022_50220301_90_dialog_content = "Oh, warna kuning biasa. Tidak menarik, ah.",
  ui_story_5022_50220301_91_dialog_content = "Wah… Aku selamat… Dahsyat juga gelombang kejutnya…",
  ui_story_5022_50220301_92_dialog_content = "Sudah cukup bersenang-senangnya? Kalau mau pergi, aku sudah menemukan rute yang bagus.",
  ui_story_5022_50220301_93_dialog_content = "Aku jadi merasa aman karena ada Azure. Belokannya juga mulus. Aku bahkan tak perlu memperingatkannya…",
  ui_story_5022_50220301_94_dialog_content = "Tidak, tidak, tidak! Kalau dia bilang rute yang bagus…",
  ui_story_5022_50220301_95_dialog_content = "Caelestite, kau suka yang kasar-kasar?",
  ui_story_5022_50220301_96_dialog_content = "Apa?",
  ui_story_5022_50220301_97_dialog_content = "PlayerName, cepat! Pegangan!",
  ui_story_5022_50220501_1_dialog_content = "(Apa tadi aku bermimpi?)",
  ui_story_5022_50220501_2_dialog_content = "(Aku bermimpi kami menerjang lereng pasir besar. Waktu seakan-akan berhenti saat mobil kami mengudara.)",
  ui_story_5022_50220501_3_dialog_content = "(Yang kulihat di sekelilingku hanyalah para Eclipsite yang sembunyi di bawah bayangan bebatuan besar. Mereka semua menatapku. Ratusan pasang mata tertuju padaku.)",
  ui_story_5022_50220501_4_dialog_content = "(Meski para Eclipsite itu bisa dikalahkan dengan cepat, bukit pasirnya tiba-tiba berputar dengan hebat…)",
  ui_story_5022_50220501_5_dialog_content = "(Ada sesuatu yang muncul dari dalam… Apa yang tadi itu sebuah mulut penuh gigi?)",
  ui_story_5022_50220501_6_dialog_content = "Apa tadi aku… bermimpi?",
  ui_story_5022_50220501_7_dialog_content = "Tidak.",
  ui_story_5022_50220501_8_dialog_content = "Kita lebih cepat. Biar Kafka yang mengurus Sandworm kelaparan itu.",
  ui_story_5022_50220501_9_dialog_content = "Apa mereka akan baik-baik saja?",
  ui_story_5022_50220501_10_dialog_content = "Lalu, apa maksudnya? Suka yang \"kasar-kasar\"!?",
  ui_story_5022_50220501_11_dialog_content = "Heyo! Apa kalian semua masih hidup, para penonton dan kontestanku?",
  ui_story_5022_50220501_12_dialog_content = "Aku Jomu, penyelenggara acara kalian. Flaming Rally sekarang benar-benar memanas! Bunuh atau terbunuh, Semuanya!",
  ui_story_5022_50220501_13_dialog_content = "Para Sandworm raksasa adalah tamu tak diundang yang memeriahkan permainan ini! Ayo bersorak untuk mereka!",
  ui_story_5022_50220501_14_dialog_content = "Apa ada keadaan yang lebih tak terduga dalam permainan nanti?",
  ui_story_5022_50220501_15_dialog_content = "Misalnya naga iblis legendaris berkepala 9, berkaki 6, dan bersayap 3?",
  ui_story_5022_50220501_16_dialog_content = "Kau memang benar-benar bisa mengatakan apa pun untuk memancing amarah banyak orang, ya. Bagaimana bisnismu? Sudah dilanjutkan?",
  ui_story_5022_50220501_17_dialog_content = "Odi dari divisi komunikasi mengumpulkan sinyal dari para kontestan yang menyerah karena serangan Sandworm. Namun, sebelum itu…",
  ui_story_5022_50220501_18_dialog_content = "Teman-teman! Eclipsite yang dikenal sebagai naga iblis adalah makhluk yang sama dengan yang diusir oleh komentator kita bertahun-tahun lalu!",
  ui_story_5022_50220501_19_dialog_content = "Bagaimana pendapat Roy tentang teman lama kita ini?",
  ui_story_5022_50220501_20_dialog_content = "Kok tiba-tiba…? Uh, yah, tentu sayang sekali dulu kita tidak menghabisi Eclipsite itu.",
  ui_story_5022_50220501_21_dialog_content = "Padahal benteng itu sudah rusak parah akibat serangan penyergapan Eclipsite… Kita kehabisan amunisi dan cakarnya menembusku…",
  ui_story_5022_50220501_22_dialog_content = "Aku masih berharap andai saja dulu aku menghabisinya sekalian.",
  ui_story_5022_50220501_23_dialog_content = "Menembusmu?",
  ui_story_5022_50220501_24_dialog_content = "Oh, bukan apa-apa. Omong-omong, akan kuserahkan tugas itu pada anak-anak muda sekarang.",
  ui_story_5022_50220501_25_dialog_content = "Artinya, anak-anak muda tertentu pun seharusnya tidak mempertaruhkan nyawa mereka. Bahkan jika memang bisa, sebaiknya mereka tidak mencoba untuk menyelesaikan masalah itu sendiri…",
  ui_story_5022_50220501_26_dialog_content = "Nah, karena kita ada di sini, bagaimana kalau kita bersantai dan menikmati permainannya?",
  ui_story_5022_50220501_27_dialog_content = "… Jadi, monster itu benar-benar ada? Tadinya kukira itu hanya karangan Zeta, seperti Evil God…",
  ui_story_5022_50220501_28_dialog_content = "Kau takut, ya? Mau dipeluk?",
  ui_story_5022_50220501_29_option_content = "Tak ada yang perlu ditakutkan.",
  ui_story_5022_50220501_30_dialog_content = "Benarkah? Bualanmu menggemaskan juga, ya.",
  ui_story_5022_50220501_31_option_content = "Tentu saja",
  ui_story_5022_50220501_32_dialog_content = "Oh? Aku suka anak jujur. Sayangnya, aku sedang sibuk.",
  ui_story_5022_50220501_33_dialog_content = "Dia sudah pergi bertahun-tahun? Pantas saja semua jadi berlebihan.",
  ui_story_5022_50220501_34_dialog_content = "Dan dia muncul saat aku di sini… Sungguh suatu kebetulan.",
  ui_story_5022_50220501_35_dialog_content = "Akan tetapi, dia memang ada dan masih ada…",
  ui_story_5022_50220501_36_dialog_content = "… Biar kuperbaiki kesalahan itu.",
  ui_story_5022_50220501_37_dialog_content = "(Azure lebih menakutkan dari sesosok naga berkepala 9…)",
  ui_story_5022_50220501_38_dialog_content = "(Apa terjadi sesuatu dulu…?)",
  ui_story_5022_50220501_39_dialog_content = "Nah, yang ini penting! Sungguh! Percayalah padaku!",
  ui_story_5022_50220501_40_dialog_content = "Pertama, kami sudah mengonfirmasi suar sinyal para kontestan yang menyerah.",
  ui_story_5022_50220501_41_dialog_content = "Lepidoz akan segera menuju ke lokasi target untuk menjemput para pecundang seperti kalian. Tunggu, ya!",
  ui_story_5022_50220501_42_dialog_content = "Berikutnya, secara mengejutkan, masih ada beberapa kontestan yang hanya mengalami cedera ringan dalam permainan ini.",
  ui_story_5022_50220501_43_dialog_content = "Oleh karena itu, untuk memeriahkan suasana, akan kuumumkan apa hadiah misterius kompetisi ini…",
  ui_story_5022_50220501_44_dialog_content = "<size=45>\"Buat Permintaan pada Eve\"!</size>",
  ui_story_5022_50220501_45_dialog_content = "Apa?",
  ui_story_5022_50220501_46_dialog_content = "Benar! Eve dari Rediesel Wrench akan mengabulkan apa pun permintaan kalian!",
  ui_story_5022_50220501_47_dialog_content = "Akankah pemenangnya ingin melihat senyum gadis itu atau meminjam kekuatan Necroid Dark Star?",
  ui_story_5022_50220501_48_dialog_content = "Aku tak sabar ingin mengetahuinya!",
  ui_story_5022_50220501_49_dialog_content = "Eve… bahkan tidak mau repot-repot memberitahuku…",
  ui_story_5022_50220501_50_dialog_content = "Kau pasti akan keberatan, 'kan?",
  ui_story_5022_50220501_51_dialog_content = "Memangnya kenapa aku harus keberatan?",
  ui_story_5022_50220501_52_dialog_content = "Melihatnya pulih sepenuhnya dan mau menyusul segala ketertinggalan…",
  ui_story_5022_50220501_53_dialog_content = "Dan menggunakan kekuatannya untuk membantu orang… Aku sangat senang.",
  ui_story_5022_50220501_54_dialog_content = "Yang benar? Kau lupa, ya? \"Permintaan apa pun\".",
  ui_story_5022_50220501_55_dialog_content = "Bagaimana kalau ada orang yang ingin menikahinya?",
  ui_story_5022_50220501_56_dialog_content = "Ahh…",
  ui_story_5022_50220501_57_option_content = "Itu mungkin saja.",
  ui_story_5022_50220501_58_dialog_content = "Eve kan cantik dan baik hati. Siapa pun pasti mau menikahinya.",
  ui_story_5022_50220501_59_dialog_content = "Pria mana pun akan beruntung kalau bisa memilikinya…",
  ui_story_5022_50220501_60_dialog_content = "Apa yang kaupikirkan!?",
  ui_story_5022_50220501_61_dialog_content = "B-bukan apa-apa!",
  ui_story_5022_50220501_62_option_content = "Itu tidak mungkin.",
  ui_story_5022_50220501_63_dialog_content = "Apa? Kaupikir Eve tidak cukup baik, ya? Hah?",
  ui_story_5022_50220501_64_dialog_content = "Tentu saja dia sangat baik!",
  ui_story_5022_50220501_65_dialog_content = "Kalau seseorang yang benar-benar mencintainya, menghargainya, dan melindunginya dengan segenap jiwa raganya benar-benar muncul…",
  ui_story_5022_50220501_66_dialog_content = "Aduh… Kita harus bagaimana? Sepertinya Sinsa sangat terganggu dengan kemungkinan lelucon itu…",
  ui_story_5022_50220501_67_dialog_content = "Ini semua salahmu, PlayerName. Katakan sesuatu, dong!",
  ui_story_5022_50220501_68_dialog_content = "Hah? Salahku!?",
  ui_story_5022_50220501_69_dialog_content = "Hei, kalian! Minggir! Aku sedang ngebut, nih!",
  ui_story_5022_50220501_70_dialog_content = "Kalau tidak, kutabrak kalian sampai terpental!",
  ui_story_5022_50220501_71_dialog_content = "Secara teknis, mobil turboku ini dalam kecepatan penuh.",
  ui_story_5022_50220501_72_dialog_content = "Hei, kau bakal jatuh kalau terus bersandar di jendela seperti itu!",
  ui_story_5022_50220501_73_dialog_content = "Tidak mungkin… Gawat, nih…",
  ui_story_5022_50220501_74_dialog_content = "Ohhhhhhhhhh! Bukankah itu PlayerName!?",
  ui_story_5022_50220501_75_dialog_content = "Kalau ikut balapan, berarti dia sudah selangkah lebih dekat untuk menjadi pria sejati. Namun, tentu saja aku tetap lebih unggul!",
  ui_story_5022_50220501_76_dialog_content = "Biar kulihat… Rekanmu adalah Joanie Boom dan… Azure!?",
  ui_story_5022_50220501_77_dialog_content = "Lama tak jumpa, Brock. Kau sudah tampak lebih kuat daripada saat terakhir kali kita bertemu, ya?",
  ui_story_5022_50220501_78_dialog_content = "Astaga, Azure masih secantik dulu…",
  ui_story_5022_50220501_79_dialog_content = "Celaka! T-tentu saja! Aku sudah jadi wakil komandan Rediesel Wrench, lo!",
  ui_story_5022_50220501_80_dialog_content = "Meskipun sudah jadi pria paling populer di Rediesel Wrench, aku masih berlatih setiap hari!",
  ui_story_5022_50220501_81_dialog_content = "Bahkan kalau harus melawan Azure dalam balapan ini, aku tetap akan jadi pemenangnya!",
  ui_story_5022_50220501_82_dialog_content = "Maksudku, hadiah utamanya sudah ditakdirkan untuk jadi milikku!",
  ui_story_5022_50220501_83_dialog_content = "Hadiah utama…?",
  ui_story_5022_50220501_84_dialog_content = "Sinsa? Kau di sini juga?",
  ui_story_5022_50220501_85_dialog_content = "Memangnya orang yang lebih lemah dariku bisa melindungi adikku? Tes… Benar juga. Aku harus mengetesmu.",
  ui_story_5022_50220501_86_dialog_content = "Kenapa kau bergumam sendiri, sih? Apa karena tadi aku bilang bahwa aku wakil komandan…?",
  ui_story_5022_50220501_87_dialog_content = "Kenapa buka pintu…? Oh, ayolah! Seharusnya aku memang tidak membual, tapi kau kan tak perlu marah begitu!",
  ui_story_5022_50220501_88_dialog_content = "Azure, apa itu yang ada di belakang mobil Brock dan Fleur?",
  ui_story_5022_50220501_89_dialog_content = "Tidak penting, kok! Kalau kau mau bertarung, sini kuladeni!",
  ui_story_5022_50220501_90_dialog_content = "Biar aku mengalahkanmu sekali lagi dalam duel ke-873 kita dan menyingkirkan timmu!",
  ui_story_5022_50220501_91_dialog_content = "Sebentar, ini bukan waktunya bertarung… Eclipsite datang!",
  ui_story_5022_50220502_1_dialog_content = "Bukankah kita baru saja mengalahkan satu gelombang Eclipsite? Jumlah mereka terlalu banyak!",
  ui_story_5022_50220502_2_dialog_content = "Waow! Lihat hamburan debu yang mereka timbulkan! Seperti badai pasir!",
  ui_story_5022_50220502_3_dialog_content = "Meskipun tak bisa melihat yang ada di balik pasir dan debu dengan jelas, aku masih bisa merasakan Eclipsite di depan dan belakang kita!",
  ui_story_5022_50220502_4_dialog_content = "Itu kemampuan khusus klanmu, ya? Keren juga, Caelestite.",
  ui_story_5022_50220502_5_dialog_content = "Sepertinya Sinsa dan Brock tak mau berhenti bertarung…",
  ui_story_5022_50220502_6_dialog_content = "Hah? Kapan mereka naik ke atas mobilku?",
  ui_story_5022_50220502_7_dialog_content = "Masih perlu bertanya? Rediesel Wrench selalu siap bertarung kapan saja!",
  ui_story_5022_50220502_8_dialog_content = "Hah, dasar anak-anak muda… Mereka memang tak bisa bersabar.",
  ui_story_5022_50220502_9_dialog_content = "Mungkin aku bisa bersantai dan menikmati permainan ini…",
  ui_story_5022_50220502_10_dialog_content = "Biar kuurus Eclipsite yang di belakang. Caelestite, ambil alih kemudinya.",
  ui_story_5022_50220502_11_dialog_content = "Aku ikut, dong! Ayo, kita ledakkan mereka!",
  ui_story_5022_50220502_12_dialog_content = "Aku? Aku kan tak bisa mengemudi…",
  ui_story_5022_50220502_13_dialog_content = "Hei, jangan lepaskan kemudinya begitu saja!",
  ui_story_5022_50220502_14_dialog_content = "Tak perlu ragu-ragu… Mulai dari mana, nih?",
  ui_story_5022_50220502_15_dialog_content = "Sini, kubinasakan kalian!",
  ui_story_5022_50220502_16_dialog_content = "Azure, apa yang harus ku…",
  ui_story_5022_50220502_17_dialog_content = "Oh? Jangan bilang kau sudah selesai. Kita justru baru saja mulai.",
  ui_story_5022_50220502_18_dialog_content = "(Tenang… Tenang! Berpura-puralah tidak mendengar suara senapan dan ledakan!)",
  ui_story_5022_50220502_19_dialog_content = "(Rasakan, putar kemudinya, dan cari cara untuk menerobos mereka…!)",
  ui_story_5022_50220502_20_dialog_content = "Tunggu apa lagi, PlayerName? Injak pedal gasnya! Ayolah!",
  ui_story_5022_50220502_21_dialog_content = "Hei, aku ini masih pemula! Gas, maksudmu ini!?",
  ui_story_5022_50220502_22_dialog_content = "Fleur, ayo kita juga tancap gas!",
  ui_story_5022_50220502_23_dialog_content = "Huh… Padahal tadi aku naik ke atap mobil biar kelihatan keren, tapi bukankah ini agak tinggi?",
  ui_story_5022_50220502_24_dialog_content = "Sekarang saatnya!",
  ui_story_5022_50220502_25_dialog_content = "Brock, sebaiknya kau…",
  ui_story_5022_50220502_26_dialog_content = "Santai saja!",
  ui_story_5022_50220502_27_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_5022_50220502_28_dialog_content = "Oh…",
  ui_story_5022_50220502_29_dialog_content = "Hei, Brock, kalau kau menghindar, nanti kap Powerball melekuk.",
  ui_story_5022_50220502_30_dialog_content = "Aduh, kasihan. Sakit, ya? Apa aku punya cukup komponen untuk memperbaikimu?",
  ui_story_5022_50220502_31_dialog_content = "Hei! Sekarang aku jadi tidak penting, ya? Dasar maniak mesin!",
  ui_story_5022_50220502_32_dialog_content = "Aku tidak menghindar, kok! Ini memang strategiku! Sekarang aku akan habis-habisan!",
  ui_story_5022_50220502_33_dialog_content = "Kalau bisa berteriak seperti itu, berarti kau baik-baik saja, 'kan?",
  ui_story_5022_50220502_34_dialog_content = "Mobilnya kehilangan kendali dan langsung menuju ke batu besar itu.",
  ui_story_5022_50220502_35_dialog_content = "Hah?",
  ui_story_5022_50220502_36_dialog_content = "Sinsa, kau kan juga ikut naik mobil ini, bagaimana kalau kau membantu?",
  ui_story_5022_50220502_37_dialog_content = "Kita berhasil!",
  ui_story_5022_50220502_38_dialog_content = "Sudah tidak ada Eclipsite yang mengejar kita lagi… Apa Azure yang mengurus semua Eclipsite itu?",
  ui_story_5022_50220502_39_dialog_content = "Hei, aku kan juga membantu! Bukankah aku pantas dipuji?",
  ui_story_5022_50220502_40_dialog_content = "Oh, tidak usah dibesar-besarkan begitu. Mereka yang lemah memang tak pantas bertahan di gurun ini.",
  ui_story_5022_50220502_41_dialog_content = "Namun, ternyata kau lebih bisa diandalkan daripada dugaanku, Caelestite. Kerja bagus untuk percobaan pertamamu.",
  ui_story_5022_50220502_42_dialog_content = "Hmm… Bagaimana kalau kaupertimbangkan untuk mendaftar sebagai kontestan resmi lain kali…?",
  ui_story_5022_50220502_43_dialog_content = "Sebentar, kenapa tidak langsung mengincar hadiah utamanya dan menantang skor tinggi Azure?",
  ui_story_5022_50220502_44_option_content = "Wah, aku jadi tertarik.",
  ui_story_5022_50220502_45_dialog_content = "Oh, menarik sekali. Akan tetapi, kau harus lebih banyak berlatih kalau mau jadi lawanku.",
  ui_story_5022_50220502_46_dialog_content = "(Dia kelihatan senang…)",
  ui_story_5022_50220502_47_option_content = "Aku tidak sehebat itu.",
  ui_story_5022_50220502_48_dialog_content = "Oh, tak usah malu-malu. Kalau kau benar-benar mau belajar, aku bisa mengajarimu.",
  ui_story_5022_50220502_49_dialog_content = "(Dekat sekali!)",
  ui_story_5022_50220502_50_dialog_content = "O-omong-omong, apakah kita melupakan sesuatu?",
  ui_story_5022_50220502_51_dialog_content = "*Uhuk, uhuk*",
  ui_story_5022_50220502_52_dialog_content = "Meskipun berhasil dihentikan, mobil ini perlu perbaikan serius… Perbaikannya akan makan waktu lama sebelum kita bisa kembali terjun dalam permainan.",
  ui_story_5022_50220502_53_dialog_content = "Hah? Kau masih belum menyerah, ya? Ada asap hitam yang mengepul dari mobilmu, tahu?",
  ui_story_5022_50220502_54_dialog_content = "Hei, jangan pernah menyepelekan teknisi. Aku ditakdirkan untuk membuat mecha besar. Memperbaiki mobil sih bukan apa-apa.",
  ui_story_5022_50220502_55_dialog_content = "Caramu melompat dari mobil itu membuatku terinspirasi!",
  ui_story_5022_50220502_56_dialog_content = "Memasang sistem pendorong vertikal di mecha sepertinya ide bagus…",
  ui_story_5022_50220502_57_dialog_content = "Kausuka robot, ya… Namun, kedengarannya memang menarik, sih!",
  ui_story_5022_50220502_58_dialog_content = "Satu lagi…",
  ui_story_5022_50220502_59_dialog_content = "Apa?",
  ui_story_5022_50220502_60_dialog_content = "Lihat ke sana.",
  ui_story_5022_50220502_61_dialog_content = "<size=45>Sinsa! Kau bakal tertinggal kalau diam saja!</size>",
  ui_story_5022_50220502_62_dialog_content = "Hei! Tunggu!",
  ui_story_5022_50220502_63_dialog_content = "Ohohoh! Berlari untuk mengejar mobil rupanya. Luar biasa!",
  ui_story_5022_50220502_64_dialog_content = "Aku orang tercepat di Rediesel Wrench!",
  ui_story_5022_50220502_65_dialog_content = "Dan aku akan memenangkan tantangan ke-874!",
  ui_story_5022_50220502_66_dialog_content = "Aku pasti bakal bisa pamer di depan Azure!",
  ui_story_5022_50220502_67_dialog_content = "Hahaha! Itu baru semangat!",
  ui_story_5022_50220502_68_dialog_content = "Namun, mobil kita mogok di tengah gurun, jadi…",
  ui_story_5022_50220502_69_dialog_content = "Nah, sebagai langkah pertama menuju tantangan berikutnya, kau bisa mengambilkan obeng hijau itu, tidak?",
  ui_story_5022_50220601_1_dialog_content = "Meledakkan kendaraan lawan… Apa Flaming Rally memang seperti ini, ya? Aku jadi ingin tahu bagaimana kabar mereka bertiga…",
  ui_story_5022_50220601_2_dialog_content = "Nah, apa kau merasakan seberapa mendebarkannya balapan ini?",
  ui_story_5022_50220601_3_dialog_content = "Tadinya kupikir ini hanya permainan belaka bagi Azure…",
  ui_story_5022_50220601_4_dialog_content = "Akan tetapi, dia benar-benar menikmatinya!",
  ui_story_5022_50220601_5_dialog_content = "Sebagai wanita, aku harus menjawab pelamarku.",
  ui_story_5022_50220601_6_dialog_content = "Ya, ini memang permainan, tapi tak bisa dianggap enteng.",
  ui_story_5022_50220601_7_dialog_content = "Kau benar-benar tampak fokus kalau mengemudi. Yakin tidak mau menyeriusinya?",
  ui_story_5022_50220601_8_dialog_content = "Aduh… yah…",
  ui_story_5022_50220601_9_dialog_content = "Sudah menyerah? Ck, ck… Mana mungkin kau bisa menikmati pestanya kalau tak tahu apa-apa?",
  ui_story_5022_50220601_10_dialog_content = "Meskipun begitu, kau pasti akan segera turut merasakan keseruannya. Heheh!",
  ui_story_5022_50220601_11_dialog_content = "… Apa maksudmu?",
  ui_story_5022_50220601_12_dialog_content = "Karena… kita sudah dekat dengan gunung apinya!",
  ui_story_5022_50220601_13_dialog_content = "Apa!?",
  ui_story_5022_50220601_14_dialog_content = "Oh, rupanya kau, Sinsa. Tadinya kupikir kau terkena batu yang berjatuhan. Siapa lagi yang bisa melompat masuk dari jendela seperti itu?",
  ui_story_5022_50220601_15_dialog_content = "Akhirnya terkejar juga.",
  ui_story_5022_50220601_16_dialog_content = "Kau mendengus, ya?",
  ui_story_5022_50220601_17_dialog_content = "Azure, tadi kau benar-benar ingin meninggalkan Sinsa…?",
  ui_story_5022_50220601_18_dialog_content = "Jangan bodoh, pasti memang begitu yang dia pikirkan. Untungnya aku ini pelari cepat!",
  ui_story_5022_50220601_19_dialog_content = "Sebentar, apa hanya aku saja yang merasa udaranya memanas?",
  ui_story_5022_50220601_20_dialog_content = "Kita memasuki bagian kedua balapan, <color=#FFB400>Dragon Breath Volcano</color>. Nah, kita pasti bisa keluar dari sini.",
  ui_story_5022_50220601_21_dialog_content = "Gunung berapi? Trek macam apa ini!?",
  ui_story_5022_50220601_22_dialog_content = "TIDAK lewat gunung api adalah rute tersingkat ke Blazing Tooth, tapi…",
  ui_story_5022_50220601_23_dialog_content = "Oh, aku terpaksa mengecewakan PlayerName yang baru saja memahami keseruan dalam balapan… Aku merasa sangat bersalah.",
  ui_story_5022_50220601_24_dialog_content = "Namun, sekarang kan kita sudah jadi teman. Kau boleh coba memegang kemudinya kapan pun.",
  ui_story_5022_50220601_25_dialog_content = "T-tidak, terima kasih! Perjalananku masih panjang!",
  ui_story_5022_50220601_26_dialog_content = "Jangan merendah begitu, PlayerName.",
  ui_story_5022_50220601_27_dialog_content = "Kau mahir dalam permainan dan berbakat mengemudi. Bayangkan.",
  ui_story_5022_50220601_28_dialog_content = "(Oh, permainan…)",
  ui_story_5022_50220601_29_dialog_content = "(Bagaimana kabar Vice, ya?)",
  ui_story_5022_50220601_30_dialog_content = "(Kami melewati semua petualangan yang menakjubkan dan berbahaya itu bersama-sama.)",
  ui_story_5022_50220601_31_dialog_content = "(Andai saja dia ada di sini…)",
  ui_story_5022_50220601_32_dialog_content = "Akkkkk! Hentikan! Maaf, Roy!",
  ui_story_5022_50220601_33_dialog_content = "Kau mulai mengoceh begitu aku pergi? Bagaimana dengan ketentuan tambahan yang berkali-kali kukatakan?",
  ui_story_5022_50220601_34_dialog_content = "Ayolah, Roy! Aku hanya menyembunyikan sebagian kebenaran untuk lebih memicu motivasi mereka… Aduh! Telingaku!",
  ui_story_5022_50220601_35_dialog_content = "Maaf, Teman-teman. Ada satu hal lagi: Penyelenggara acara berhak menjelaskan hadiah utamanya.",
  ui_story_5022_50220601_36_dialog_content = "Hanya satu permintaan saja yang boleh diajukan. Kalau ada perselisihan pendapat dalam tim, tolong jangan gunakan kekerasan brutal.",
  ui_story_5022_50220601_37_dialog_content = "Berusahalah semampu kalian. Semoga kontestan terbaik yang menang. Pertimbangkan permintaan kalian masak-masak.",
  ui_story_5022_50220601_38_dialog_content = "Kalau ada yang coba-coba curang, akan kupatahkan sendiri tulang kalian. Kalian semua dengar itu?",
  ui_story_5022_50220601_39_dialog_content = "N-nah, aku mau mengumumkan progres terbarunya.",
  ui_story_5022_50220601_40_dialog_content = "Pertama, Zeta, Sweet Evil God, adalah yang pertama mencapai stasiun pemeliharaan di gunung api.",
  ui_story_5022_50220601_41_dialog_content = "Kami akan segera menyiarkan status tim lain setelah iklan berikut ini…",
  ui_story_5022_50220601_42_dialog_content = "Cicipi sajian lezat di bawah bunga sakura…",
  ui_story_5022_50220601_43_dialog_content = "Diesel Sweety! Barbara! Oh, hore!",
  ui_story_5022_50220601_44_dialog_content = "Hah, rasanya aku mendengar sesuatu yang aneh…",
  ui_story_5022_50220601_45_dialog_content = "Angin keberuntungan akan menyampaikan berkatku.",
  ui_story_5022_50220601_46_dialog_content = "Apa kau mau merasakan… jamuan cita rasa terlezat…",
  ui_story_5022_50220601_47_dialog_content = "Lambaikan saja tanganmu… aku selalu menunggu di sini…",
  ui_story_5022_50220601_48_dialog_content = "Lalu datanglah… Kaniya Ramen! Lezat!",
  ui_story_5022_50220601_49_dialog_content = "*Uhuk* Sial…",
  ui_story_5022_50220601_50_dialog_content = "La la la! La la la! Bernyanyilah denganku!",
  ui_story_5022_50220601_51_dialog_content = "La la la! La la la!",
  ui_story_5022_50220601_52_dialog_content = "Iklannya dikalahkan oleh musik…",
  ui_story_5022_50220601_53_dialog_content = "Huh, baiklah. Diesel Sweety Barbara mengadakan pesta karaoke 300 lagu di konvoi di dekat Lepidoz…",
  ui_story_5022_50220601_54_dialog_content = "Sebagai staf Post-Rally Entertainment Division 2, dia…",
  ui_story_5022_50220601_55_dialog_content = "Dia tak peduli kalau aku hampir menarik telingaku sampai putus dan memulai tugasnya di waktu yang ditentukan!",
  ui_story_5022_50220601_56_dialog_content = "Omong-omong, kita alihkan perhatian ke yang hebat ini…",
  ui_story_5022_50220601_57_dialog_content = "Semua sudah berakhir!",
  ui_story_5022_50220601_58_dialog_content = "Sial… Regina? Aku tak tahu kalau dia akan datang!",
  ui_story_5022_50220601_59_dialog_content = "Jomu, kau benar-benar ingin tetap netral, 'kan?",
  ui_story_5022_50220601_60_dialog_content = "Bersikap netral itu bagus untuk bisnis. Nah, kita singkirkan dulu gergaji itu, ya?",
  ui_story_5022_50220601_61_dialog_content = "Tak akan kubiarkan pekikanmu yang mengerikan itu menyakiti telinga semua orang, Barbara!",
  ui_story_5022_50220601_62_dialog_content = "Aku akan menghancurkanmu dengan musikku yang berapi-api!",
  ui_story_5022_50220601_63_dialog_content = "Regina, kau tak bisa menakutiku!",
  ui_story_5022_50220601_64_dialog_content = "Barbara! Barbara!",
  ui_story_5022_50220601_65_dialog_content = "Solar Storm! Solar Storm!",
  ui_story_5022_50220601_66_dialog_content = "La la la! Keberuntunganmu, keberuntunganku! Ayo bergandengan!",
  ui_story_5022_50220601_67_dialog_content = "Huh, dia mendahuluiku! Teman-teman, ayo goyang!",
  ui_story_5022_50220601_68_dialog_content = "Groar! Groar! Siapa yang bisa selamatkan kita dari kebuntuan ini!?",
  ui_story_5022_50220601_69_dialog_content = "Sial! Matikan stasiunnya! Kepalaku jadi berdenyut-denyut!",
  ui_story_5022_50220601_70_dialog_content = "Oh, hanya ini saja kemampuanmu, Caelestite?",
  ui_story_5022_50220601_71_dialog_content = "Menurut kebiasaan Flaming Rally, bagian serunya belum muncul.",
  ui_story_5022_50220601_72_dialog_content = "Para pengemudi memperebutkan posisi, perselisihan Diesel Sweety dan Solar Storm sudah mencapai puncaknya!",
  ui_story_5022_50220601_73_dialog_content = "Dengar, Diesel Sweety memilih lagu yang ceria. Nada tingginya yang manis bisa memecahkan gelas anggur!",
  ui_story_5022_50220601_74_dialog_content = "Nah, kalau Solar Storm, lagunya sudah sampai chorus!",
  ui_story_5022_50220601_75_dialog_content = "Dia mau memilih nada pembangkit semangat yang mana, ya? Ayo kita cari tahu…",
  ui_story_5022_50220601_76_dialog_content = "Begitu rupanya! Dia akan… akan…",
  ui_story_5022_50220601_77_dialog_content = "Solar Storm tidak menghancurkan gitarnya untuk membuat efek dramatis. Dia justru melemparkannya!",
  ui_story_5022_50220601_78_dialog_content = "Solar Storm sudah turun dari panggung!",
  ui_story_5022_50220601_79_dialog_content = "Solar Storm… Dia melompat ke trofi yang dia peroleh dari pengejaran Lumopolis! Kapal udara!",
  ui_story_5022_50220601_80_dialog_content = "Solar Storm menaiki kapal udara itu… dan menabrakkannya ke bebatuan!",
  ui_story_5022_50220601_81_dialog_content = "Huh! Roti goreng! <size=45>Dengarkan musikku yang sesungguhnya!</size>",
  ui_story_5022_50220601_82_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5022_50220601_83_dialog_content = "Meledak!?",
  ui_story_5022_50220601_84_dialog_content = "Di mana Lepidoz? Seharusnya itu tidak memengaruhi kita…",
  ui_story_5022_50220601_85_dialog_content = "<color=#e8d9bb>Ugh… Ah!</color>",
  ui_story_5022_50220601_86_dialog_content = "Yah, itu tidak bisa dipastikan.",
  ui_story_5022_50220601_87_dialog_content = "Suara apa itu?",
  ui_story_5022_50220601_88_dialog_content = "D-dinding tebing di sebelah kiri runtuh!",
  ui_story_5022_50220601_89_dialog_content = "Tenang saja. Maju terus.",
  ui_story_5022_50220601_90_dialog_content = "Kenapa kau takut? Di sebelah kanan aman, 'kan?",
  ui_story_5022_50220601_91_dialog_content = "Namun, Azure sudah tancap gas dan aku bisa merasakan…",
  ui_story_5022_50220601_92_dialog_content = "Sebelah sana penuh Eclipsite!",
  ui_story_5022_50220602_1_dialog_content = "Hei, PlayerName. Kau boleh buka mata sekarang. PlayerName?",
  ui_story_5022_50220602_2_dialog_content = "Hah? Belum siuman? Benar-benar ketakutan, ya?",
  ui_story_5022_50220602_3_dialog_content = "Rupanya memang masih kurang berpengalaman, ya. Kau harus lebih sering ikut balapan.",
  ui_story_5022_50220602_4_dialog_content = "Tidak mungkin!",
  ui_story_5022_50220602_5_dialog_content = "Wah, ini benar-benar keajaiban medis! Padahal kita tidak melakukan apa-apa!",
  ui_story_5022_50220602_6_dialog_content = "Lebih sering ikut balapan? Masih bisa hidup saja sudah keajaiban!",
  ui_story_5022_50220602_7_dialog_content = "Hei, jangan bawa-bawa keajaiban untuk hal semudah ini.",
  ui_story_5022_50220602_8_dialog_content = "Biar kujelaskan. Bagaimanapun juga, aku memang lebih sabar kalau menghadapi anak manis.",
  ui_story_5022_50220602_9_dialog_content = "Buka matamu dan lihat jalannya dengan cermat. Di sisi sebelah sini ada tebing dan sisi sebelah sana ada dinding batu.",
  ui_story_5022_50220602_10_dialog_content = "Benar. Aku lihat.",
  ui_story_5022_50220602_11_dialog_content = "Nah, tempat ini ada di dekat tepi Eternal Night. Biasanya, Eclipsite bersembunyi di balik bayangan dinding batu untuk mengurangi penggunaan energi.",
  ui_story_5022_50220602_12_dialog_content = "Ah, sekarang aku paham.",
  ui_story_5022_50220602_13_dialog_content = "Artinya, para Eclipsite itu mudah dihindari asalkan kita menemukan sudut yang tepat.",
  ui_story_5022_50220602_14_dialog_content = "Aku mengerti sekarang…",
  ui_story_5022_50220602_15_dialog_content = "TIDAK!",
  ui_story_5022_50220602_16_dialog_content = "Menggunakan Eclipsite sebagai bantalan itu tidak wajar!",
  ui_story_5022_50220602_17_dialog_content = "Jangan dipikirkan, PlayerName. Rasakan saja.",
  ui_story_5022_50220602_18_dialog_content = "Benar! Percayalah pada Azure!",
  ui_story_5022_50220602_19_dialog_content = "Aduh… Hanya aku yang meragukannya… Firasatku sangat buruk…",
  ui_story_5022_50220602_20_dialog_content = "Vice…",
  ui_story_5022_50220602_21_dialog_content = "Vice… Aku membutuhkanmu di sini…",
  ui_story_5022_50220602_22_dialog_content = "(Kalau saja dulu aku minta maaf padanya…)",
  ui_story_5022_50220602_23_dialog_content = "<color=#e8d9bb>Kresek… Kresek…</color>",
  ui_story_5022_50220602_24_dialog_content = "Caelestite? Caelestite? Kau di sana?",
  ui_story_5022_50220602_25_dialog_content = "Lagi?",
  ui_story_5022_50220602_26_dialog_content = "K-kau kenapa? Kau habis menyantap makanan kotor dari tanah? Atau kau sudah gila karena kepanasan?",
  ui_story_5022_50220602_27_dialog_content = "Aduh… Apa kabar, Zeta?",
  ui_story_5022_50220602_28_dialog_content = "Apa kabar? Kau lelet. Terlalu lelet! Apa kau sudah di dekat gunung berapinya?",
  ui_story_5022_50220602_29_dialog_content = "Ini bukan pertarungan! Satu pihak melumat yang lain!",
  ui_story_5022_50220602_30_dialog_content = "Bagaimana? Nona Sweet Evil God sudah sampai di garis finis?",
  ui_story_5022_50220602_31_dialog_content = "Huh! Aku sudah keluar dari Magma Lake. Di luar dugaanmu, 'kan!?",
  ui_story_5022_50220602_32_dialog_content = "Aku juga sudah mendapat Amulet of Frost untuk menangkal panas dari Tiny One, ahli senjata dari para kesatria di stasiun pemeliharaan!",
  ui_story_5022_50220602_33_dialog_content = "*Sroot*",
  ui_story_5022_50220602_34_dialog_content = "Suara apa itu…?",
  ui_story_5022_50220602_35_dialog_content = "Nona Sweet Evil God sangat hebat! Aku takut sekali!",
  ui_story_5022_50220602_36_dialog_content = "Tak ada gunanya berpura-pura tak peduli. Aku pembalap. Kau tak bisa mengecohku. Kau pasti ingin mengalahkanku!",
  ui_story_5022_50220602_37_dialog_content = "Sayangnya, sudah terlalu lama kau tak memainkannya dan kau tak punya keunggulan apa-apa lagi!",
  ui_story_5022_50220602_38_dialog_content = "Yang lebih penting, rasa takut akan kematian dan kekalahan telah menggerogotimu dari dalam!",
  ui_story_5022_50220602_39_dialog_content = "Sebagai pembalap, kau hanyalah debu. Sama sekali tak berharga!",
  ui_story_5022_50220602_40_dialog_content = "Akulah yang akan mengalahkan naga iblis itu. Aku jugalah yang akan jadi jawara!",
  ui_story_5022_50220602_41_dialog_content = "Saksikan kemenanganku!",
  ui_story_5022_50220602_42_dialog_content = "Bagus. Aku sama sekali tak gagap dan tak melewatkan satu baris pun…!",
  ui_story_5022_50220602_43_dialog_content = "Mestinya kaumatikan dulu Communicator-mu sebelum kau mengembus napas lega tadi!",
  ui_story_5022_50220602_44_dialog_content = "Huh, pasti dia berlatih mengucapkannya di depan cermin. Tadi itu jauh lebih lancar daripada ejekannya yang terakhir kali.",
  ui_story_5022_50220602_45_dialog_content = "Sinsa juga balapan melawan Zeta?",
  ui_story_5022_50220602_46_dialog_content = "Terakhir kali dulu, dia mendapatkan peringkat kedua, dan menantangku untuk balapan di panggung.",
  ui_story_5022_50220602_47_dialog_content = "Dia menangis terisak-isak, jadi aku tak sepenuhnya paham apa yang dikatakannya.",
  ui_story_5022_50220602_48_dialog_content = "Untungnya, Roy menjauhkannya dariku…",
  ui_story_5022_50220602_49_dialog_content = "Ejekannya sungguh sengit… Bahkan Azure sekalipun tak tahu harus bilang apa.",
  ui_story_5022_50220602_50_dialog_content = "Azure…?",
  ui_story_5022_50220602_51_dialog_content = "Untuk sementara ini, adu lagu antara Solar Storm dan Diesel Sweety sudah berakhir.",
  ui_story_5022_50220602_52_dialog_content = "Sekarang, kita alihkan perhatian ke balapannya.",
  ui_story_5022_50220602_53_dialog_content = "Dengan gembira kuumumkan bahwa, para kontestan yang berhasil mencapai Dragon Breath Volcano, bagian kedua dari balapan ini…",
  ui_story_5022_50220602_54_dialog_content = "<size=45>Hanya sedikit!</size>",
  ui_story_5022_50220602_55_dialog_content = "Baiklah, tak apa. Ini bukan hal yang perlu digembar-gemborkan. Yang lebih layak disebut adalah…",
  ui_story_5022_50220602_56_dialog_content = "Beberapa kontestan sangat tertarik dengan iklan Kaniya Ramen dan es serut Octobro sampai-sampai mereka meninggalkan permainan ini demi memuaskan perut mereka!",
  ui_story_5022_50220602_57_dialog_content = "Oh, tapi, tak perlu kecewa!",
  ui_story_5022_50220602_58_dialog_content = "Menurut catatan sejarah, yang mampu melintasi gurun panas ini hanyalah yang terbaik.",
  ui_story_5022_50220602_59_dialog_content = "Entah itu lingkungan yang keras maupun kerja sama tim, semuanya adalah tantangan besar yang harus diatasi.",
  ui_story_5022_50220602_60_dialog_content = "Apa kau masih ingat bagaimana kita menemukan jalur hebat ini tanpa sengaja saat kita tersesat?",
  ui_story_5022_50220602_61_dialog_content = "Waktu itu, aku benar-benar mengira kita akan mati dalam operasi pencarian dan penyelamatan itu! Hahaha!",
  ui_story_5022_50220602_62_dialog_content = "Aku ingat ada orang yang menyarankan kita memakai papan reyot yang dicopot dari mobil untuk berselancar menuruni aliran magma…",
  ui_story_5022_50220602_63_dialog_content = "Aliran magma!?",
  ui_story_5022_50220602_64_dialog_content = "Uhh… Tidak. Tak ingat. Namun, ada seorang kontestan yang berusaha membekukan seluruh Magma Lake…",
  ui_story_5022_50220602_65_dialog_content = "Dan ada seorang kontestan lain yang berusaha membelah mobil lawannya menjadi enam bagian dengan sebilah pisau. Akan tetapi, entah bagaimana, sang pilot berhasil keluar hanya dengan luka pada egonya…",
  ui_story_5022_50220602_66_dialog_content = "Sayangnya, kedua kontestan itu jarang kembali dan mereka menggunakan nama samaran, jadi…",
  ui_story_5022_50220602_67_dialog_content = "Oh, betapa inginnya kami melihat mereka lagi. Eh, aku hanya melantur, sih.",
  ui_story_5022_50220602_68_dialog_content = "Oh, ya, kami juga menyadari bahwa sekitar saat itu, aktivitas Eclipsite meningkat banyak.",
  ui_story_5022_50220602_69_dialog_content = "Bagi para pembalap yang sudah berpengalaman, Eclipsite biasa bukanlah ancaman…",
  ui_story_5022_50220602_70_dialog_content = "Akan tetapi, lain ceritanya kalau yang harus mereka hadapi adalah Wicked Dragon Hakudoma!",
  ui_story_5022_50220602_71_dialog_content = "Kalau memang benar begitu, kita harus meluncurkan suvenir edisi terbatas bertema naga buas untuk mengeruk keuntungan!",
  ui_story_5022_50220602_72_dialog_content = "Memangnya siapa yang bakal tertarik…?",
  ui_story_5022_50220602_73_dialog_content = "Odi dari Post-Logistics Division 3 sedang memantau wilayah ini melalui jaringan komunikasi yang sudah ada di Lepidoz.",
  ui_story_5022_50220602_74_dialog_content = "Sejauh ini, tak ada tanda-tanda Eclipsite berukuran besar.",
  ui_story_5022_50220602_75_dialog_content = "Sungguh melegakan… dan mengecewakan! Nah, sekarang saatnya jeda iklan! Crunchy Munchy Crunch, satu paket isi tiga mangkuk nasi…",
  ui_story_5022_50220602_76_dialog_content = "… Tidak?",
  ui_story_5022_50220602_77_dialog_content = "(Kenapa Azure tampak seperti… kecewa?)",
  ui_story_5022_50220602_78_dialog_content = "Azure, apa kau berharap Wicked Dragon Hakudoma muncul?",
  ui_story_5022_50220602_79_dialog_content = "Memangnya kelihatan dari wajahku?",
  ui_story_5022_50220602_80_dialog_content = "Caelestite, jangan coba-coba mengintip pikiranku.",
  ui_story_5022_50220602_81_dialog_content = "Namun, karena aksimu bagus saat kita melawan para kontestan lain… kau boleh melakukannya, sekali ini saja.",
  ui_story_5022_50220602_82_dialog_content = "Jalur ini punya makna khusus bagiku.",
  ui_story_5022_50220602_83_dialog_content = "Di sinilah aku belajar mengemudi dan ikut serta dalam Blazing Rally untuk pertama kalinya. Aku pun selalu berhasil memecahkan rekornya.",
  ui_story_5022_50220602_84_dialog_content = "Jalur ini dipenuhi kenanganku, yang paling manis sampai yang paling pahit.",
  ui_story_5022_50220602_85_dialog_content = "Aku pernah merasakan kalah telak di sini dan menemukan musuh yang membuatku bersumpah akan membunuhnya.",
  ui_story_5022_50220602_86_dialog_content = "Suatu hari, akan kupecahkan tengkoraknya dan kuremukkan tulang punggungnya, lalu kulumat sampai jadi abu di bawah kakiku.",
  ui_story_5022_50220602_87_dialog_content = "Aku hanya berharap hari inilah saatnya.",
  ui_story_5022_50220602_88_dialog_content = "Dia tak boleh mati dan hilang begitu saja sebelum aku sempat membuat ususnya terburai.",
  ui_story_5022_50220602_89_dialog_content = "Apa? Omonganku membuatmu takut?",
  ui_story_5022_50220602_90_dialog_content = "Bukan takut…",
  ui_story_5022_50220602_91_dialog_content = "Akan tetapi, aku jadi tahu sedikit tentang dirimu yang sebenarnya.",
  ui_story_5022_50220602_92_dialog_content = "Kau mungkin tampak dungu dan pengecut, tapi kau jelas tahu cara menyenangkan orang lain.",
  ui_story_5022_50220602_93_dialog_content = "Berapa banyak orang yang berhasil kaukibuli dengan kata-katamu yang semanis madu itu?",
  ui_story_5022_50220602_94_dialog_content = "A-aku hanya berkata sejujurnya…",
  ui_story_5022_50220602_95_dialog_content = "Namun, kenapa kau sangat bersikukuh tentang Eclipsite yang satu ini?",
  ui_story_5022_50220602_96_dialog_content = "Kau benar-benar suka mendengarkan cerita, ya, Caelestite?",
  ui_story_5022_50220602_97_dialog_content = "Maksudku, sudah bertahun-tahun cerita ini beredar.",
  ui_story_5022_50220602_98_dialog_content = "Mungkin aku seharusnya lebih khawatir akan kalah dari Zeta dan keinginannya yang satu itu.",
  ui_story_5022_50220602_99_dialog_content = "Apa ada aturan untuk duelnya?",
  ui_story_5022_50220602_100_dialog_content = "Yang kauhadapi itu Zeta. Dia tak akan setengah-setengah menghadapimu.",
  ui_story_5022_50220602_101_dialog_content = "Eh, Caelestite, jangan bilang begitu, seakan-akan ini tak ada hubungannya denganmu.",
  ui_story_5022_50220602_102_dialog_content = "Kita ini rekan tim. Apa yang harus terjadi, terjadilah. Kita akan menanggung segalanya bersama, 'kan?",
  ui_story_5022_50220602_103_dialog_content = "Hah?",
  ui_story_5022_50220602_104_dialog_content = "Kurasa di sini perhentianku…",
  ui_story_5022_50220602_105_dialog_content = [[
Ha. Jangan keburu panik.|
Permainannya baru saja mulai.]],
  ui_story_5022_50220802_1_dialog_content = "Akhirnya kita sampai di stasiun pemeliharaan… Aku sungguh lelah. Ada banyak sekali Eclipsite…",
  ui_story_5022_50220802_2_dialog_content = "Azure, akhirnya kau datang juga! Silakan, parkirlah mobilmu di sini…",
  ui_story_5022_50220802_3_dialog_content = "Kau, periksa komponen yang perlu diganti!",
  ui_story_5022_50220802_4_dialog_content = "Lalu, bannya… Kau! Iya, kau! Keluarkan bannya!",
  ui_story_5022_50220802_5_dialog_content = "Dan kau, angkat pantatmu dan mulailah bekerja!",
  ui_story_5022_50220802_6_dialog_content = "Ya!",
  ui_story_5022_50220802_7_dialog_content = "Bagus sekali, Tiny One. Kau memang paham cara menyelesaikan pekerjaan.",
  ui_story_5022_50220802_8_dialog_content = "Heheh.",
  ui_story_5022_50220802_9_dialog_content = "Orang-orang ini… Kapan sih mereka bisa paham?",
  ui_story_5022_50220802_9X1_dialog_content = "<size=45>Hoi, hoi! Hentikan!</size>",
  ui_story_5022_50220802_10_dialog_content = "Daripada mengkhawatirkan tinggi badanku…",
  ui_story_5022_50220802_11_dialog_content = "Hah? PlayerName? Aku tak menyangka akan bertemu denganmu di sini.",
  ui_story_5022_50220802_12_dialog_content = "Orang seringkih dirimu ternyata berhasil sampai sejauh ini… Aku terkesan.",
  ui_story_5022_50220802_13_dialog_content = "Kedengarannya seperti bukan pujian…",
  ui_story_5022_50220802_14_dialog_content = "Orang pendek sepertimu malah menyebutku payah…",
  ui_story_5022_50220802_14X1_dialog_content = "<size=45>Hoi! Sudahlah!</size>",
  ui_story_5022_50220802_15_dialog_content = "Baiklah, sudah cukup. Sebentar lagi Magma Lake Life Ender. Tikungan itu adalah bagian tersulit dari lintasan ini. Kalian siap?",
  ui_story_5022_50220802_16_dialog_content = "Aduh! Tunggu… Magma Lake apa?",
  ui_story_5022_50220802_17_dialog_content = "Persis seperti namanya. Danau berisi magma cair.",
  ui_story_5022_50220802_18_dialog_content = "Maksudku, bagian itu lumayan jelas…",
  ui_story_5022_50220802_S18_dialog_content = "Baiklah, baiklah, aku mendengarkan! Jangan pukul aku!",
  ui_story_5022_50220802_19_dialog_content = "Kalau sampai jatuh ke dalamnya, suhu magmanya cukup untuk membuat kita menyublim seluruhnya.",
  ui_story_5022_50220802_20_dialog_content = "Penyelenggara acara memang memberikan peralatan bagi para kontestan untuk mengatasi panas dan udara beracun, tapi kau tetap akan merasa seakan-akan napasmu menyemburkan api.",
  ui_story_5022_50220802_21_dialog_content = "Kalau begitu… Apa yang harus kita lakukan?",
  ui_story_5022_50220802_22_dialog_content = "Begitu saja sudah takut, nih? Omong-omong… Bagaimana kalau kita makan sekotak Vactus Jello dulu?",
  ui_story_5022_50220802_23_dialog_content = "Jadi, ini bisa menangkal panas? Tanaman gurun memang luar biasa, ya…",
  ui_story_5022_50220802_24_dialog_content = "Tidak. Tidak sama sekali.",
  ui_story_5022_50220802_25_dialog_content = "Hah?",
  ui_story_5022_50220802_26_dialog_content = "Rasanya enak. Itu saja.",
  ui_story_5022_50220802_27_dialog_content = "Nah, sekarang mari kita dengarkan laporan dari tim!",
  ui_story_5022_50220802_28_dialog_content = "Sebenarnya aku ingin minta jeda iklan, tapi sponsor kami tak terlalu banyak… Aku bahkan harus memasarkan sendiri produk-produkku…",
  ui_story_5022_50220802_29_dialog_content = "*Sroot*",
  ui_story_5022_50220802_30_dialog_content = "Sweet Devil masih memimpin. Azure, sang juara kedua, tertinggal cukup jauh!",
  ui_story_5022_50220802_31_dialog_content = "Polar Fire, Team Kafka, dan para kontestan lain yang telah tereliminasi sudah dijemput oleh Lepidoz dan sedang menjalani perbaikan.",
  ui_story_5022_50220802_32_dialog_content = "Kalau sampai ada yang terlewat tak kusebutkan, itu salah kalian sendiri karena sulit ditemukan. Berusahalah lebih keras lagi!",
  ui_story_5022_50220802_33_dialog_content = "Muntahkan saja darahnya, lalu lanjutkan! Aku yakin kau pasti bisa! Jangan berhenti!",
  ui_story_5022_50220802_34_dialog_content = "Sebagai teladan luar biasa untuk kalian, My Super Dream Team sudah diperbaiki oleh Fleur dan sekarang kembali terjun ke dalam permainan!",
  ui_story_5022_50220802_35_dialog_content = "Kalau tak bisa memperbaiki kendaraan kalian sendiri, tunggu saja sampai Chainsaw Rick dan Rabbie menyelamatkan kalian!",
  ui_story_5022_50220802_36_dialog_content = "Setidaknya kami akan mengambil komponen-komponen jatuhan kalian yang terkubur dalam pasir. Tak usah khawatir!",
  ui_story_5022_50220802_37_dialog_content = "(Baiklah… Rasanya memang enak. Akan tetapi, makanan ini tak akan bisa menangkal panas dan juga bukan Amulet of Frost…)",
  ui_story_5022_50220802_38_dialog_content = "Zeta tak terhentikan dalam balapan ini. Dia berhasil membuktikan kemampuannya yang luar biasa sebagai pembalap.",
  ui_story_5022_50220802_39_dialog_content = "Dia juga banyak terbantu oleh pemahamannya tentang Blazing Tooth dan pertambangan!",
  ui_story_5022_50220802_40_dialog_content = "(Akan kubawa pulang beberapa untuk oleh-oleh bagi semua orang di Colossus.)",
  ui_story_5022_50220802_41_dialog_content = "Hasil balapan ini sepertinya sulit diubah… Hah? Odi? Ada masalah apa?",
  ui_story_5022_50220802_42_dialog_content = "<color=#e8d9bb>Kresek… Kresek…</color>",
  ui_story_5022_50220802_43_dialog_content = "Ini Odi, Post-Logistics Division 3.",
  ui_story_5022_50220802_44_dialog_content = "Semuanya, dengarkan.",
  ui_story_5022_50220802_45_dialog_content = "Ada masalah.",
  ui_story_5022_50220901_1_dialog_content = "Kami mendeteksi sejumlah besar Eclipsite di antara Dragon Breath Volcano dan Blazing Tooth.",
  ui_story_5022_50220901_2_dialog_content = "Kali ini, gerakan mereka membuat pasir dan debu berhamburan sehingga sulit dilacak secara visual…",
  ui_story_5022_50220901_3_dialog_content = "Namun, ukuran dan kecepatan salah satu dari mereka sama persis dengan data Eclipsite tipe Dragon yang pernah ada dalam sejarah…",
  ui_story_5022_50220901_4_dialog_content = "Dia bergerak di sepanjang jalur, tapi kami kesulitan menghubungi Zeta karena terhalang pasir dan debu…",
  ui_story_5022_50220901_5_dialog_content = "Kami akan berusaha memperbaiki komunikasi dengan staf di area itu dan terus mengabarkan perkembangannya kepada kalian.",
  ui_story_5022_50220901_6_dialog_content = "Kalian semua, hati-hati, ya!",
  ui_story_5022_50220901_7_dialog_content = "Saat balapan mencapai babak terakhir, ada tamu tak terduga yang datang!",
  ui_story_5022_50220901_8_dialog_content = "Dia adalah si Eclipsite legendaris, Hakudoma dari dunia bayangan…",
  ui_story_5022_50220901_9_dialog_content = "Darurat! Komando kuambil alih!",
  ui_story_5022_50220901_10_dialog_content = "Saat ini, hanya ada satu jalan bagi Zeta untuk melintasi jurang di depannya. Kemungkinan besar, kawanan Eclipsite itu akan bisa menyusulnya.",
  ui_story_5022_50220901_11_dialog_content = "…!!",
  ui_story_5022_50220901_12_dialog_content = "Dia takkan bisa menanganinya sendiri. Namun, anak itu adalah salah satu aset terbaik kita...",
  ui_story_5022_50220901_13_dialog_content = "Meski mungkin akan ketakutan, dia bisa bertahan sebentar.",
  ui_story_5022_50220901_14_dialog_content = "Tim Post-Logistics di area Blazing Tooth akan segera dikerahkan untuk membantunya.",
  ui_story_5022_50220901_15_dialog_content = "Kita butuh waktu untuk sampai ke sana dengan kendaraan biasa. Kontestan paling dekat, Azure, kami percayakan tugas ini kepadamu.",
  ui_story_5022_50220901_16_dialog_content = "Begitu Lepidoz sampai di area komunikasi, aku akan menugaskan tim untuk menyingkirkan kawanan Eclipsite itu satu per satu. Tetap siagakan Communicator milikmu.",
  ui_story_5022_50220901_17_dialog_content = "Roy terdengar sangat tenang… Namun, sebenarnya situasinya parah, 'kan?",
  ui_story_5022_50220901_18_dialog_content = "Tiny One, bisa coba perkirakan posisi Zeta berdasarkan waktu saat dia keluar dari stasiun pemeliharaan?",
  ui_story_5022_50220901_19_dialog_content = "Berdasarkan kecepatan geraknya, mestinya dia sudah sangat dekat dengan jalan masuk ke jurang.",
  ui_story_5022_50220901_20_dialog_content = "Akan butuh waktu untuk sampai di sana. Bahkan kau harus melambat melewati Magma Lake Life Ender…",
  ui_story_5022_50220901_21_dialog_content = "Tentu saja, kalau lewat rute biasa, kita tak akan sampai di sana tepat waktu.",
  ui_story_5022_50220901_22_dialog_content = "Kalau saja aku melintasi area itu lewat rute patroliku yang biasanya dan bukannya terjun ke dalam balapan ini…",
  ui_story_5022_50220901_23_dialog_content = "Sekarang bukan saatnya menyesalinya.",
  ui_story_5022_50220901_24_dialog_content = "Caelestite, karena kau bisa melihat aliran cahaya, mungkin kau bisa menciptakan jaringan sensoris dengan beberapa Aurorian, seperti yang dulu pernah kaulakukan?",
  ui_story_5022_50220901_25_dialog_content = "Tentu saja… tapi aku tak tahu bagaimana itu bisa membantu kita melewati Magma Lake…",
  ui_story_5022_50220901_26_dialog_content = "Jangan khawatir.",
  ui_story_5022_50220901_27_dialog_content = "Aku sudah menemukan rute.",
  ui_story_5022_50220901_28_dialog_content = "Kau sudah siap, Caelestite?",
  ui_story_5022_50220901_S28_dialog_content = "Kurasa, tapi…",
  ui_story_5022_50220901_29_dialog_content = "Ya ampun… Sudah berapa kali kusaksikan hidupku seakan-akan bakalan tamat…?",
  ui_story_5022_50220901_30_dialog_content = "Aku akan mengebut agar kita bisa sampai ke atas sana.",
  ui_story_5022_50220901_31_dialog_content = "Memangnya tak ada cara lain—Ahhhhhhhhh!",
  ui_story_5022_50220901_32_dialog_content = "<anim type=Shake><size=45>K-kita terbang!</size></anim>",
  ui_story_5022_50220901_32X1_dialog_content = "(Jo-Jo-Jo-Joanie—)",
  ui_story_5022_50220901_33_dialog_content = "Sinsa, memangnya rencana segila ini bakal berhasil?",
  ui_story_5022_50220901_34_dialog_content = "Berdasarkan analisis dan perhitunganku, secara teknis, mestinya berhasil, tapi…",
  ui_story_5022_50220901_35_dialog_content = "Menendang bom, menembakkan bom, dan memanfaatkan ledakannya agar bom-bom itu meluncur maju dan membuat mobil itu terlontar ke Magma Lake?",
  ui_story_5022_50220901_36_dialog_content = "Menurut standar mana pun, ini konyol!",
  ui_story_5022_50220901_37_dialog_content = "Akan tetapi, mereka itu Azure dan PlayerName. Taktik ini pasti berhasil!",
  ui_story_5022_50220901_38_dialog_content = "Eh, itu mereka! Lihat di sana, di atas Magma Lake! Mereka berhasil meluncur sangat tinggi!",
  ui_story_5022_50220901_39_dialog_content = "Hehehe, rencana ini seru sekali dan dijamin antigagal!",
  ui_story_5022_50220901_40_dialog_content = "Hanya karena kau bersenang-senang, bukan berarti kau harus mengumumkannya kepada semua orang!",
  ui_story_5022_50220901_41_dialog_content = "Jangan menatapku terus! Kalau sampai terjadi sesuatu pada mereka, akulah yang akan pertama turun tangan menyelamatkan mereka!",
  ui_story_5022_50220901_42_dialog_content = "Tunggu! PlayerName berbicara denganku lewat telepati!",
  ui_story_5022_50220901_43_dialog_content = "Pemukul… bisbol… Aduh. Oh! Siapkan para Wrench? Akan kulontarkan bomnya!",
  ui_story_5022_50220901_44_dialog_content = "Kau pasti bisa!",
  ui_story_5022_50220901_45_dialog_content = "(Nah, Sinsa, sekarang arahkan ke lokasi yang sudah kutandai—)",
  ui_story_5022_50220901_46_dialog_content = "Baiklah, ini dia!",
  ui_story_5022_50220901_47_dialog_content = "Bom datang, Azure! Siap—",
  ui_story_5022_50220901_47X1_dialog_content = "<size=45>Tembak!!</size>",
  ui_story_5022_50220901_47X2_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5022_50220901_48_dialog_content = "<color=#e8d9bb>DUAR!</color>",
  ui_story_5022_50220901_49_dialog_content = "Berhasil! Beberapa kali lagi…",
  ui_story_5022_50220901_50_dialog_content = "(Aku harus menjaga keseimbangan. Kalau aku geser sedikit ke kanan… Bagus!)",
  ui_story_5022_50220901_51_dialog_content = "(Tak apa. Kalaupun terjadi hal terburuk sekalipun…)",
  ui_story_5022_50220901_52_dialog_content = "Aaaah!",
  ui_story_5022_50220901_53_dialog_content = "PlayerName!",
  ui_story_5022_50220901_54_dialog_content = "(Jangan lihat ke bawah… Jangan lihat, jangan lihat, jangan lihat ke bawah!)",
  ui_story_5022_50220901_55_dialog_content = "Eh, kalau kau benar-benar berniat menjauhiku, mestinya kaupilih waktu yang lebih tepat.",
  ui_story_5022_50220901_56_dialog_content = "Atau, kau ingin aku melepaskan peganganku?",
  ui_story_5022_50220901_57_dialog_content = "Jangan mengejekku lagi, Azure… Kita…",
  ui_story_5022_50220901_58_dialog_content = "Hm…? Ternyata kita tergelincir jatuh tak terlalu cepat…",
  ui_story_5022_50220901_59_dialog_content = "Kaulihat batuan magma yang mengambang itu?",
  ui_story_5022_50220901_60_dialog_content = "Dragon Breath Volcano adalah fenomena geografis karena benda-benda di dekatnya akan mengambang dalam jarak tertentu.",
  ui_story_5022_50220901_61_dialog_content = "Waow…",
  ui_story_5022_50220901_62_dialog_content = "Indah, 'kan? Meskipun begitu, kalaupun jumlah penumpangnya dikurangi dua orang, kita tetap saja jauh lebih berat daripada batu-batuan ini.",
  ui_story_5022_50220901_63_dialog_content = "Jadi, kalau kau tak segera kembali ke sini dan terus berusaha…",
  ui_story_5022_50220901_64_dialog_content = "Mestinya kaubilang dari tadi, dong!",
  ui_story_5022_50220901_65_dialog_content = "Ledakan terakhir!",
  ui_story_5022_50220901_66_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5022_50220901_67_dialog_content = "Oh! Lihat itu! Mereka berhasil sampai ke seberang Magma Lake!",
  ui_story_5022_50220901_68_dialog_content = "Mereka sungguh berhasil. Belum pernah ada kontestan yang mencoba cara seperti itu…",
  ui_story_5022_50220901_69_dialog_content = "Ini bukan saatnya memikirkan itu! High-Level Eclipsite itu…",
  ui_story_5022_50220901_70_dialog_content = "Apa maksudmu? Balapannya belum selesai!",
  ui_story_5022_50220901_71_dialog_content = "Benar. Kita baru saja menambahkan misi pencarian dan penyelamatan berbungkus tantangan Bos dengan sampingan berburu Eclipsite!",
  ui_story_5022_50220901_72_dialog_content = "Aku penasaran, ancaman macam apa yang akan ditimbulkan naga itu… Seru sekali!",
  ui_story_5022_50220901_73_dialog_content = "Tiny One! Sebaiknya sesekali kau pergi keluar. Kalau tidak, bisa-bisa otakmu berkarat!",
  ui_story_5022_50220901_74_dialog_content = "Pesta tanpa tamu tak terduga sama sekali tak bisa disebut pesta!",
  ui_story_5022_50220901_75_dialog_content = "Kalau tak segera ke sana, kau hanya akan dapat sisa-sisanya!",
  ui_story_5022_50220901_76_dialog_content = "Yah… Memang ada kendaraan cadangan di stasiun pemeliharaan, sih…",
  ui_story_5022_50220901_77_dialog_content = "Aku ikut. Harus ada orang yang bertugas menjaga agar kecerdasan intelektual tim cukup tinggi.",
  ui_story_5022_50220901_78_dialog_content = "Kalau begitu, tunggu apa lagi!? Saatnya berpesta!",
  ui_story_5022_50220901_79_dialog_content = "Target: <color=#FFB400>Blazing Tooth</color>!",
  ui_story_5022_50221001_1_dialog_content = "Humph… Aku tak percaya… Kita benar-benar berhasil!",
  ui_story_5022_50221001_2_dialog_content = "Tak ada hal lain yang bisa membuatku kaget—",
  ui_story_5022_50221001_3_dialog_content = "Tidak, sebaiknya jangan mengacaukannya… Aku masih di sini bersama Rediesel Wrench.",
  ui_story_5022_50221001_4_dialog_content = "Lihat, 'kan? Kau mulai mahir, PlayerName.",
  ui_story_5022_50221001_5_dialog_content = "(Apa barusan Azure… menyebut namaku?)",
  ui_story_5022_50221001_6_dialog_content = "(Kalau begitu, saat dia memegangku di Magma Lake, dia juga…)",
  ui_story_5022_50221001_7_dialog_content = "Kenapa kau senyum-senyum begitu?",
  ui_story_5022_50221001_8_dialog_content = "B-bukan apa-apa! Hanya saja, kalau kau sudah mengeluarkan seluruh kemampuanmu, Sinsa tak mungkin bisa menyaingimu…",
  ui_story_5022_50221001_9_dialog_content = "Tidak juga, sih. Sinsa pernah menghentikan Colossus milikku dengan satu tangan saja. Itu sungguh luar biasa.",
  ui_story_5022_50221001_10_dialog_content = "Entah bagaimana mengatakannya, tapi… seperti itulah kemampuan veteran Rediesel Wrench.",
  ui_story_5022_50221001_11_dialog_content = "Kuanggap itu pujian. Kedengarannya mungkin gila, tapi jelas membuat ketagihan, 'kan!?",
  ui_story_5022_50221001_12_dialog_content = "Kau sendiri juga gila.",
  ui_story_5022_50221001_13_dialog_content = "Tadi, kautahu aku akan memegangmu sementara kau berusaha menyeimbangkan mobilnya, 'kan?",
  ui_story_5022_50221001_14_dialog_content = "Dasar idiot. Aku tak biasa bekerja sama dalam tim. Kenapa kaukira kau bisa mengandalkanku?",
  ui_story_5022_50221001_15_dialog_content = "Tidak.",
  ui_story_5022_50221001_16_dialog_content = "Aku terbiasa memberikan perintah dalam pertempuran. Jadi, aku tahu banyak hal.",
  ui_story_5022_50221001_17_dialog_content = "Walau kau mengeluh kalau ada orang yang mencampuri urusanmu, kau selalu memperhatikan rekan timmu dan kau tahu pasti apa yang mereka lakukan.",
  ui_story_5022_50221001_18_dialog_content = "Tak ada satu hal pun yang luput dari perhatianmu.",
  ui_story_5022_50221001_19_dialog_content = "Kau membuatku merasa tersanjung, PlayerName. Aku suka.",
  ui_story_5022_50221001_20_dialog_content = "Hah, yang benar saja? Sepertinya sekarang aku jadi tertarik padamu.",
  ui_story_5022_50221001_21_dialog_content = "Hah?",
  ui_story_5022_50221001_22_dialog_content = "…",
  ui_story_5022_50221001_23_dialog_content = "Masih ada jalur yang harus ditempuh sebelum kita bisa sampai di jalan masuk ke ngarai. Saatnya bercerita.",
  ui_story_5022_50221001_24_dialog_content = "Kau penasaran tentang apa yang terjadi antara aku dan Eclipsite itu, 'kan? Keingintahuanmu tergambar jelas di wajahmu.",
  ui_story_5022_50221001_25_dialog_content = "…",
  ui_story_5022_50221001_26_dialog_content = "Dia berhasil mengalahkanku, membuatku remuk redam…",
  ui_story_5022_50221001_27_dialog_content = "Seandainya Roy tak ke sana saat Eclipsite itu mengalahkanku, tak mungkin aku masih ada di sini sekarang.",
  ui_story_5022_50221001_28_dialog_content = "…!",
  ui_story_5022_50221001_29_dialog_content = "Walau dia selalu menjadikannya bahan candaan dan memanfaatkannya sebagai cerita untuk anak-anak…",
  ui_story_5022_50221001_30_dialog_content = "Kami berdua sama-sama tahu, kejadian itu menimbulkan luka bagi kami untuk selamanya.",
  ui_story_5022_50221001_31_dialog_content = "Sulit dibayangkan, 'kan? Belasan tahun lalu, Rediesel Wrench nyaris gagal menyelamatkan diri dari serbuan Eclipsite.",
  ui_story_5022_50221001_32_dialog_content = "Kawanan monster berusaha mengepung baris pertahanan Illumina dari gurun… Salah satunya adalah Eclipsite itu.",
  ui_story_5022_50221001_33_dialog_content = "Aku kehilangan rumah dan saudara-saudaraku dalam rentetan pertempuran itu.",
  ui_story_5022_50221001_34_dialog_content = "Dan aku menyerah dalam balapannya.",
  ui_story_5022_50221001_35_dialog_content = "Berlatih untuk bertempur dan menyintas tampak lebih penting ketimbang permainan.",
  ui_story_5022_50221001_36_dialog_content = "Dari dulu, aku selalu sendirian karena aku tak percaya diri dengan kemampuanku sendiri untuk menjaga rekan-rekanku.",
  ui_story_5022_50221001_37_dialog_content = "Payah, ya? Akan tetapi, aku sungguh tak mau lagi merasa… tak berdaya seperti itu.",
  ui_story_5022_50221001_38_dialog_content = "Azure…",
  ui_story_5022_50221001_39_dialog_content = "Walaupun berkali-kali berhasil menuntaskan eksplorasi berbahaya, aku masih saja tak yakin apakah kemampuanku cukup bagus.",
  ui_story_5022_50221001_40_dialog_content = "Mampukah aku menyingkirkan musuh-musuh kami untuk melindungi hal-hal yang berarti bagiku?",
  ui_story_5022_50221001_41_dialog_content = "Seandainya aku harus berhadapan lagi dengan musuh bebuyutanku, akankah kali ini hasilnya berbeda?",
  ui_story_5022_50221001_42_dialog_content = "Sama seperti balapan ini, walaupun kubilang aku sudah menyerah…",
  ui_story_5022_50221001_43_dialog_content = "Tapi, aku tak bisa menahan diri dan akhirnya tetap saja menyelesaikan misiku, hanya agar aku bisa menyelinap kembali dan melihatnya berulang kali…",
  ui_story_5022_50221001_44_dialog_content = "Aku tak terlalu bisa diandalkan dan kemampuanku tak sehebat yang kaukira. Aku ini hanya…",
  ui_story_5022_50221001_45_dialog_content = "Seorang amatir.",
  ui_story_5022_50221001_46_dialog_content = "Kau sama sekali bukan amatir.",
  ui_story_5022_50221001_47_dialog_content = "Tak ada yang salah kalau kau menikmati hal yang kausukai.",
  ui_story_5022_50221001_48_dialog_content = "Mungkin aneh kalau kata-kata ini keluar dari mulutku, seorang asing, tapi…",
  ui_story_5022_50221001_49_dialog_content = "Bukankah prinsip Rediesel Wrench adalah menjalani hidup sepenuh-penuhnya?",
  ui_story_5022_50221001_50_dialog_content = "Aku yakin, orang-orang Rediesel Wrench akan menganggap segala jenis bahaya sebagai kesempatan untuk mencari keseruan.",
  ui_story_5022_50221001_51_dialog_content = "Karena kau sudah mengatakannya… Bisa kubayangkan wajah Joanie berbinar-binar penuh semangat.",
  ui_story_5022_50221001_52_dialog_content = "Lagi pula, sama seperti teman-teman yang selama ini kuandalkan, anggota Rediesel Wrench tak akan pernah membiarkanmu menghadapi musuh bebuyutanmu sendirian.",
  ui_story_5022_50221001_53_dialog_content = "Huh… Abaikan saja kenyataan bahwa saat ini hanya ada aku di sini.",
  ui_story_5022_50221001_54_dialog_content = "Seperti yang kaulihat, meski tak tahu cara menggunakan Luminatics, aku akan berusaha semampuku untuk membantu dengan caraku sendiri.",
  ui_story_5022_50221001_55_dialog_content = "Jadi, dalam pertempuran mendatang, kau juga bisa mengandalkanku!",
  ui_story_5022_50221001_56_dialog_content = "PlayerName…",
  ui_story_5022_50221001_57_dialog_content = "Aduh… Sekarang aku jadi malu karena mengoceh tak jelas seperti itu tadi…",
  ui_story_5022_50221001_58_dialog_content = "Sudah kuduga, ada alasan yang membuatku tertarik padamu. Kau orang yang baik.",
  ui_story_5022_50221001_59_dialog_content = "Kita sudah hampir sampai jalan masuk ke ngarai. Sekarang, Zeta mungkin sedang menangis seperti anak kecil.",
  ui_story_5022_50221001_60_dialog_content = "Omong-omong… Roy bahkan rela berdandan seperti putri demi Zeta…",
  ui_story_5022_50221001_61_dialog_content = "Namun, saat Zeta menghadapi bahaya besar, Roy tetap yakin dia bisa bertahan sampai kita tiba?",
  ui_story_5022_50221001_62_dialog_content = "Pola pendidikan di Rediesel Wrench memang liar, ya…",
  ui_story_5022_50221001_63_dialog_content = "Seperti yang dia bilang, Zeta salah satu yang terbaik di antara kita.",
  ui_story_5022_50221001_64_dialog_content = "Akan tetapi, jangan sampai dia menunggu terlalu lama. Sebaiknya kita habisi para Eclipsite dan meneruskan perjalanan.",
  ui_story_5022_50221001_65_dialog_content = "Ayo tunjukkan kemampuan kita, PlayerName!",
  ui_story_5022_50221101_1_dialog_content = "Lihat kawanan Eclipsite itu?",
  ui_story_5022_50221101_2_dialog_content = "Aww… Kalau bertumpuk-tumpukan jadi satu seperti itu, gerakan mereka tampak seperti cacing. Menjijikkan…",
  ui_story_5022_50221101_3_dialog_content = "Kita libas mereka tanpa ampun! Ini kesempatanku untuk mengalibrasi bom-bom baruku. Namun, naga buas itu jatahku!",
  ui_story_5022_50221101_4_dialog_content = "Tenang saja. High-Level Eclipsite itu tak ada di antara kerumunan itu.",
  ui_story_5022_50221101_5_dialog_content = "Sepertinya dia membuntuti Zeta ke ngarai… Gerakannya sangat cepat…",
  ui_story_5022_50221101_6_dialog_content = "Kawanan Eclipsite yang lainnya sepertinya bergerak ke arah tengah.",
  ui_story_5022_50221101_7_dialog_content = "Apa mereka berusaha memperlambat gerakan Azure? Dia terlalu jauh…",
  ui_story_5022_50221101_8_dialog_content = "<color=#e8d9bb>Kresek… Kresek…</color>",
  ui_story_5022_50221101_9_dialog_content = "Kau bisa mendengarku, Tiny One?",
  ui_story_5022_50221101_10_dialog_content = "Roy! Aku bisa mendengarmu! Honcho Sinsa dan Joanie Boom juga di sini bersamaku. Apa yang kaubutuhkan?",
  ui_story_5022_50221101_11_dialog_content = "Sinsa? Bukankah dia bersama Azure…?",
  ui_story_5022_50221101_12_dialog_content = "Tidak. Begini lebih baik… Kali ini, kau bisa menimbulkan kerusuhan besar.",
  ui_story_5022_50221101_13_dialog_content = "Pancing perhatian mereka dari belakang, lalu buat barisan mereka bubar. Kita harus membuka kesempatan bagi Azure untuk menerobos.",
  ui_story_5022_50221101_14_dialog_content = "Apa pendapatmu soal rencana ini, pemimpin?",
  ui_story_5022_50221101_15_dialog_content = "Baiklah, kali ini, kita biarkan saja Azure jadi pahlawan… karena memang dialah bintang pesta untuk hari ini. Hari ini saja, lo!",
  ui_story_5022_50221101_16_dialog_content = "Aku tahu kau sudah pernah mendengar ini dan mungkin tak ada yang perlu dikhawatirkan karena pemimpin kita ada di sini… Akan tetapi, aku ingin mengingatkan kalian…",
  ui_story_5022_50221101_17_dialog_content = "Basmi cacing-cacing semangka itu agar mereka tak jadi gangguan lagi. Jaga keselamatan Carrier kita!",
  ui_story_5022_50221101_18_dialog_content = "Jangan lupakan sapu-sapu kusut menyebalkan yang bisa menyembuhkan Eclipsite lain itu! Musnahkan mereka semua!",
  ui_story_5022_50221101_19_dialog_content = "Eyeball Monster yang bentuknya seperti telur rebus busuk itu bisa memanggil anak buah mereka yang merepotkan. Bunuh mereka sesegera mungkin. Begitu, 'kan?",
  ui_story_5022_50221101_20_dialog_content = "Anu… Dan…",
  ui_story_5022_50221101_21_dialog_content = "Jaga jarak dari Mega Fist. Waspadai juga Flying Octopus yang mungkin bisa mengacaukan gerakan kita.",
  ui_story_5022_50221101_22_dialog_content = "… Anu… Roy, apa barusan kau berdesah? Maaf kalau aku salah.",
  ui_story_5022_50221101_23_dialog_content = "Tidak, tidak, Anda melakukan pekerjaan luar biasa. Hanya saja... Sungguh luar biasa betapa cepatnya anak-anak tumbuh...",
  ui_story_5022_50221101_24_dialog_content = [[
Kafka dan Sork akan segera bergabung dengan kalian. Pimpin pertempurannya, pemimpin. |
Selamat bersenang-senang.]],
  ui_story_5022_50221101_25_dialog_content = "Aaaaaahhh! Berengsek kau, Barbara, kau mengacaukan konser soloku lagi!",
  ui_story_5022_50221101_26_dialog_content = "Graaah!",
  ui_story_5022_50221101_27_dialog_content = "Diam! Di sinilah kau akan tumbang! Solo Requiem!",
  ui_story_5022_50221101_28_dialog_content = "Oh? Konser Regina? Kukira para penonton ini kemari untuk menonton konserku!",
  ui_story_5022_50221101_29_dialog_content = "Siap? Sweet Kiss!",
  ui_story_5022_50221101_30_dialog_content = "Hah? Memangnya ada orang di dunia ini yang bakal suka dengan lagu-lagu bodohmu itu?",
  ui_story_5022_50221101_31_dialog_content = "Pekikan dan teriakanmu justru lebih menyakitkan telinga. Iya, 'kan?",
  ui_story_5022_50221101_32_dialog_content = "Kau mau memancing perkelahian, nih?",
  ui_story_5022_50221101_33_dialog_content = "Kalau kau mau berkelahi, aku sih tak akan menolak.",
  ui_story_5022_50221101_34_dialog_content = "*Batuk-batuk* Maaf menyela.",
  ui_story_5022_50221101_35_dialog_content = "Kalian berdua memisahkan diri dari Lepidoz dan mengitari gunung berapi ini untuk memintas jalan dari gurun utara. Kurasa kalian sekarang sudah cukup dekat dengan kawanan Eclipsite itu, 'kan?",
  ui_story_5022_50221101_36_dialog_content = "Kau terlalu lelet, Roy. Kami sudah beraksi dari tadi. Kita harus memanggang mereka semua, 'kan?",
  ui_story_5022_50221101_37_dialog_content = "Hmm… Karakter tak berguna ini mulai membuatku bosan.",
  ui_story_5022_50221101_38_dialog_content = "Ini jarang sekali terjadi, tapi aku setuju dengan kata-katamu barusan.",
  ui_story_5022_50221101_39_dialog_content = "Namun, aku jelas akan menuntaskan misi sulit ini. Idola super memang harus punya etika kerja tinggi.",
  ui_story_5022_50221101_40_dialog_content = "Argh… Aku minta maaf atas pengalaman burukmu, tapi kita punya tugas yang sangat penting, yaitu membendung musuh dan mencegah agar kawanan Eclipsite tak berhamburan membanjiri ngarai.",
  ui_story_5022_50221101_41_dialog_content = "Eh, bagaimana kalau kita bertaruh saja? Yang bisa membunuh lebih banyak Eclipsite kali ini, nanti boleh mengadakan konser tunggal di Fiery Support berikutnya.",
  ui_story_5022_50221101_42_dialog_content = "!!!",
  ui_story_5022_50221101_43_dialog_content = "Selain itu, penyanyi berhak menentukan lokasi konsernya, entah itu di Lepidoz atau Oasis.",
  ui_story_5022_50221101_44_dialog_content = "Horee! Kau yakin mau sampai sejauh itu?",
  ui_story_5022_50221101_45_dialog_content = "Jika saya memilih Oasis, saya dapat menggunakan efek cahaya yang fantastis dan menakjubkan! Saya semakin bersemangat hanya dengan memikirkannya ...",
  ui_story_5022_50221101_46_dialog_content = "Tunggu, tapi konser di Lepidoz yang bergerak juga merupakan kesempatan langka...",
  ui_story_5022_50221101_47_dialog_content = "Hoi! Regina! Jaga sikapmu! Jangan bertindak sebelum waktunya!",
  ui_story_5022_50221101_48_dialog_content = "Fyuh… Berikutnya…",
  ui_story_5022_50221101_49_dialog_content = "Azure, kawanan Eclipsite itu pelan-pelan bubar. Sebentar lagi, kita bisa menerobos kepungan mereka!",
  ui_story_5022_50221101_50_dialog_content = "Rediesel Wrench akhirnya datang membantu?",
  ui_story_5022_50221101_51_dialog_content = "Eclipsite tak akan begitu saja mengalihkan perhatian dari kita. Kalau kawanan Eclipsite itu bisa dibubarkan secepat ini, pasti Roy-lah yang memimpin.",
  ui_story_5022_50221101_52_dialog_content = "Ah! Permintaan koneksi?",
  ui_story_5022_50221101_53_dialog_content = "Halo…",
  ui_story_5022_50221101_54_dialog_content = "Dah.",
  ui_story_5022_50221101_55_dialog_content = "Hah?!",
  ui_story_5022_50221101_56_dialog_content = "Sebentar! Dingin sekali sikapmu! Ibumu pasti menangis karenanya.",
  ui_story_5022_50221101_57_dialog_content = "Ayolah. Kau sudah terlalu tua untuk bercanda seperti itu.",
  ui_story_5022_50221101_58_dialog_content = "Uhuk… Maaf, tapi…",
  ui_story_5022_50221101_59_dialog_content = "… Roy.",
  ui_story_5022_50221101_60_dialog_content = "Yang akan kaukatakan itu sudah kulihat dan kualami sendiri.",
  ui_story_5022_50221101_61_dialog_content = "Rediesel Wrench sudah banyak berubah dalam sekitar sepuluh tahun belakangan. Kini, kita tak lagi kalah dan takut akan Eclipsite…",
  ui_story_5022_50221101_62_dialog_content = "Dan, aku juga sudah berubah.",
  ui_story_5022_50221101_63_dialog_content = "Kanan?",
  ui_story_5022_50221101_64_dialog_content = "Azure…",
  ui_story_5022_50221101_65_dialog_content = "Menuntaskannya dengan tanganku sendiri adalah satu-satunya cara bagiku agar terbebas dari bayangan yang terus menghantuiku itu.",
  ui_story_5022_50221101_66_dialog_content = "Simpan saja semua kata-katamu sampai aku kembali nanti dan membawa kemenangan.",
  ui_story_5022_50221101_67_dialog_content = "... Jadi begitu. Nah, kami telah membuka jalan untuk Anda.",
  ui_story_5022_50221101_68_dialog_content = "Selamat berburu.",
  ui_story_5022_50221201_1_dialog_content = "<color=#e8d9bb>Lebih dari sepuluh tahun lalu</color>",
  ui_story_5022_50221201_2_dialog_content = "Gaar…",
  ui_story_5022_50221201_3_dialog_content = "Hosh… Hosh… Ini tak ada habisnya…",
  ui_story_5022_50221201_4_dialog_content = "Coo…",
  ui_story_5022_50221201_5_dialog_content = "Si keparat ini rupanya menunggu sampai kekuatanku terkuras habis…",
  ui_story_5022_50221201_6_dialog_content = "(Tak akan berhasil kalau aku berusaha menangkalnya sendirian di dalam mobil… Namun, apa lagi yang bisa kuperbuat untuk menyelamatkan semua orang?)",
  ui_story_5022_50221201_7_dialog_content = "… Apa? Coba ulangi kata-katamu itu!",
  ui_story_5022_50221201_8_dialog_content = "Kata-kataku sudah cukup jelas.",
  ui_story_5022_50221201_9_dialog_content = "Apa maksudmu Chief tak akan kemari, Roy? Tatap aku!",
  ui_story_5022_50221201_10_dialog_content = "Krisis ini sama sekali belum berakhir. Mereka bisa saja mengorbankan nyawa untuk mengulur waktu bagi kita, tapi kawanan Eclipsite yang menghancurkan pangkalan kita itu akan segera menyusul.",
  ui_story_5022_50221201_11_dialog_content = "Di antara kawanan itu, ada satu Eclipsite berwujud seperti naga yang gerakannya luar biasa cepat. Aku akan berusaha mengalihkan perhatiannya. Sinsa, kaupimpin…",
  ui_story_5022_50221201_12_dialog_content = "Kenapa kau kemari sendirian? Kenapa…",
  ui_story_5022_50221201_13_dialog_content = "Seandainya bisa, kuharap nyawaku juga melayang di sana, Azure.",
  ui_story_5022_50221201_14_dialog_content = "Begitu kita berhasil melewati ini, hajar saja aku sesukamu. Akan tetapi, sekarang ini, Azure… Hoi! Kau mau ke mana?",
  ui_story_5022_50221201_15_dialog_content = "(… Kalau itu tadi adalah kata-kata terakhirku untuknya, rasanya omonganku agak kejam, ya?)",
  ui_story_5022_50221201_16_dialog_content = "(Dari belakang bungker ini, mestinya aku bisa melancarkan serangan…)",
  ui_story_5022_50221201_17_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_5022_50221201_18_dialog_content = "Ahh…!",
  ui_story_5022_50221201_19_dialog_content = "(Arghh… Apa kulitnya terbuat dari baja?)",
  ui_story_5022_50221201_20_dialog_content = "(Senapanku… Aku harus mengambil kembali senapanku…)",
  ui_story_5022_50221201_21_dialog_content = "Aduh… Sakit sekali…",
  ui_story_5022_50221201_22_dialog_content = "(Aku tak bisa… bergerak…)",
  ui_story_5022_50221201_23_dialog_content = "(Apa tulangku patah saat tabrakan tadi? Atau mungkinkah raungan kerasnya itu membuat sarafku mati rasa?)",
  ui_story_5022_50221201_24_dialog_content = "(Fokus saja pada apa yang ada di depan mata. Jangan menyerah. Aku tak boleh menyerah… Aku tak akan menyerah…)",
  ui_story_5022_50221201_25_dialog_content = "<anim type=Shake><size=45>Groar!</size></anim>",
  ui_story_5022_50221201_26_dialog_content = "(Tidak… Kesadaranku… Mulai kabur…)",
  ui_story_5022_50221201_27_dialog_content = "(Apa mereka berhasil meloloskan diri?)",
  ui_story_5022_50221201_28_dialog_content = "(Apa aku akan mati di sini?)",
  ui_story_5022_50221201_29_dialog_content = "<color=#e8d9bb>Gruduk!</color>",
  ui_story_5022_50221201_30_dialog_content = "<size=45>Gaar ahhhhhh!</size>",
  ui_story_5022_50221201_31_dialog_content = "(… Ledakan?)",
  ui_story_5022_50221201_32_dialog_content = "Uhuk… Ah-hahah… Tepat waktu.",
  ui_story_5022_50221201_33_dialog_content = "Roy! Kau…",
  ui_story_5022_50221201_34_dialog_content = "Kenapa tampangmu seperti itu? Kau tak bisa pasang tampang senang sedikit saja, ya?",
  ui_story_5022_50221201_35_dialog_content = "Situasi saat ini terkendali, tetapi daya tembak kita tidak dapat menahan musuh untuk waktu yang lama...",
  ui_story_5022_50221201_36_dialog_content = "Ah… Kau… *Batuk-batuk* Khawatir tentang ini…",
  ui_story_5022_50221201_37_dialog_content = "Aduh... Kurasa dia tidak punya cukup kekuatan lagi untuk menyerangmu...",
  ui_story_5022_50221201_38_dialog_content = "Ya, memang sedikit sakit... Tapi tidak ada yang tidak bisa diperbaiki dengan tidur malam yang nyenyak...",
  ui_story_5022_50221201_39_dialog_content = "Lagi pula, aku kan memang cukup kuat dan tangguh.",
  ui_story_5022_50221201_40_dialog_content = "Tutup mulutmu. Omonganmu tak ada gunanya untuk lukamu…",
  ui_story_5022_50221201_41_dialog_content = "Yang lainnya telah... Mencapai keselamatan. Ada semacam kadal raksasa...",
  ui_story_5022_50221201_42_dialog_content = "Tapi saya mengirim Sinsa untuk memeriksanya... Jadi, jangan khawatir...",
  ui_story_5022_50221201_43_dialog_content = "Beri aku beberapa detik lagi... Biarkan aku memulihkan kekuatan...",
  ui_story_5022_50221201_44_dialog_content = "Aku bisa membekukan cakar tajamnya dan meremukkan mereka!",
  ui_story_5022_50221201_45_dialog_content = "... Anda selalu punya rencana.",
  ui_story_5022_50221201_46_dialog_content = "Tidak sepertiku, maju terus tanpa otak dan berakhir seperti ini... Pemimpin pasti akan memarahiku karena ini...",
  ui_story_5022_50221201_47_dialog_content = "…",
  ui_story_5022_50221201_48_dialog_content = "Oh... Tidak... Dia tidak akan... Aku hampir lupa... Dia sudah pergi...",
  ui_story_5022_50221201_49_dialog_content = "Karena saat ini kita maupun Eclipsite itu sama-sama tak bisa bergerak, aku… Uhuk… Aku harus menyampaikan keluhan.",
  ui_story_5022_50221201_50_dialog_content = "Kaukira ini saat yang tepat untuk menceramahiku?",
  ui_story_5022_50221201_51_dialog_content = "Aku tak akan berceramah, kok. Akan tetapi, berapa kali kubilang padamu, jangan bertindak sendirian dan berusaha membuktikan betapa beraninya kau!",
  ui_story_5022_50221201_52_dialog_content = "Aku mengajarimu terlalu banyak. Aku sama sekali tak bisa menyusulmu menggunakan mobil… Aku harus lebih banyak berlatih…",
  ui_story_5022_50221201_53_dialog_content = "Pemimpin… dia membuatku berjanji untuk menjagamu dan Rediesel Wrench tetap aman. Dia sungguh suka menyuruh-nyuruh orang…",
  ui_story_5022_50221201_54_dialog_content = "Aku harus memenuhi janjiku, paling tidak hingga ratusan tahun…",
  ui_story_5022_50221201_55_dialog_content = "Kepalaku jadi sakit kalau membayangkan bahwa aku harus mendidik orang-orang dungu dan bandit liar itu menjadi penguasa gurun ini.",
  ui_story_5022_50221201_56_dialog_content = "Kata-kata terakhirnya cukup tegas, 'kan?",
  ui_story_5022_50221201_57_dialog_content = "Makanya… Kau tak boleh meninggalkanku.",
  ui_story_5022_50221201_58_dialog_content = "Masih banyak sekali hal yang harus kita capai… Kita tak boleh mati sekarang. Lagi pula, pastinya, bukan di sini.",
  ui_story_5022_50221201_59_dialog_content = "Anda tidak perlu mengatakan itu kepada saya! Sekarang tutup mulut, saya harus fokus untuk mengontrol jangkauan Luminatics saya.",
  ui_story_5022_50221201_60_dialog_content = "Hahah. Uhuk… Sepertinya kau sudah cukup istirahat.",
  ui_story_5022_50221201_61_dialog_content = "Ayo… pulang.",
  ui_story_5022_50221201_62_dialog_content = "Kita akan membangun benteng baru... Di suatu tempat dengan air dan banyak pohon...",
  ui_story_5022_50221202_1_dialog_content = "Anu… Azure…",
  ui_story_5022_50221202_2_dialog_content = "Tidak ada yang tidak bisa diperbaiki dengan tidur nyenyak... Hah, dia keluar selama lebih dari seminggu berturut-turut...",
  ui_story_5022_50221202_3_dialog_content = "Memangnya siapa juga yang sok berani?",
  ui_story_5022_50221202_4_dialog_content = "… Azure? Azure?",
  ui_story_5022_50221202_5_dialog_content = "Apa katamu?",
  ui_story_5022_50221202_6_dialog_content = "Pikiranmu sepertinya sedang tak fokus. Dari tadi, kau juga bergumam kepada dirimu sendiri sambil ngebut… Apa kau baik-baik saja?",
  ui_story_5022_50221202_7_dialog_content = "Aku hanya… baru saja ingat sesuatu yang sudah berlalu.",
  ui_story_5022_50221202_8_dialog_content = "Jangan khawatir. Aku bisa mengemudi di jalur balapan ini dengan mata tertutup.",
  ui_story_5022_50221202_8X_dialog_content = "Kalau bisa, aku lebih suka matamu tetap terbuka, sih…",
  ui_story_5022_50221202_9_dialog_content = "Aku bisa merasakan bahwa High-Level Eclipsite itu sangat dekat dengan kita.",
  ui_story_5022_50221202_10_dialog_content = "Darkflow-nya terasa familier. Dengan cara yang sangat meresahkan...",
  ui_story_5022_50221202_11_dialog_content = "Kami telah memasuki ngarai. Pasir tidak akan terlalu mempengaruhi peralatan komunikasi kita di sini... Kita mungkin bisa mencapai Zeta...",
  ui_story_5022_50221202_12_dialog_content = "<color=#e8d9bb>Kresek… Kresek…</color>",
  ui_story_5022_50221202_13_dialog_content = "Huhu… Ahhhhhh!",
  ui_story_5022_50221202_14_dialog_content = "Ada orang di sana? Tolong…",
  ui_story_5022_50221202_15_dialog_content = "Zeta! Syukurlah. Kau baik-baik saja?",
  ui_story_5022_50221202_16_dialog_content = "Komunikasinya sudah aktif lagi? Caelestite! Apa itu Caelestite?",
  ui_story_5022_50221202_17_dialog_content = "Aku… aku…",
  ui_story_5022_50221202_18_dialog_content = "Solly Ahhh!",
  ui_story_5022_50221202_19_dialog_content = "Jeritanmu keras sekali!",
  ui_story_5022_50221202_20_dialog_content = "Maaf! Aku hanya ingin… Huhu… berteman dengan semua orang.",
  ui_story_5022_50221202_21_dialog_content = "Aku hanya ingin bermain dengan yang lain… Aku *terisak*… Aku hanya membuat masalah *mengendus* agar orang-orang memperhatikanku…",
  ui_story_5022_50221202_22_dialog_content = "Waaah! Maaf, Maggie... Kita berada di tim yang sama tapi aku sering mengerjaimu...",
  ui_story_5022_50221202_23_dialog_content = "Dan dan Tiny One, Kafka, Rabbie, Odi, Jomu, Clover, Chainsaw Rick, dan Sork...",
  ui_story_5022_50221202_24_option_content = "Kau harus minta maaf kepada banyak sekali orang…",
  ui_story_5022_50221202_25_dialog_content = "Saya belum selesai! Masih banyak lagi di Rediesel Wrench...",
  ui_story_5022_50221202_26_dialog_content = "Misalnya Scorching Jinx, Tempest Emperor, Dusk Phoenix, Depraved Warwraith… Huhu…",
  ui_story_5022_50221202_27_dialog_content = "(Siapa pula mereka itu?)",
  ui_story_5022_50221202_28_option_content = "Zeta, tenanglah sebentar…",
  ui_story_5022_50221202_29_dialog_content = "Tidak!",
  ui_story_5022_50221202_30_dialog_content = "(Biarkan dia selesaikan omongannya…)",
  ui_story_5022_50221202_31_dialog_content = "*Menangis*... Azure...",
  ui_story_5022_50221202_32_dialog_content = "Oh? Lanjutkan saja. Aku mendengarkan, kok.",
  ui_story_5022_50221202_33_dialog_content = "Aku sering sengaja mencari masalah denganmu karena aku iri.",
  ui_story_5022_50221202_34_dialog_content = "Kau sangat mahir dalam segala hal. Selain itu, Roy lebih memercayaimu daripada siapa pun juga…",
  ui_story_5022_50221202_35_dialog_content = "Itu sebabnya aku selalu berusaha mencari kekurangan denganmu...",
  ui_story_5022_50221202_36_dialog_content = "Di bawah tempat tidurku, ada sebuah wadah kaleng. Di dalamnya ada semua permen yang sudah kukumpulkan dan kusimpan selama bertahun-tahun.",
  ui_story_5022_50221202_37_dialog_content = "Azure... *Sniff*... Ambil dan bagikan dengan semua orang...",
  ui_story_5022_50221202_38_dialog_content = "Hmm. Ada lagi?",
  ui_story_5022_50221202_39_dialog_content = "*Mengendus* Kotak itu sudah dipasangi jebakan, jadi berhati-hatilah saat melepaskannya…",
  ui_story_5022_50221202_40_dialog_content = "Berikan lebih banyak permen untuk Maggie di Canary, juga untuk Roy yang selalu bekerja hingga larut malam. Lalu…",
  ui_story_5022_50221202_41_dialog_content = "Tolong sampaikan kepada semuanya bahwa aku menyayangi mereka… Huhu…",
  ui_story_5022_50221202_42_dialog_content = "Enam belas tahun di Rediesel Wrench adalah masa-masa yang indah…",
  ui_story_5022_50221202_43_dialog_content = "Tolong, jangan lupakan aku… Huaaaaa!",
  ui_story_5022_50221202_44_dialog_content = "Sudah selesai?",
  ui_story_5022_50221202_45_dialog_content = "Hmm…",
  ui_story_5022_50221202_46_dialog_content = "Itu tak akan ada gunanya.",
  ui_story_5022_50221202_47_dialog_content = "Hah?",
  ui_story_5022_50221202_48_dialog_content = "Permintaanmu terlalu banyak. Aku tak punya waktu untuk melakukannya. Sebaiknya kaulakukan saja sendiri.",
  ui_story_5022_50221202_49_dialog_content = "Namun…",
  ui_story_5022_50221202_50_dialog_content = "Jangan khawatir. Akulah yang akan jadi pahlawan…",
  ui_story_5022_50221202_51_dialog_content = "Eh, tidak, aku akan jadi si jahat yang meninggalkan jalan hidup kelam dan kembali ke jalan kebenaran berkat keyakinan naif sang pahlawan…",
  ui_story_5022_50221202_52_dialog_content = "Saat sang pahlawan terjerumus ke dalam bahaya, aku akan melompat dan mengalahkan naga itu.",
  ui_story_5022_50221202_53_dialog_content = "... Aku akan membawamu pulang, Zeta.",
  ui_story_5022_50221301_1_dialog_content = "Azure, aku melihatnya! Di sana!",
  ui_story_5022_50221301_2_dialog_content = "(High-Level Eclipsite ini tampak mirip sekali dengan Nozard hasil modifikasi…)",
  ui_story_5022_50221301_3_dialog_content = "PlayerName, pegangan. Aku mau ngebut.",
  ui_story_5022_50221301_4_dialog_content = "<color=#e8d9bb>Brak! Dor… Dor!</color>",
  ui_story_5022_50221301_5_dialog_content = "(Barusan, mobil kami melindas satu Eclipsite kecil…)",
  ui_story_5022_50221301_6_dialog_content = "Memangnya nanti bumper dan kaca depanmu tak penyok?",
  ui_story_5022_50221301_7_dialog_content = "Jangan meremehkan Bullock 8. Mobil ini tak seperti mainan yang sering kaulihat di Illumina.",
  ui_story_5022_50221301_8_dialog_content = "Mobilku tangguh, sekeras batu. Sebaiknya kauperiksa keadaan Zeta dengan teropong itu.",
  ui_story_5022_50221301_9_dialog_content = "Biar kulihat…",
  ui_story_5022_50221301_10_dialog_content = "Zeta… Zeta dan mobilnya dicengkeram cakar naga itu!",
  ui_story_5022_50221301_11_dialog_content = "Kedengarannya tidak bagus. Ayo selamatkan dia!",
  ui_story_5022_50221301_12_dialog_content = "Ayo.",
  ui_story_5022_50221301_13_dialog_content = "Baiklah… Sebentar, Azure. Kenapa kita malah bergerak mundur?",
  ui_story_5022_50221301_14_dialog_content = "PlayerName, betapapun saya ingin menghadapi Eclipsite ini secara langsung...",
  ui_story_5022_50221301_15_dialog_content = "Aku punya rencana yang lebih bagus.",
  ui_story_5022_50221301_16_dialog_content = "(Samarkan jejak kita, lalu kita memanjat lewat jalan kecil ke titik komando di hutan…)",
  ui_story_5022_50221301_17_dialog_content = "Aku paham. Ini pasti cara kerja sniper. Azure memang cerdas.",
  ui_story_5022_50221301_18_dialog_content = "Terima kasih atas pujianmu. Kalau bukan berkat kemampuan psikismu, mungkin kita akan butuh waktu lebih lama lagi.",
  ui_story_5022_50221301_19_dialog_content = "... Seperti inikah rasanya bekerja sebagai tim? Tidak terlalu buruk.",
  ui_story_5022_50221301_20_dialog_content = "Hah? Apa katamu? Aku senang sekali bisa membantu Azure!",
  ui_story_5022_50221301_21_dialog_content = "Sudah lama aku menantikan ini. PlayerName, kemari dan berlututlah.",
  ui_story_5022_50221301_22_dialog_content = "Sebentar… Senapan ini? Kenapa kau menodongkannya kepadaku?",
  ui_story_5022_50221301_23_dialog_content = "Tetap berlutut!",
  ui_story_5022_50221301_24_dialog_content = "... Besar. Tingginya sempurna.",
  ui_story_5022_50221301_25_dialog_content = "Diamlah. Jangan gemetaran.",
  ui_story_5022_50221301_26_dialog_content = "Aku akan berusaha sebaik mungkin…",
  ui_story_5022_50221301_27_dialog_content = "Hah… Luar biasa.",
  ui_story_5022_50221301_28_dialog_content = "Sudah ribuan kali aku memimpikan momen ini, tapi tak sekalipun aku merasa…",
  ui_story_5022_50221301_29_dialog_content = "Setenang ini.",
  ui_story_5022_50221301_30_dialog_content = "Azure, apa kau bisa melihat Zeta?",
  ui_story_5022_50221301_31_dialog_content = "Tentu saja. Dia menggantung di pintu, melempar bom...",
  ui_story_5022_50221301_32_dialog_content = "Dan berusaha masuk kembali ke mobilnya.",
  ui_story_5022_50221301_33_dialog_content = "Sepertinya kau senang menyaksikannya…",
  ui_story_5022_50221301_34_dialog_content = "Jangan bodoh. Para sniper seperti kami biasa mengawali misi dengan mengamati keadaan sekitar dan memprediksi gerakan target.",
  ui_story_5022_50221301_35_dialog_content = "Namun, kau memang benar. Aku tak keberatan menyaksikannya lebih lama lagi.",
  ui_story_5022_50221301_36_dialog_content = "Arah angin, sudah. Kecepatan angin, sudah.",
  ui_story_5022_50221301_37_dialog_content = "Sekarang kita menunggu Eclipsite berputar dan memberiku pandangannya...",
  ui_story_5022_50221301_38_dialog_content = "Merindukan Azure, Saya pernah melihat Eclipsite Tingkat Tinggi yang serupa sebelumnya...",
  ui_story_5022_50221301_39_dialog_content = "Untuk membunuhnya, kami terpaksa meledakkan satu Undercity di Illumina.",
  ui_story_5022_50221301_40_dialog_content = "Kau tak percaya kepadaku?",
  ui_story_5022_50221301_41_dialog_content = "… Memang, dulu aku gagal.",
  ui_story_5022_50221301_42_dialog_content = "Cakarnya tajam dan kulitnya tak bisa ditembus.",
  ui_story_5022_50221301_43_dialog_content = "Gara-gara itu, aku dan kawan-kawanku terpaksa menumpahkan darah dan menderita.",
  ui_story_5022_50221301_44_dialog_content = "Namun, masa lalu hanyalah masa lalu… Rediesel Wrench tak kenal takut…",
  ui_story_5022_50221301_45_dialog_content = "Kami tak pernah menolak bertarung dan selalu berusaha meraih kemenangan…",
  ui_story_5022_50221301_46_dialog_content = "Kalau tak bisa menang kali ini, kami akan memastikan kekalahan itu segera tertebus.",
  ui_story_5022_50221301_47_dialog_content = "… Dan, sekaranglah saatnya!",
  ui_story_5022_50221301_48_dialog_content = "Groar!",
  ui_story_5022_50221301_49_dialog_content = "!!!",
  ui_story_5022_50221301_50_dialog_content = "Apa itu bekerja? Aku melihat peluru menembus matanya...",
  ui_story_5022_50221301_51_dialog_content = "Jangan bergerak.",
  ui_story_5022_50221301_52_dialog_content = "B-baiklah…",
  ui_story_5022_50221301_53_dialog_content = "… Tidak, tak berhasil.",
  ui_story_5022_50221301_54_dialog_content = "Perilaku target memang berubah, tapi dia masih bisa bergerak.",
  ui_story_5022_50221301_55_dialog_content = "Namun, meskipun saya tidak tahu banyak tentang Eclipsites Roy...",
  ui_story_5022_50221301_56_dialog_content = "Namun, makhluk hidup apa pun mestinya akan menderita parah kalau kehilangan kedua matanya dalam sehari.",
  ui_story_5022_50221301_57_dialog_content = "Heh. Masih bisa bergerak padahal otaknya sudah rusak… Menarik.",
  ui_story_5022_50221301_58_dialog_content = "<color=#e8d9bb>Dor! Duar, duar!</color>",
  ui_story_5022_50221301_59_dialog_content = "Wow! Kilatan cahaya menyilaukan itu… Dan rentetan ledakannya… Apa itu Zeta?",
  ui_story_5022_50221301_60_dialog_content = "Ya. Dia berhasil lolos.",
  ui_story_5022_50221301_61_dialog_content = "Apa yang harus kita lakukan? Isi lagi amunisi senapannya?",
  ui_story_5022_50221301_62_dialog_content = "Saya bisa merasakan Eclipsites lainnya. Mereka tertarik ke sini oleh tembakan dan ledakan...",
  ui_story_5022_50221301_63_dialog_content = "Ayo, PlayerName.",
  ui_story_5022_50221301_64_dialog_content = "Kita singkirkan dulu makhluk kecil berisik itu dari sana.",
  ui_story_5022_50221402_1_dialog_content = "Guaaahh!",
  ui_story_5022_50221402_2_dialog_content = "Kenapa kawanan Eclipsite itu masih banyak sekali…? Apa mereka berasal dari bawah tanah?",
  ui_story_5022_50221402_3_dialog_content = "Sarang mereka mungkin ada di ngarai ini.",
  ui_story_5022_50221402_4_dialog_content = "Ini info intel penting. Akan tetapi, untuk sekarang ini, kita harus fokus pada musuh.",
  ui_story_5022_50221402_5_dialog_content = "Karena kehilangan matanya, gerakannya jadi kacau tak menentu. Berkat itu, kita bisa cepat-cepat menemui Zeta.",
  ui_story_5022_50221402_6_dialog_content = "*Menangis*... Azure...",
  ui_story_5022_50221402_7_dialog_content = "Zeta, tak apa kalau kau mau memeluk penyelamatmu setelah kau terlepas dari cengkeraman maut.",
  ui_story_5022_50221402_8_dialog_content = "Namun, kau sama sekali tak boleh mengotori seluruh tubuhnya dengan ingusmu.",
  ui_story_5022_50221402_9_dialog_content = "Kalau begitu, Caelestite… Huhu…",
  ui_story_5022_50221402_10_option_content = "Tubuhku boleh dibiarkan berlumuran ingus?",
  ui_story_5022_50221402_11_dialog_content = "Semenit lagi!",
  ui_story_5022_50221402_12_dialog_content = "Akulah pahlawan yang akan menyelamatkan Astra. Aku tak boleh menyerah!",
  ui_story_5022_50221402_13_option_content = "Jangan takut. Kami bersamamu.",
  ui_story_5022_50221402_14_dialog_content = "*Hiks*",
  ui_story_5022_50221402_15_dialog_content = "Terima kasih, Caelestite…",
  ui_story_5022_50221402_16_dialog_content = "Aku sudah tak apa-apa.",
  ui_story_5022_50221402_17_dialog_content = "Wicked Dragon Hakudoma dari dunia bayangan muncul justru saat aku sedang bertarung dengan Azure… Ini adalah bagian dari ujian yang sudah disiapkan para dewa untuk orang yang terpilih…",
  ui_story_5022_50221402_18_dialog_content = "(Masih menangis, tapi keadaannya pulih dengan cepat…)",
  ui_story_5022_50221402_19_dialog_content = "Kita harus membuat gerakannya makin terbatas. PlayerName, rencanakan rutenya.",
  ui_story_5022_50221402_20_dialog_content = "Baiklah. Biar kutangani.",
  ui_story_5022_50221402_21_dialog_content = "<color=#e8d9bb>Dor… Dor… Dor…</color>",
  ui_story_5022_50221402_22_dialog_content = "<color=#e8d9bb>Duar… Duar… Duar…</color>",
  ui_story_5022_50221402_23_dialog_content = "Groar!",
  ui_story_5022_50221402_24_dialog_content = "(Dalam operasi sebelumnya, memang akulah yang merencanakan rute, tapi…)",
  ui_story_5022_50221402_25_dialog_content = "(Zeta mampu menguasainya dengan cepat dan terus melemparkan Candy Bomb ke titik-titik yang sulit dihindari si naga…)",
  ui_story_5022_50221402_26_dialog_content = "(Lalu, Azure menembak semua bom itu, satu per satu… Kerja sama tim mereka benar-benar sempurna.)",
  ui_story_5022_50221402_27_dialog_content = "(Eclipsite ini agak berbeda dari semua Eclipsite lain yang pernah kutemui.)",
  ui_story_5022_50221402_28_dialog_content = "Hmm… Kalau dia mirip dengan Nozard, berarti dia bisa memanipulasi Eclipsite lain untuk menyerang.",
  ui_story_5022_50221402_29_dialog_content = "Namun, wujud dan gerakannya mirip dengan Eclipsite yang pernah kuhadapi bersama Vice di Whispering Corridor.",
  ui_story_5022_50221402_30_dialog_content = "Lebih tangguh dan kulitnya lebih tebal. Dia… dia nyaris tak bisa dihancurkan.",
  ui_story_5022_50221402_31_dialog_content = "Jika kita tidak bisa meramalkan bagaimana dia akan bertindak dan menentukan targetnya, ini bisa menjadi sangat berbahaya...",
  ui_story_5022_50221402_32_dialog_content = "PlayerName, kau sudah punya rencana?",
  ui_story_5022_50221402_33_dialog_content = "... Sepertinya dia mengikuti pola saat menghindari serangan kita... Seperti...",
  ui_story_5022_50221402_34_dialog_content = "<color=#e8d9bb>Dor…</color>",
  ui_story_5022_50221402_35_dialog_content = "Apa-apaan kau ini, Caelestite? Cakar naga buas itu bukan untuk dijadikan hiasan!",
  ui_story_5022_50221402_36_dialog_content = "Tak apa! Aku akan mengawasi Caelestite itu.",
  ui_story_5022_50221402_37_dialog_content = "… Bisa kuatasi!",
  ui_story_5022_50221402_38_dialog_content = "Kau membuatku takut! Ada apa?",
  ui_story_5022_50221402_39_dialog_content = "Inti merah itu.",
  ui_story_5022_50221402_40_dialog_content = "Azure juga melihatnya? Ya, dia melindungi inti di depan dadanya itu!",
  ui_story_5022_50221402_41_dialog_content = "Aku baru saja memastikannya dengan tembakan terakhirku tadi.",
  ui_story_5022_50221402_42_dialog_content = "Karena kehilangan penglihatan, dia hanya bisa menghindari serangan dariku dan Zeta dengan mengandalkan insting dan merasakan Lumina.",
  ui_story_5022_50221402_43_dialog_content = "Titik lemahnya sudah ketahuan… PlayerName, Zeta.",
  ui_story_5022_50221402_44_dialog_content = "Ayo habisi dia.",
  ui_story_5022_50221501_1_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5022_50221501_2_dialog_content = "Graaoooooohhh!",
  ui_story_5022_50221501_3_dialog_content = "Kita sudah tahu titik lemahnya, tapi inti itu sepertinya terlindung dengan baik, mustahil bisa dihancurkan.",
  ui_story_5022_50221501_4_dialog_content = "Peluru Nona Azure tidak menembus... Apa yang harus kita lakukan?",
  ui_story_5022_50221501_5_dialog_content = "Yah… Kalau sebutir peluru tak berhasil menembusnya, kita coba sepuluh peluru. Kalau tetap belum berhasil, kita tembakkan seratus peluru ke titik yang sama.",
  ui_story_5022_50221501_6_dialog_content = "Tak seru kalau dia mati begitu saja.",
  ui_story_5022_50221501_7_dialog_content = "Dia… Dia berusaha kabur!",
  ui_story_5022_50221501_8_dialog_content = "Enak saja!",
  ui_story_5022_50221501_9_dialog_content = "Serangan kita berhasil mencederai tulang sayap naga buas itu. Dia tak akan bisa terbang.",
  ui_story_5022_50221501_10_dialog_content = "Kita membutuhkan lebih banyak daya tembak untuk lebih membatasi pergerakannya...",
  ui_story_5022_50221501_11_dialog_content = "Makan nih pelurunya!",
  ui_story_5022_50221501_12_dialog_content = "Azure, akan kubukakan peluang agar kau bisa menembak. Kemarilah!",
  ui_story_5022_50221501_13_dialog_content = "Ah! Jona! Kok mereka bisa setinggi itu? Mmm… Sungguh indah!",
  ui_story_5022_50221501_14_dialog_content = "PlayerName, ikut aku. Ayo kita temui mereka.",
  ui_story_5022_50221501_15_dialog_content = "Hoi, sekarang aku bisa berbuat sesukaku!",
  ui_story_5022_50221501_16_dialog_content = "Enak saja! Lagu terakhirnya jadi jatahku!",
  ui_story_5022_50221501_17_dialog_content = "Hah. Sebelum kau sempat tarik suara, nadaku pasti sudah berhasil duluan meledakkan musuh sampai jadi abu!",
  ui_story_5022_50221501_18_dialog_content = "Bagus! Silakan naik ke panggung!",
  ui_story_5022_50221501_19_dialog_content = "Kalian berdua cepat sekali. Lepidoz dan yang lainnya belum sampai?",
  ui_story_5022_50221501_20_dialog_content = "Kau kan tahu sendiri betapa malasnya kadal kita itu. Belum lagi, dia selalu uring-uringan kalau diajak menempuh perjalanan jarak jauh.",
  ui_story_5022_50221501_21_dialog_content = "Roy sangat lihai membujuknya. Mestinya sebentar lagi mereka sudah sampai di sini.",
  ui_story_5022_50221501_22_dialog_content = "Baiklah. Kalau begitu, mereka tak akan kebagian jatah keseruan membantai naga. Akan kuhabisi naganya dalam hitungan detik saja!",
  ui_story_5022_50221501_23_dialog_content = "Uhh? Kau bisa mengimbangi iramaku, tidak?",
  ui_story_5022_50221501_24_dialog_content = "Sang Kesatria tak akan membiarkan satu pun iblis lolos! Saatnya mengakui dosa-dosamu!",
  ui_story_5022_50221501_25_dialog_content = "Kalaupun mau mengaku dosa, kurasa dia hanya bisa meraung dan melenguh…",
  ui_story_5022_50221501_26_dialog_content = "Situasi di sini makin memanas! Dengan senang hati, senapanku akan jadi irama pengiring!",
  ui_story_5022_50221501_27_dialog_content = "Aduh…",
  ui_story_5022_50221501_28_dialog_content = "Bodoh sekali aku karena berusaha menghabisimu sendirian!",
  ui_story_5022_50221501_29_dialog_content = "Groar…",
  ui_story_5022_50221501_30_dialog_content = "Kali ini, aku… maksudku, kami…",
  ui_story_5022_50221501_31_dialog_content = "Tak akan membiarkanmu lolos hidup-hidup.",
  ui_story_5022_50221502_1_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5022_50221502_2_dialog_content = "<size=45>Gaaraaahhhhhh!</size>",
  ui_story_5022_50221502_3_dialog_content = "Sudah selesai…",
  ui_story_5022_50221502_4_dialog_content = "Apakah kita menang? Saya telah menggunakan semua bom permen saya tetapi tampaknya tidak banyak membantu ...",
  ui_story_5022_50221502_5_dialog_content = "Fyuh… Lumayan juga, Azure. Kalau ada waktu, berkunjunglah ke Squirming Sandworm. Aku yang traktir.",
  ui_story_5022_50221502_6_dialog_content = "Makhluk besar ini langsung hancur jadi abu dalam sekejap. Sayang sekali, sepertinya tak akan ada lagu penutup.",
  ui_story_5022_50221502_7_dialog_content = "Untuk pertunjukan semegah ini, aku tak keberatan duduk bersama para penonton.",
  ui_story_5022_50221502_8_dialog_content = "Kau dan kata-kata manismu itu boleh tinggal di auditorium saja selamanya.",
  ui_story_5022_50221502_9_dialog_content = "Apa katamu tadi? Anginnya terlalu kencang, suaramu tak kedengaran.",
  ui_story_5022_50221502_10_dialog_content = "(Walau sering berkelahi dan bertengkar, sebenarnya mereka sangat akrab.)",
  ui_story_5022_50221502_11_dialog_content = "(Aku penasaran, apa yang akan dilakukan Vice sekarang…)",
  ui_story_5022_50221502_12_dialog_content = "(Tunggu… Kurasa, lagi-lagi kita melewatkan sesuatu yang sangat penting…)",
  ui_story_5022_50221502_13_dialog_content = "<color=#e8d9bb>Dor, dor, dor…</color>",
  ui_story_5022_50221502_14_dialog_content = "Ada yang mendekat… Mobil?",
  ui_story_5022_50221502_15_dialog_content = "Eh! Rakitan besar ini untuk apa?",
  ui_story_5022_50221502_16_dialog_content = "Wow! Kedengarannya tak terlalu bagus, tapi setidaknya mobilnya bisa bergerak…",
  ui_story_5022_50221502_17_dialog_content = "Hei, semuanya!",
  ui_story_5022_50221502_18_dialog_content = "Hah? Apa kami melewatkan hal yang seru?",
  ui_story_5022_50221502_19_dialog_content = "Huh… Saat aku sibuk mendandani mobil ini, Brock berniat membantuku. Namun, dia malah merusakkan Communicator. Kami tak menerima komunikasi apa pun…",
  ui_story_5022_50221502_20_dialog_content = "Aku mengulurkan obeng, persis seperti yang kauminta, lo!",
  ui_story_5022_50221502_21_dialog_content = "Kau sudah sangat bangga dengan tugas seperti itu?",
  ui_story_5022_50221502_22_dialog_content = "Terserah, deh… Kali ini, kau tak akan bisa mengalahkanku, Zeta!",
  ui_story_5022_50221502_23_dialog_content = "…",
  ui_story_5022_50221502_24_dialog_content = "Aku lupa, kompetisinya masih berlangsung!",
  ui_story_5022_50221502_25_dialog_content = "Absolute Zero Witch - Azure!",
  ui_story_5022_50221502_26_dialog_content = "Tak usah teriak-teriak begitu, kesatria.",
  ui_story_5022_50221502_27_dialog_content = "Kau berhasil mengalahkanku dalam menghadapi naga ini, tapi balapannya belum selesai!",
  ui_story_5022_50221502_28_dialog_content = "Aku… aku tak bisa lama-lama menunggumu!",
  ui_story_5022_50221502_29_dialog_content = "<color=#e8d9bb>Duar… Duar! Duar…</color>",
  ui_story_5022_50221502_30_dialog_content = "Mobil Zeta entah bagaimana selamat dari cakar naga jahat itu...",
  ui_story_5022_50221502_31_dialog_content = "Ini bukan saatnya merasa heran, PlayerName.",
  ui_story_5022_50221502_32_dialog_content = "Azure?",
  ui_story_5022_50221502_33_dialog_content = "Maukah kau ikut denganku sepanjang sisa balapan ini dan berkendara ke ujung dunia?",
  ui_story_5022_50221502_34_dialog_content = "Tentu saja…",
  ui_story_5022_50221502_35_dialog_content = "Namun, kenapa kata-katamu justru terdengar sangat ganjil, ya?",
  ui_story_5022_50221502_36_dialog_content = "Para pendengar yang terhormat, seperti komentarku tadi tentang pertarungan seru ini…",
  ui_story_5022_50221502_37_dialog_content = "Ugh!",
  ui_story_5022_50221502_38_dialog_content = "(Hampir saja aku melupakan komentator radio yang supercerewet ini…)",
  ui_story_5022_50221502_39_dialog_content = "Tim Azure dan Tim Zeta mengesampingkan dendam lama dan menyatukan kekuatan dengan bala bantuan dari staf kompetisi ini…",
  ui_story_5022_50221502_40_dialog_content = "Dan dengan indah berhasil mengalahkan Wicked Dragon Hakudoma dari dunia bayangan!",
  ui_story_5022_50221502_41_dialog_content = "Termasuk para anggota Post-Logistics Division 3 tak bersenjata yang bersembunyi di pojokan dan menyiarkan ulang keseluruhan pertarungan ini…",
  ui_story_5022_50221502_42_dialog_content = "Tak ada korban selain naga buas yang tadi diledakkan itu. Selamat, semuanya!",
  ui_story_5022_50221502_43_dialog_content = "Aku tahu, semua kontestan kita pasti kecewa karena melewatkan komentarku yang berapi-api ini.",
  ui_story_5022_50221502_44_dialog_content = "(Anu… Tidak juga, sih…)",
  ui_story_5022_50221502_45_dialog_content = "Jangan khawatir. Aku paham perasaan kalian, kok!",
  ui_story_5022_50221502_46_dialog_content = "Akan kuceritakan ulang seluruh perjalanan ini saat pesta perayaan nanti, khusus untuk kalian!",
  ui_story_5022_50221502_47_dialog_content = "Lebih jelas dengan lebih banyak detail, lebih seru daripada ikut terjun langsung dalam pertarungannya. Terlebih lagi, tarifnya hanya 1.000 Nightium!",
  ui_story_5022_50221502_48_dialog_content = "Para kontestan sudah kembali bersaing, berlomba mencapai garis finis di perbatasan Eternal Night!",
  ui_story_5022_50221502_49_dialog_content = "Akhirnya, Lepidoz berhasil membebaskan diri dari celah itu! Ayo jalan!",
  ui_story_5022_50221502_49X_dialog_content = "Dia benar-benar harus menjaga asupan makannya…",
  ui_story_5022_50221502_50_dialog_content = "Balapan kita terus melaju ke babak final. Kejutan apa yang kira-kira akan dihadirkan para kontestan?",
  ui_story_5022_50221502_51_dialog_content = "Azure, di depanmu!",
  ui_story_5022_50221502_52_dialog_content = "... Zeta! <size=45>Anda tidak akan lolos kali ini! </size><size=40>... Anda... </size><size=35>... Ah... </size><size=30>... Aduh ... </size><size=25>... Aduh ... </size><size=20>...</size>",
  ui_story_5022_50221502_53_dialog_content = "Anu… Sepertinya mobil Brock terguling dari bukit…",
  ui_story_5022_50221502_54_dialog_content = "Sweet Devil dan My Super Dream Team bersaing ketat di jalur zig-zag menuruni lereng Blazing Tooth!",
  ui_story_5022_50221502_55_dialog_content = "Di tikungan kanan pertama, Zeta membanting kemudi ke kiri agar bisa berbelok ke kiri dengan lebih mulus setelah…",
  ui_story_5022_50221502_56_dialog_content = "Manuver ngepotnya sungguh sempurna!",
  ui_story_5022_50221502_57_dialog_content = "Karena terkecoh oleh teknik cemerlang itu, Powerball dari My Super Dream Team menyimpang keluar jalur. Kendaraan mereka butuh perbaikan besar.",
  ui_story_5022_50221502_58_dialog_content = "Sementara itu, Azure cepat menyusul...",
  ui_story_5022_50221502_59_dialog_content = "Kaca depan mobilnya pecah... Apakah aman mengemudi seperti itu?",
  ui_story_5022_50221502_60_dialog_content = "Jaga mulutmu! Ini Sand Dragon, si Rainbow Chaser!",
  ui_story_5022_50221502_61_dialog_content = "Sungguh nama yang luar biasa!",
  ui_story_5022_50221502_62_dialog_content = "Yah, kurasa mobil legendaris ini memang sehebat reputasinya…",
  ui_story_5022_50221502_63_dialog_content = "Baiklah… Bagaimana kalau begini?",
  ui_story_5022_50221502_64_dialog_content = "Ah! Akselerasi mendadak!",
  ui_story_5022_50221502_65_dialog_content = "Kau melakukan terlalu banyak hal tak berguna saat berpindah gigi.",
  ui_story_5022_50221502_66_dialog_content = "Apa katamu?",
  ui_story_5022_50221502_67_dialog_content = "Dengar, ya. Jangan sampai perhatianmu teralihkan oleh kontestan lain, atau keunggulan maupun kelemahan sementaramu. Fokus saja pada dirimu sendiri.",
  ui_story_5022_50221502_68_dialog_content = "(Meski tak bisa lihat apa-apa di luar, aku yakin kedua mobil ini sama hebatnya!)",
  ui_story_5022_50221502_69_dialog_content = "Apa yang Anda tahu? Ini tidak seperti Anda mengalahkan saya sebelumnya ...",
  ui_story_5022_50221502_70_dialog_content = "Hah. Sebelum kau lahir, aku sudah dua kali jadi juara Blazing Tooth Circuit.",
  ui_story_5022_50221502_71_dialog_content = "Aku bisa tahu trik bodoh apa yang kau rencanakan hanya dengan mendengarkan komentar radio...",
  ui_story_5022_50221502_72_dialog_content = "… Dan aku tahu rencanamu untuk menyusulku.",
  ui_story_5022_50221502_73_dialog_content = "Kau… Selama ini kau mengamatiku?",
  ui_story_5022_50221502_74_dialog_content = "Azure!",
  ui_story_5022_50221502_75_dialog_content = "Apa? Kau tak suka apa yang kubilang barusan? Kalau begitu, buktikan bahwa aku salah.",
  ui_story_5022_50221502_76_dialog_content = "Saya pikir hal yang paling penting dalam lomba ini adalah untuk mengalahkan Anda ...",
  ui_story_5022_50221502_77_dialog_content = "Tapi, bagaimana mungkin...",
  ui_story_5022_50221502_78_dialog_content = "Aku belum berhasil mengalahkanmu…",
  ui_story_5022_50221502_79_dialog_content = "Akan tetapi, kenapa aku malah merasa sangat senang?",
  ui_story_5022_50221502_80_dialog_content = "Oh?",
  ui_story_5022_50221502_81_dialog_content = "Sirkuit ini... Percobaan rekor ini... Ini...",
  ui_story_5022_50221502_82_dialog_content = "Kemampuanku belum pernah sebagus ini…",
  ui_story_5022_50221502_83_dialog_content = "*terisak*... Waaaah!",
  ui_story_5022_50221502_84_dialog_content = "Kenapa dia menangis lagi?! Untung tidak ada apa-apa selain dataran pasir di depan...",
  ui_story_5022_50221502_85_dialog_content = "Heh. Aku rindu perasaan ini. Dulu, aku sendiri pun pernah merasakannya.",
  ui_story_5022_50221502_86_dialog_content = "Dibandingkan meraih kemenangan, lebih seru rasanya saat kita berhasil melampaui batas dengan lawan yang setara.",
  ui_story_5022_50221502_87_dialog_content = "Harus kuakui, kau ini pembalap berbakat.",
  ui_story_5022_50221502_88_dialog_content = "Azure…",
  ui_story_5022_50221502_89_dialog_content = "Meski begitu, aku tak berniat menyerah dalam balapan ini.",
  ui_story_5022_50221502_90_dialog_content = "Aku akan mencatatkan rekor baru untuk Blazing Tooth.",
  ui_story_5022_50221502_91_dialog_content = "Jangan terlalu yakin tentang itu!",
  ui_story_5022_50221502_92_dialog_content = "Setelah kau kalah dalam balapan ini, jangan lupa bagikan semua permenmu dan minta maaflah kepada semua orang.",
  ui_story_5022_50221502_93_dialog_content = "Sudah! Jangan kau ingat-ingat lagi! Dasar nenek sihir!",
  ui_story_5022_50221502_94_dialog_content = "Ups… Mana mungkin aku melupakan permintaan terakhir sang kesatria?",
  ui_story_5022_50221502_95_dialog_content = "Hmmmmm! Kali ini, aku tak akan kalah! Kalau aku berhasil mengalahkanmu, kau harus mengajakku dalam misimu!",
  ui_story_5022_50221502_96_dialog_content = "(Menyaksikan balapan mereka, darahku jadi mendidih…)",
  ui_story_5022_50221502_97_dialog_content = "(Inikah yang disebut Sinsa sebagai balapan sejati? Sekarang aku mulai paham.)",
  ui_story_5022_50221502_98_dialog_content = "(Tunggu... Apakah ada sesuatu yang baru saja terbang melewati atas kepala?)",
  ui_story_5022_50221502_99_dialog_content = "Eh…",
  ui_story_5022_50221502_100_dialog_content = "Hah?",
  ui_story_5022_50221601_1_dialog_content = "Aduh… Hmm!",
  ui_story_5022_50221601_2_dialog_content = "Saya harus tetap terjaga untuk melihat para pembalap melintasi garis finis...",
  ui_story_5022_50221601_3_dialog_content = "Kau bisa tidur dengan nyaman. Pundakku siap dijadikan sandaran untukmu.",
  ui_story_5022_50221601_4_dialog_content = "Aku tak bisa lihat apa-apa, tapi aku akan bisa merasakan gerakan angin saat ada orang mendekat.",
  ui_story_5022_50221601_5_dialog_content = "Dawn, apakah masih belum ada tanda-tanda mereka? Panas banget disini, bikin ngantuk...",
  ui_story_5022_50221601_6_dialog_content = "Aku bisa merasakan getaran di kejauhan...",
  ui_story_5022_50221601_7_dialog_content = "Tidak, tunggu... Sesuatu yang besar akan datang...",
  ui_story_5022_50221601_8_dialog_content = "Di langit.",
  ui_story_5022_50221601_9_dialog_content = "Ohh! Dia datang!",
  ui_story_5022_50221601_10_dialog_content = "Ini… Mungkinkah…?",
  ui_story_5022_50221601_11_dialog_content = "Hmm… Ini kan pita pelangi di garis finis. Kenapa ada di sini? Apa ada kontestan yang sudah menuntaskan balapannya?",
  ui_story_5022_50221601_12_dialog_content = "Kendaraan itu sangat besar.... Saya tidak ingat pernah melihat yang seperti itu di garis start.",
  ui_story_5022_50221601_13_dialog_content = "Ah… Ini Soroz milik PlayerName!",
  ui_story_5022_50221601_14_dialog_content = "Sebenarnya… Tadi Odi mengirim pesan bilang bahwa Colossus menyerahkan formulir pendaftarannya di titik periksa di Hot Air Desert…",
  ui_story_5022_50221601_15_dialog_content = "Kukira itu hanya gurauan.",
  ui_story_5022_50221601_16_dialog_content = "Dengan ini saya umumkan bahwa pemenang dari Blazing Rally adalah...",
  ui_story_5022_50221601_17_dialog_content = "<size=45>Soroz dan pilotnya!</size>",
  ui_story_5022_50221601_18_dialog_content = "Setidaknya, kita masih bisa menyaksikan upacara penghargaan yang sudah dinanti-dinantikan itu!",
  ui_story_5022_50221601_19_dialog_content = "Juara balapan ini berhak meminta sesuatu dari Eve!",
  ui_story_5022_50221601_20_dialog_content = "Sang juara, Bu Vice, keinginan untuk ... paket hadiah cara mengajar Sinsa sebuah pelajaran!",
  ui_story_5022_50221601_21_dialog_content = "Hah?",
  ui_story_5022_50221601_22_dialog_content = "Mari kita simak ucapan terima kasih dari Vice!",
  ui_story_5022_50221601_23_dialog_content = "Jangan tinggalkan catatan bertuliskan, \"PlayerName ada di tanganku. Datanglah ke Hot Air Desert jika kau masih ingin bertemu dengannya…\"",
  ui_story_5022_50221601_24_dialog_content = "Lalu, bawa dia!",
  ui_story_5022_50221601_25_dialog_content = "Ini penculikan!",
  ui_story_5022_50221601_26_dialog_content = "Setelah menyampaikan ucapan terima kasih, saatnya juara kita, Vice, menerima hadiahnya!",
  ui_story_5022_50221601_27_dialog_content = "Intinya, aku harus memberikan pelajaran untuk kakakku?",
  ui_story_5022_50221601_28_dialog_content = "TIDAK, Eve, Tolong...",
  ui_story_5022_50221601_29_dialog_content = "Aaaaaaaargh!!",
  ui_story_5022_50221601_30_dialog_content = "Ah oh… Ini di luar dugaan.",
  ui_story_5022_50221601_31_dialog_content = "* Terisak * Saya dapat menerima bahwa kami berlomba untuk seri, tapi ... Di mana itu Vice wanita berasal?",
  ui_story_5022_50221601_32_dialog_content = "Dia beruntung dia adalah teman Caelestite dan ekornya sangat keren...",
  ui_story_5022_50221601_33_dialog_content = "Kalau tidak, aku pasti sudah menantangnya untuk duel!",
  ui_story_5022_50221601_34_dialog_content = "Azure, bisa-bisanya kau tetap tenang dan tak acuh begitu? Memangnya kau tak kecewa?",
  ui_story_5022_50221601_35_dialog_content = "Lo, dia tak berbuat curang, 'kan? Tak sembarang orang bisa menerbangkan Colossus. Kuakui, aku kalah.",
  ui_story_5022_50221601_36_dialog_content = "Lagi pula, aku cukup terhibur melihatmu melompat-lompat seperti tikus berkuping besar.",
  ui_story_5022_50221601_37_dialog_content = "Apa kaubilang?",
  ui_story_5022_50221601_38_dialog_content = "(Saya tidak pernah berpikir begitu Vice akan menerbangkan Soroz ke sini...)",
  ui_story_5022_50221601_39_dialog_content = "PlayerName!",
  ui_story_5022_50221601_40_dialog_content = "Bisa-bisanya kau pergi bersama Sinsa tanpa memberitahuku?",
  ui_story_5022_50221601_41_dialog_content = "Saya mendengar semuanya di radio! Mengendarai mobil balap melintasi gunung berapi... Melawan Eclipsite berkepala sembilan yang tampak seperti naga...",
  ui_story_5022_50221601_42_dialog_content = "Saat aku dan Soroz sampai di ngarai, pertarungannya sudah selesai. Tadi, kami khawatir sekali, tahu!",
  ui_story_5022_50221601_43_option_content = "Aku minta maaf. Aku benar-benar minta maaf!",
  ui_story_5022_50221601_44_dialog_content = "(Sepertinya dia tak ingat pertengkaran kami…)",
  ui_story_5022_50221601_45_option_content = "Maafkan aku, Vice.",
  ui_story_5022_50221601_46_dialog_content = "Aku pikir kau marah padaku...",
  ui_story_5022_50221601_47_dialog_content = "Mulai sekarang, aku janji akan selalu memberitahumu setiap kali aku mau pergi.",
  ui_story_5022_50221601_48_dialog_content = "Hmm... Baik. Aku akan memaafkanmu sekali ini, tetapi hanya karena kamu tampaknya benar-benar menyesalinya!",
  ui_story_5022_50221601_49_dialog_content = "Balapannya seru sekali dan gunung berapinya sangat spektakuler.",
  ui_story_5022_50221601_50_dialog_content = "Aku tak yakin apa aku melanggar aturan karena menerbangkan Soroz. Namun, di Blazing Rally memang tak ada aturan. Iya, 'kan?",
  ui_story_5022_50221601_51_dialog_content = "Aku ini pengemudi ACV kelas kakap. Tahun depan, ajak aku, ya.",
  ui_story_5022_50221601_52_dialog_content = "Vice…",
  ui_story_5022_50221601_53_dialog_content = "Agar hasilnya lebih baik, sepertinya bagus juga kalau kita berlatih bersama melalui permainan.",
  ui_story_5022_50221601_54_dialog_content = "Vice!",
  ui_story_5022_50221601_55_dialog_content = "Lagi pula, program latihan mandiri PlayerName harus dilanjutkan. Seperti biasa, aku akan mengingatkanmu setiap hari!",
  ui_story_5022_50221601_56_dialog_content = "Err ... Saya tidak berpikir itu ...",
  ui_story_5022_50221601_57_dialog_content = "<color=#e8d9bb>Ting…</color>",
  ui_story_5022_50221601_58_dialog_content = "Hai, semuanya! Kalian merindukanku, tidak?",
  ui_story_5022_50221601_59_dialog_content = "A-apa itu?",
  ui_story_5022_50221601_60_dialog_content = "Tak apa. Itu hanya suara radio. Saat pertama kali mendengarnya, aku juga ketakutan.",
  ui_story_5022_50221601_61_dialog_content = "Jomu telah menayangkan iklan selama ini. Dia bahkan tidak menyebutkan bahwa Soroz ikut balapan...",
  ui_story_5022_50221601_62_dialog_content = "Aku berani bertaruh, para pendengar pasti protes karena aku tak menyebutkan kontestan yang bernama Vice.",
  ui_story_5022_50221601_63_dialog_content = "Akan tetapi, sepanjang sejarah, baru pertama kali ini ada Colossus yang ikut dalam Blazing Rally.",
  ui_story_5022_50221601_64_dialog_content = "Batuk... Dan untuk menjaga agar balapan tetap menarik, mungkin ini juga yang terakhir kali.",
  ui_story_5022_50221601_65_dialog_content = "Agar acara ini terasa makin luar biasa, aku tak mau menyia-nyiakan kesempatan langka. Makanya, kusimpan hal ini sebagai kejutan pemungkas!",
  ui_story_5022_50221601_66_dialog_content = "Terima kasih sudah mendengarkan siaran kami untuk Blazing Rally tahun ini. Sampai jumpa di lain waktu. Jangan lupa, isi surveinya!",
  ui_story_5022_50221601_67_dialog_content = "Juga, silakan mampir ke toko saya. Kita punya...",
  ui_story_5022_50221601_68_dialog_content = "Eh, Jomu! Kemarilah! Oleaster sebaskom penuh ini harus kaukupas semua.",
  ui_story_5022_50221601_69_dialog_content = "Roy, aku sedang siaran!",
  ui_story_5022_50221601_70_dialog_content = "Pas sekali. Katakan saja semuanya. Makanan sudah siap.",
  ui_story_5022_50221601_71_dialog_content = "Brock, jangan buka kaleng bubuk protein itu. Bukankah aku sudah memberitahumu... Hei, tidak, jangan menuangkannya ke mulutmu! Fleur, Hentikan dia!",
  ui_story_5022_50221601_72_dialog_content = "Batuk ... Jadi, saya kira Anda semua mendengar ...",
  ui_story_5022_50221601_73_dialog_content = "Saatnya pesta perayaan!",
  ui_story_5022_50221601_74_dialog_content = "Baiklah! Akan kulanjutkan urusan dengan kakakku setelah selesai makan.",
  ui_story_5022_50221601_75_dialog_content = "Belum selesai?",
  ui_story_5022_50221601_76_dialog_content = "Bagaimana? Lebih enak daripada yang sebelumnya, 'kan?",
  ui_story_5022_50221601_77_dialog_content = "Lumayan. Masakanmu… Yang enak hanya makanan penutupnya. Apa menu kita hari ini?",
  ui_story_5022_50221601_78_dialog_content = "Puding Sea Buckthorn kesukaanmu.",
  ui_story_5022_50221601_79_dialog_content = "Dengan Oleaster Puree? Aku suka yang kental dan pekat!",
  ui_story_5022_50221601_80_dialog_content = "Yah, itu tergantung cara Jomu mengupas Oleasternya, sih.",
  ui_story_5022_50221601_81_dialog_content = "Bagaimana menurutmu, PlayerName? Perjalanannya luar biasa, 'kan?",
  ui_story_5022_50221601_82_dialog_content = "Itu pasti melebihi harapan saya. Tunggu, apa... Apa yang baru saja kau beri makan padaku?!",
  ui_story_5022_50221601_83_dialog_content = "Cicipi saja. Satai kadal!",
  ui_story_5022_50221601_84_dialog_content = "Kau sungguh yakin ini bisa dimakan?",
  ui_story_5022_50221601_85_dialog_content = "Tentu saja! Coba lihat Azure!",
  ui_story_5022_50221601_86_dialog_content = "Aku tidak percaya Bu Azure sedang makan ini... dan dengan cara yang elegan...",
  ui_story_5022_50221601_87_dialog_content = "PlayerName, masih ada lagi. Mau cicipi yang ini?",
  ui_story_5022_50221601_88_dialog_content = "Ini kesukaanku, Ular Derik Panggang dengan Keju!",
  ui_story_5022_50221601_89_dialog_content = "Anu… Terima kasih, tapi…",
  ui_story_5022_50221601_90_dialog_content = "Makanlah! Jangan malu-malu.",
  ui_story_5022_50221601_91_dialog_content = "Aku tidak benar-benar... Aku... Oh...",
  ui_story_5022_50221601_92_dialog_content = "Ini baru makanan pembuka. Kita bahkan belum sampai ke hidangan pembuka utama.",
  ui_story_5022_50221601_93_dialog_content = "Pernahkah Anda meneteskan air mata oleh semua makanan yang belum pernah Anda coba sebelumnya? Kasihan...",
  ui_story_5022_50221601_94_dialog_content = "Ini dia. Aku punya Sup Telur Kadal dan Kumbang!",
  ui_story_5022_50221601_95_dialog_content = "Hmm! Marshmallow bakar ini enak sekali! Kalau sudah pulang nanti, kita juga harus mencoba memasaknya!",
  ui_story_5022_50221601_96_dialog_content = "Vice, Anda sudah cukup. Datang dan bantu aku...",
  ui_story_5022_50221601_97_dialog_content = "Azure?",
  ui_story_5022_50221601_98_dialog_content = "Kenapa duduk sendirian di sini? Nanti kau kehabisan hidangan penutup, lo.",
  ui_story_5022_50221601_99_dialog_content = "Kau sudah mencicipinya?",
  ui_story_5022_50221601_100_dialog_content = "Tentu saja. Aku juga mencuri porsi Zeta karena dia terlalu sibuk memamerkan boneka hadiahnya.",
  ui_story_5022_50221601_101_dialog_content = "Biasanya, kau langsung pergi setelah balapan selesai dan tak pernah menghadiri pesta perayaan. Sekarang, akhirnya kautahu apa saja yang selama ini kaulewatkan!",
  ui_story_5022_50221601_102_dialog_content = "Hah. Sudah, hentikan.",
  ui_story_5022_50221601_103_dialog_content = "Hahahah. Sekarang, akhirnya kita hidup berkecukupan. Semua orang bisa makan sampai kenyang. Sumber asupan daging kita kini juga tak melulu kadal bakar.",
  ui_story_5022_50221601_104_dialog_content = "Kurasa ini pantas dibicarakan.",
  ui_story_5022_50221601_105_dialog_content = "Kau masih saja hidup dalam kenangan lamamu seperti pria tua rendahan. Cepat atau lambat, generasi muda akan mengabaikanmu.",
  ui_story_5022_50221601_106_dialog_content = "Wow! Kata-katamu dingin sekali! Saat ini masih masa-masa puncak dalam hidupku, tahu!",
  ui_story_5022_50221601_107_dialog_content = "…",
  ui_story_5022_50221601_108_dialog_content = "… Azure.",
  ui_story_5022_50221601_109_dialog_content = "Menurutmu, apa harapannya akhirnya terwujud?",
  ui_story_5022_50221601_110_dialog_content = "Kenapa kau tiba-tiba menanyakannya? Kaulah yang paling mengenal mantan pemimpin kita.",
  ui_story_5022_50221601_111_dialog_content = "Tolong, jawab saja.",
  ui_story_5022_50221601_112_dialog_content = "…",
  ui_story_5022_50221601_113_dialog_content = "Biar kupikirkan dulu.",
  ui_story_5022_50221601_114_dialog_content = "Operasi penarikan iuran perlindungan dan memulung yang kita lakukan berjalan lancar. Kita juga bisa mengatasi masalah dengan musuh dan konflik internal dalam kelompok kita…",
  ui_story_5022_50221601_115_dialog_content = "Kini, semua orang menikmati hidup nyaman, kebutuhan pangan kita tercukupi, dan kita juga punya pakaian hangat.",
  ui_story_5022_50221601_116_dialog_content = "Untuk sekawanan pecundang yang memutuskan untuk bekerja sama, kurasa keadaan kita cukup bagus.",
  ui_story_5022_50221601_117_dialog_content = "Bagi sebagian besar dari kita, termasuk aku, setelah segala kehilangan yang kita tanggung, situasi ini paling mendekati gambaran keluarga.",
  ui_story_5022_50221601_118_dialog_content = "Seperti rumput liar, dulu kita disiangi. Namun, di tanah tandus, akar kita justru tumbuh subur dan tak terkekang.",
  ui_story_5022_50221601_119_dialog_content = "Di gurun ini, kitalah yang mampu menjaga api yang tak bisa dipadamkan oleh kalangan bangsawan itu. Kitalah yang tetap mampu menangani hal-hal yang tak bisa mereka atasi.",
  ui_story_5022_50221601_120_dialog_content = "Jadi, aku akan bilang bahwa harapan mantan pemimpin kita akhirnya terwujud.",
  ui_story_5022_50221601_121_dialog_content = "… Terima kasih.",
  ui_story_5022_50221601_122_dialog_content = "Meskipun membandingkan kami dengan rumput liar ... Yah, saya kira Anda ada benarnya.",
  ui_story_5022_50221601_123_dialog_content = "Kalau kau ingin dengar puisi, bukan aku orang yang tepat. Sinsa ada di sana, tuh.",
  ui_story_5022_50221601_124_dialog_content = "Kau sama sekali tak berubah. Dia memang lebih muda dari kita, tapi sudah mampu menjadi pemimpin yang cakap.",
  ui_story_5022_50221601_125_dialog_content = "Masa? Pemimpin kita yang cakap itu barusan mengeluh kepada PlayerName di dekat api unggun.",
  ui_story_5022_50221601_126_dialog_content = "Dulu, setiap kali dia melakukan kesalahan konyol, kau juga sering mengacak-acak rambutnya sambil mengejeknya.",
  ui_story_5022_50221601_127_dialog_content = "Heh. Sinsa memang belum terlalu bisa diandalkan. Kemampuan aktingnya masih harus banyak ditingkatkan.",
  ui_story_5022_50221601_128_dialog_content = "Anda membuatnya mengikuti saya, bukan? Zeta menantangku, dan Sinsa Dan PlayerName masuk ke mobilku...",
  ui_story_5022_50221601_129_dialog_content = "Kau sudah tahu Colossus itu akan datang?",
  ui_story_5022_50221601_130_dialog_content = "Eh, kau kan tahu, aku tak secerdas itu.",
  ui_story_5022_50221601_131_dialog_content = "Satu-satunya hal yang agak kupaksakan adalah bahwa kau harus punya rekan dalam balapan tahun ini.",
  ui_story_5022_50221601_132_dialog_content = "Dengan begitu, kau bisa lihat seberapa banyak bocah-bocah itu sudah bertambah dewasa dan seberapa jauh Rediesel Wrench sudah berkembang sementara kau hidup menyendiri.",
  ui_story_5022_50221601_133_dialog_content = "Kemudian satu hal mengarah ke yang lain ...",
  ui_story_5022_50221601_134_dialog_content = "Aku sangat cemas sampai hampir muntah saat kau dan Caelestite terbang dari gunung berapi...",
  ui_story_5022_50221601_135_dialog_content = "Hmm? Aneh sekali rasanya mendengar kata-kata itu dari pria yang dulu mengajariku cara memanfaatkan Eclipsite sebagai bantalan, memanfaatkan lereng pasir sebagai sabuk akselerasi, dan juga menjaga kecepatan saat menikung menuruni lereng bukit!",
  ui_story_5022_50221601_136_dialog_content = "Ahaha. BENAR...",
  ui_story_5022_50221601_137_dialog_content = "Kehadiran naga itu memang sama sekali tak terduga.",
  ui_story_5022_50221601_138_dialog_content = "Semoga naga buas itu kini hanya tinggal cerita saja, hanya untuk Zeta.",
  ui_story_5022_50221601_139_dialog_content = "Namun, pengalaman baru membantu kita untuk bertumbuh. Cedera bukanlah apa-apa bagi anggota Rediesel Wrench.",
  ui_story_5022_50221601_140_dialog_content = "Akan tetapi, dia berhasil kembali dalam keadaan selamat dan tak terluka… Sebentar. Zeta sungguh adalah pahlawan terpilih?",
  ui_story_5022_50221601_141_dialog_content = "Yah, dalam fiksi petualangan, orang tua sang protagonis, seperti aku, biasanya mati mengenaskan saat masih muda.",
  ui_story_5022_50221601_142_dialog_content = "Aduh!",
  ui_story_5022_50221601_143_dialog_content = "Itu tak lucu, tahu. Kalau dengar kata-katamu, Zeta pasti akan menangis kencang-kencang. Tahu sendiri kan seperti apa dia saat menangis. Aku sendiri sudah dua kali menyaksikannya hari ini.",
  ui_story_5022_50221601_144_dialog_content = "Kapan kalian berdua begitu dekat? Lumayan... Bagaimana kalau mengajaknya dalam misi berikutnya?",
  ui_story_5022_50221601_145_dialog_content = "Enak saja! Dia harus menunggu sampai bisa jadi juara Blazing Tooth dulu!",
  ui_story_5022_50221601_146_dialog_content = "Jadi, kau mau ikut balapan tahun depan?",
  ui_story_5022_50221601_147_dialog_content = "... Hmm. Kukira.",
  ui_story_5022_50221601_148_dialog_content = "Bagus sekali! Tugas Exploration Team memang penting. Meski begitu, kita semua perlu sesekali bersantai sedikit dan menjalani hidup sepenuh-penuhnya.",
  ui_story_5022_50221601_149_dialog_content = "Tak usah repot-repot mengajariku tentang itu. Aku sudah sering…",
  ui_story_5022_50221601_150_dialog_content = "Bertemu dengan Jona untuk minum-minum di gudang kedai setempat, lalu berkendara ke kota sebelah untuk minum-minum lagi? Menurutku, itu bukan hobi yang sehat.",
  ui_story_5022_50221601_151_dialog_content = "Hmm…",
  ui_story_5022_50221601_152_dialog_content = "Aku senang kau mau kembali ke jalan yang seharusnya.",
  ui_story_5022_50221601_153_dialog_content = "Anda selalu suka bertindak keras ...",
  ui_story_5022_50221601_154_dialog_content = "Memangnya siapa yang mengajarkannya kepadaku? Kan kau sendiri!",
  ui_story_5022_50221601_155_dialog_content = "... Hah? Apakah begitu?",
  ui_story_5022_50221601_156_dialog_content = "Sudahlah, tak usah repot-repot. Cobalah lebih percaya kepada generasi muda!",
  ui_story_5022_50221601_157_dialog_content = "<color=#e8d9bb>Brak… Duar!</color>",
  ui_story_5022_50221601_158_dialog_content = "…",
  ui_story_5022_50221601_159_dialog_content = "…",
  ui_story_5022_50221601_160_dialog_content = "Waaaahhhh… Percikan api meledak di wajah Regina! Lihat! Hahahah!",
  ui_story_5022_50221601_161_dialog_content = "Brock, wajahmu juga hitam, lo.",
  ui_story_5022_50221601_162_dialog_content = "Barbara! Kau akan menyesali ini!",
  ui_story_5022_50221601_163_dialog_content = "Waow! Bom ini pasti cocok sekali untuk di panggung! Iya, 'kan, Tiny One?",
  ui_story_5022_50221601_164_dialog_content = "Yap, tapi kita perlu menyesuaikan radius ledakannya. Coba saya lihat struktur interiornya...",
  ui_story_5022_50221601_165_dialog_content = "Suka, tidak? Aku masih punya banyak dari seri yang sama! Aku sudah meningkatkan kualitasnya!",
  ui_story_5022_50221601_166_dialog_content = "Kau sebenarnya hanya ingin menyalakan kembang api, 'kan?",
  ui_story_5022_50221601_167_dialog_content = "Bukankah ini akhir yang sempurna untuk pesta perayaan? Bahkan ekor Lepidoz pun bergoyang-goyang karena senang.",
  ui_story_5022_50221601_168_dialog_content = "Apa katamu barusan? Memercayai generasi muda?",
  ui_story_5022_50221601_169_dialog_content = "Astaga, bocah-bocah ini...",
  ui_story_5022_50221601_170_dialog_content = "Hahahah… Menyenangkan juga kalau bisa tetap bersikap kekanak-kanakan.",
  ui_story_5022_50221601_171_dialog_content = "Caelestite! Kau memakan hidangan penutupku, ya?",
  ui_story_5022_50221601_172_dialog_content = "Kau memang pernah sekali menyelamatkan nyawaku, tapi aku tak akan mengampunimu karena memakan hidangan penutupku!",
  ui_story_5022_50221601_173_dialog_content = "Itu bukan aku! Itu Nona Azure... Dia...",
  ui_story_5022_50221601_174_dialog_content = "Mana Azure? Azure!",
  ui_story_5022_50221601_175_dialog_content = "Aduh! Rekan timmu yang imut itu sedang dalam masalah. Kau yakin tak mau membantunya?",
  ui_story_5022_50221601_176_dialog_content = "Jangan remehkan PlayerName.",
  ui_story_5022_50221601_177_dialog_content = "Bisa saja dia akan membawa perubahan ke dunia ini.",
  ui_story_5022_50221601_178_dialog_content = "Kisah sang Caelestite tak akan berakhir hanya gara-gara puding.",
  ui_story_5022_50221601_179_dialog_content = "Aku yakin itu.",
  ui_story_5022_50221601_180_dialog_content = "Ya, kata-katamu barusan sungguh mengesankan. Namun, tetap saja Caelestite itu dikejar-kejar akibat ulahmu.",
  ui_story_5022_50221601_181_dialog_content = "Azure… Roy!",
  ui_story_5022_50221601_182_dialog_content = "Kemarilah! Saatnya menyalakan kembang api!",
  ui_story_5022_50221601_183_dialog_content = "3——2——1——!"
}
return config
